const DATA=[{"n":1,"title":"The old sailor","items":[{"t":"h","s":"The old sailor comes to The Admiral Benbow"},{"t":"p","s":["I remember him as if it were yesterday.","He came slowly to the door of The Admiral Benbow Inn, his sea-chest following behind him on a hand-cart.","He was a strong, heavy man with long hair and an old, blue coat.","His hands were rough and black with dirt and he had a long scar from a sword across one cheek.","He knocked on the inn door and, when my father opened the door, called roughly for a glass of rum.","‘This is a pleasant, quiet bay for an inn,’ he said and looked slowly round him at the cliffs and our inn.","‘Here, mate!’ he cried to the man with the hand-cart, ‘help me to get my chest inside.’","He continued, ‘Rum and simple food is what I want.","And that cliff up there where I can watch the ships.","You can call me Captain.","Oh, I see what you want,’ he said with a fierce look, and threw down three or four gold coins in front of him.","All day he was around the bay, or up on the cliffs with his telescope.","All evening he sat in the inn by the fire drinking rum.","Mostly he did not speak when spoken to, but looked up suddenly and angrily, and we learnt to stay away from him.","He was very nervous of other sailors who came to the inn.","One day he quietly promised to give me a silver fourpenny coin every month if I would ‘keep an eye open for a seaman with one leg’.","The captain often drank too much rum and sang his old, wild sea-songs.","Then he used to hit his hand down hard on the table for silence, before telling his frightening stories of the sea.","They were about hangings, storms at sea and terrible crimes.","During the months that the old sailor stayed with us, my father became very ill.","One day Dr Livesey came to see him, and before he left, the smart, bright doctor sat in the same room as our dirty, heavy sailor, who suddenly started his usual song: ‘Fifteen men on the dead man’s chest – Yo-ho-ho, and a bottle of rum!","Drink and the devil had done for the rest – Yo-ho-ho, and a bottle of rum!’ Later on, he banged his hand on the table, which we all knew was a call for silence.","Everyone, apart from Dr Livesey, stopped talking.","A few moments later the captain cried, ‘Silence!’","‘If you were talking to me, sir,’ said Dr Livesey.","‘I have one thing to say – if you go on drinking so much rum, then the world will soon be free of a very dirty old scoundrel!’","The captain jumped to his feet and took a knife out of his pocket.","The doctor did not move, but spoke slowly.","‘I am a man of the law – a magistrate – as well as a doctor.","If you do not put that knife away, you will go to the next court, and will be hanged.’","A few uncomfortable moments passed, until the captain finally put the knife in his pocket and sat down heavily."]},{"t":"h","s":"Black Dog"},{"t":"p","s":["It was early one January morning, while the captain was out at the beach with his telescope, that the inn door opened and a man stepped in who I had never seen before.","He wore a sword in his belt, his skin was an unpleasant colour and two fingers were missing from his left hand.","He sat down at a table, then called me closer.","‘Is this here table for my mate, Bill?’ he asked, a strange look on his face.","I said that the table was for a man who we called the captain.","‘Well,’ he said, ‘my mate would be called the captain, probably.","He has a cut on one cheek and he’s very pleasant when he’s drunk, is my mate, Bill.","So, is he here?’ I told him he was out walking.","‘Well,’ he replied, ‘you and me’ll just get behind the door, and we’ll give Bill a little surprise.’","He made me hide and I became very worried when I saw him take out his sword.","At last, the captain came in and walked towards his breakfast table.","‘Bill,’ said the stranger.","The captain turned to face us.","His face turned white.","‘Come, Bill, you know me – your old shipmate – surely,’ said the man.","The captain’s eyes opened wide and he said, ‘Black Dog!’","‘That’s right, Black Dog, come to see his old shipmate Billy.","Ah, we’ve seen some times together since I lost these two fingers,’ he said, holding up his hand.","I brought them some rum and then left the room.","At first I could only hear low voices, but then they became louder.","Then, all of a sudden, there was loud swearing and I heard something crash to the floor.","There was the sound of metal against metal, and then a cry of pain.","The next moment, I saw Black Dog running away, with the captain close behind.","They were both carrying swords and Black Dog had blood streaming from his shoulder.","But Black Dog was faster than the captain and he was soon outside and over the hill.","The captain came back into the inn and said, ‘Jim, rum!’ But as he spoke, he started to fall against the wall.","‘Rum,’ he repeated.","‘I have to get away from here.’","I ran to get the rum.","While I was in the next room, I heard a crash.","I ran in and found him lying on the floor.","The captain was breathing very loud and hard.","His eyes were closed and his face was a horrible colour.","My mother had now come downstairs, but we did not know what to do.","At that moment, Dr Livesey came in, on his way to see my father.","‘He’s made himself very ill with too much rum, but I’ll do my best to save his life,’ said the doctor when he had looked at him.","The doctor pulled off the captain’s shirt to start his work and I saw several tattoos on the captain’s arm.","They read, ‘Here’s luck,’ ‘A fair wind,’ and ‘Billy Bones’.","It was some time later before the captain opened his eyes.","First he looked around the room, and then he tried to get up, crying, ‘Where’s Black Dog?’","‘There’s no Black Dog here,’ replied the doctor.","‘You’ve been drinking rum and you’ve had a stroke.","Now, what I have to say to you is this.","One glass of rum won’t kill you.","But if you take one, you’ll take another, and if you don’t stop, you’ll die.","Come on, now.","I’ll help you to your bed.’","We managed to get him upstairs and onto his bed.","‘He should lie in bed for a week,’ said the doctor as soon as we had closed the door.","‘That’s the best thing for him, and you.","But another stroke would finish him off.’"]},{"t":"h","s":"The black spot"},{"t":"p","s":["At about midday I went to see the captain.","He seemed both weak and excited.","‘Jim,’ he said, ‘every month I’ve given you a silver fourpenny.","You’ll bring me a little drink of rum, now, won’t you?’","‘The doctor …’ I began.","He started to swear and then said, ‘What does that doctor know about life at sea?","I’ve lived on rum, I tell you.","Your doctor said himself one glass wouldn’t hurt me.","I’ll give you a golden guinea for some, Jim.’","‘I want what you owe my father.","That’s all,’ I said (for he had been very slow to pay us).","‘I’ll get you one glass, and no more.’","When I brought it to him, he took it quickly and drank it down.","‘Aye,’ he said, ‘that’s better.","How long do I have to lie here?’","‘A week, at least.’","I said.","‘I can’t do that!’ he cried.","But he was too weak to get up, and he lay back for a while in silence.","‘Jim,’ he said after a time, ‘It’s my old sea-chest they want.","If I can’t get away, you go to – well, yes – you go to the doctor.","Tell him to bring the magistrates here to The Admiral Benbow to get all of old Flint’s crew, all of ’em that’s left.","I was Flint’s first mate and I’m the only one that knows the place.","He gave it to me when he was dying.","But don’t tell the doctor unless they get the black spot on me, or unless you see that Black Dog, or the sailor with one leg.’","‘But what is the black spot, Captain?’ I asked.","‘That’s a sort of warning, mate.","If I get the black spot, it means they are coming to get me and what I’ve got.","Keep your eyes open, Jim, and I’ll give you half of everything, I promise you.’","What I would have done if everything had gone well I do not know.","But my poor father died quite suddenly that evening.","All of the neighbours came to visit and there was a lot to arrange, so I was too busy and upset to think of the captain.","The following day the captain came downstairs, ate a little and got himself some rum.","On the night before we buried my father he was as drunk as ever.","He sat at the table with his sword ready in front of him, singing his ugly old sea-songs.","But he was still very weak, and seemed to be getting worse, not better.","Several days later, on a cold, foggy afternoon, I was standing at the door full of sad thoughts about my father.","As I stood there I saw someone coming slowly along the road.","The man was blind – he was walking along tapping a stick in front of him.","He wore a cloth over his eyes and nose and was bent over.","I had never in my life seen such a terrible-looking man.","He stopped a little way from the inn, and he said in a loud voice, ‘Will any good man tell a poor blind man where he is?’","‘You are at The Admiral Benbow,’ I replied.","‘Give me your hand, young friend, and lead me in,’ he said.","I held out my hand and the horrible man held it hard.","He pulled me up close to him and said, ‘Now, boy.","Take me in to the captain.’","‘Sir,’ I said, ‘I can’t.","The captain is not what he used to be.","He sits with his sword ready …’ ‘Take me in or I’ll break your arm,’ he said and pulled my arm roughly.","It was the hardest, coldest voice I had ever heard.","I was so frightened that I led him into the room where the captain was sitting.","The poor captain lifted his head, and it was easy to see that he was very frightened.","‘Now, Bill, sit where you are,’ said the man.","‘Hold out your left hand.","Boy, take his left hand and bring it near my right hand.’","We both did what we were told, and I saw him put something into the captain’s hand, which quickly closed on it.","The blind man suddenly went out of the door.","I stood without moving and heard his stick go tap-tapping down the street.","The captain looked down into his hand.","‘Ten o’clock!’ he cried.","‘I’ve got six hours,’ he said and tried to stand up.","But he suddenly put his hand to his neck, and then, with a strange sound, fell face first onto the floor.","I shouted to my mother, but it was too late.","The captain was dead."]}]},{"n":2,"title":"Everything changes at the inn","items":[{"t":"h","s":"The sea chest"},{"t":"p","s":["I told my mother everything.","We were very frightened and did not know what to do.","If I went to see Dr Livesey as the captain had told me to do, I would have to leave my mother alone, and her safety was my priority.","On the other hand, it also seemed too dangerous for us to stay at the inn.","At last we decided what we ought to do.","First we needed to go to the nearest village to get help, then we would come back to open the chest and take the money the captain owed us before anyone else came for it.","But when we got to the village no one wanted to return with us to The Admiral Benbow.","Some of the men had heard of the terrible Captain Flint, and others had seen strange men on the road that day, as well as a ship in a nearby bay.","They were all too frightened to leave their houses.","We decided to go back to the inn alone to carry out our plan.","One man gave me a gun in case we were attacked, and a boy said he would ride to the doctor’s house to get help.","When we arrived back at the inn, nothing had changed.","We locked the door, lit a candle and, holding each other’s hands, we walked into the room where the captain lay.","I went down on my knees.","On the floor near the dead man’s hand was a small, round, black piece of paper – the black spot.","I picked it up.","Written on one side were the words, ‘You have till ten tonight’.","Luckily for us it was still only six o’clock.","I anxiously looked in his pockets for the key to the chest, but I found nothing.","Then, finally, I saw it on a piece of string around his neck.","I cut the string and we went quickly upstairs to find the chest.","It was old and well-used like any other sailor’s chest and it had the letter ‘B’ burnt on it.","‘Give me the key,’ said my mother, and although the lock was difficult to open she turned it and opened the lid in a moment.","At the top there was a carefully folded suit.","Under that, there were too many things to count – some pistols, a large piece of silver, an old Spanish watch and many more small objects.","At the very bottom of the chest lay a packet covered in cloth, and a heavy bag that held gold coins.","‘Let’s take what he owed us,’ said my mother, ‘and not a penny more.’","And she began to count out the coins.","It was a long, difficult job because the coins were all of different countries and sizes.","When we had counted out about half of our money, I suddenly heard the tap-tapping of the blind man’s stick on the road.","We sat holding our breath.","Then the stick banged on the inn door, and we heard the handle being turned – and then silence.","At last, the tapping started again, but this time it became quieter and quieter as the man walked away.","Not long after that, we heard a whistle blow far up on the hill.","That was enough for us.","‘I haven’t counted enough to pay his bill, but I’ll take what I have,’ she said, jumping to her feet.","‘And I’ll take this instead of the rest of the money,’ I said, picking up the packet covered in cloth.","We went as quickly as we could down the dark stairs and out onto the road.","We were on our way back to the village when we heard the sound of someone running, first in the distance and then getting nearer.","‘You must take the money and run on.","I feel I’m going to faint,’ my mother said, and then she fell on my shoulder.","Luckily, we were near a little bridge, and with some difficulty, I managed to pull her under it."]},{"t":"h","s":"The last of the blind man"},{"t":"p","s":["Moments later, seven or eight men came running towards the inn.","In front, there were three men holding hands.","Then, in the weak moonlight, I could see that in between the other two was the blind man.","‘Go in!’ he cried.","Several men went to the door of the inn and, finding the door unlocked, went inside.","Two of them stayed outside with the terrible blind man.","There was a moment’s silence, then a cry of surprise, and a voice shouting from the house, ‘Bill’s dead!’","The blind man swore.","‘Look in his pockets!","Then find the chest!’ he cried.","A little while later, one of the upstairs windows was thrown open and someone shouted out to the blind man, ‘Pew, someone’s been in the chest.’","‘Isn’t it there?’ Pew asked angrily.","‘The money’s here, but there’s none of Flint’s writing,’ the man replied.","‘It’s these people of the inn – it’s that boy.","Why didn’t I take his eyes out?’ cried the blind man, Pew.","‘They were here earlier – the door was locked when I came.","Go and find them.’","Just then came the whistle we had heard before, and it came from the direction of the village.","‘Dirk’s blown the whistle again!’ said one of the men.","‘That means he’s seen someone coming.","Let’s leave!’","‘Keep looking!’ Pew shouted angrily.","‘The boy and his mother can’t be far away.","We almost have it, and you want to run away?","You’ll be as rich as kings if we find it!’","‘Hang it, Pew.","Why don’t we go?","We’ve got the bag of money!’ said one.","Pew started trying to hit the men with his stick.","As the fight went on, the sound of horses galloping came from the top of the hill.","The sailors quickly stopped fighting and ran away, leaving Pew anxiously tapping up and down the road alone.","Just then, four or five horses appeared in the moonlight, galloping down the hill towards the inn.","Pew screamed and, not knowing in which direction to go, ran right under the first horse.","Down he went with a terrible cry.","The horses came to a stop and I recognized the boy that had gone from the village to get Dr Livesey.","With him were several law officers who he had met on the way to the doctor’s house.","Pew was dead.","We went back to find my mother and carry her to the village.","There she recovered well after a little while.","The law officers rode on to the nearby bay, but they were too late – the strange ship had already gone, and probably the rest of the pirates with it.","When the leader of the men, Mr Dance, returned from the bay, I told him everything that had happened.","‘They wanted something more than the money, you say?","Well then, Hawkins, what on earth were they trying to find?’ he asked me.","‘I believe I have what they want in my pocket,’ I replied, ‘and I would like to get it to Dr Livesey, so that it will be safe.’","‘Of course, boy,’ he said, ‘Yes, I shall go there myself and tell him all about this.","Why don’t you come with me?’"]},{"t":"h","s":"The Captain’s papers"},{"t":"p","s":["We found Dr Livesey at the Hall, where he was having dinner with the squire.","A servant led us through the great house to the library, where both men were smoking their pipes next to the fire.","The squire was a tall, strong man with eyebrows that were very black and moved a lot when he spoke.","‘Come in, Mr Dance,’ he said in a loud voice.","‘Good evening,’ said the doctor.","‘What brings you both here today?’","Mr Dance stood up and told his story, and the two gentlemen listened with surprise and interest.","‘And so, Jim,’ said the doctor when Mr Dance had finished, ‘you have the thing they wanted?’","‘Here it is, sir,’ I said and gave it to him.","He held it for a moment and then put it carefully in his pocket.","‘Squire,’ he said, ‘Mr Dance will go home, but I think Hawkins should stay at my house tonight and we should give him dinner.’","And so I ate a wonderful dinner at the Hall while we talked.","‘I’ve heard of this man Flint,’ said Mr Trelawney, the squire.","‘He was the most dangerous pirate that ever sailed.","I’ve seen his ship, with terrible eyes painted on its sails.’","‘But did he have money?’ asked the doctor.","‘Money!’ cried the squire.","‘Haven’t you heard the story of his treasure?","What were those scoundrels looking for if not money?’","‘Just tell me,’ replied the doctor, ‘if I have information in my pocket about where Flint buried his treasure, what does that mean we should do?’","‘What does it mean?’ cried the squire, ‘If we have the information you’re talking about, it means that I will go to Bristol and buy a ship, and we’ll find that treasure if we have to spend a year looking for it.’","‘Very well,’ said the doctor and put the packet on the table in front of him.","‘Now then, if Jim agrees, I will open the packet,’ and he started to open the cloth that covered it.","Inside were two things – a book and a roll of paper.","The book was full of names, numbers and dates.","‘This is Bill Bones’ account book!’ cried the squire.","‘The names are the ships that he sank, and the numbers show the money he took from them.’","The doctor carefully opened the rolled-up paper and we saw a map of an island, complete with latitude and longitude, names of hills and bays, a large hill in the centre named ‘The Spy-glass’, and every detail that a captain would need to bring a ship in safely.","There were three red crosses – one was in the south-west and had these words next to it: ‘Bulk of treasure here.’","The second red cross showed where some silver was buried, and the third some weapons.","There were detailed notes and instructions on the back of the map.","I did not understand the map, but the squire and Dr Livesey were very excited.","‘By tomorrow evening I shall be in Bristol,’ said the squire.","‘Then, in three weeks’ time we’ll be sailing the best ship, sir, with the most efficient crew in England.","Hawkins, you will be a cabin-boy, and you, Livesey, the ship’s doctor.","I will be the admiral!","We’ll take my men, Redruth, Joyce and Hunter, too.","We’ll have good winds, a quick voyage, and no difficulty at all in finding the treasure, and more money than we can imagine.’","‘Trelawney,’ said the doctor.","‘I’ll go with you, and I think Jim will too.","But there’s only one man I’m afraid of.’","‘And who’s that?’ asked the squire with a troubled look on his face.","‘You,’ replied the doctor, ‘because you can’t keep a secret.","We’re not the only men who know about this document.","Those men who attacked the inn tonight are not far away, I’m sure.","And, according to Jim, they want that money.","We must be very careful until we are on our way, and we must not say a word about this map to anyone.’","‘Livesey,’ replied the squire, ‘you have a point.","I’ll be as silent as the grave.’"]}]},{"n":3,"title":"The sea-cook","items":[{"t":"h","s":"I go to Bristol"},{"t":"p","s":["It took longer than three weeks until we were ready to go to sea.","A ship was being prepared by the squire, and Dr Livesey had been called away to London.","During that time I lived at the Hall with old Tom Redruth, and spent hours looking at the map, imagining every small detail and dreaming about what would happen when we finally got to the island.","And so the weeks passed until one fine day a letter arrived."]},{"t":"h","s":"Old Anchor Inn"},{"t":"p","s":["Bristol,"]},{"t":"h","s":"March 1st"},{"t":"p","s":["Dear Hawkins, The ship has been bought and is ready to go to sea.","What a ship!","She is easy to sail, weighs two hundred tonnes and her name is ‘Hispaniola’.","My old friend, Blandly, helped me to get her.","He worked so hard for me, and so, I must say, did everyone else in Bristol, as soon as they heard where we were going – to find the treasure, I mean.","Finding the crew was a problem at first, and I could only find a few men.","But then, by luck, I met an older sailor.","He has an inn, so he knows all the sailors in Bristol.","He was ill for a while, but now he wants to work as a ship’s cook to get back to sea again.","Long John Silver, he is called, and he has lost a leg.","Poor man.","I told him immediately that he would be our ship’s cook.","Well, I thought I had just found a cook, but in addition I had found a whole crew.","He had soon found us a group of the toughest old sailors.","He then got rid of the weakest two of the six or seven men I had already employed.","I am very well, but I won’t be happy until we are at sea, so both you and Redruth must come to Bristol tomorrow."]},{"t":"h","s":"John Trelawney"},{"t":"p","s":["P.S.","I forgot to tell you that Blandly (who will send a ship to look for us if we don’t come back by the end of August) has found us a captain.","He is a little too serious, but in every other way he is an excellent man – a real treasure.","‘Trelawney has been talking to people,’ I said to Redruth.","‘Dr Livesey will not like that.’","But I was very excited to hear the news that the ship was ready.","The next day I said goodbye to my dear mother and the little bay where I had lived since I was born, and then Redruth and I left for Bristol in the evening.","It was early the next morning when we arrived in the city and walked down to the docks to meet Trelawney.","There were ships of all shapes, sizes and nationalities all along the quays.","Sailors were singing at their work, some below and others high up in the rigging.","Then suddenly, in front of a large inn, I saw Squire Trelawney, dressed like a smart sea-officer.","‘Here you are,’ he cried, ‘and the doctor came last night from London.","Bravo!","The ship’s crew is complete.","We sail tomorrow!’"]},{"t":"h","s":"At The Spy-glass inn"},{"t":"p","s":["After breakfast, the squire asked me to take a note to Long John Silver.","He told me to go to The Spy-glass – an inn at the other end of the docks.","I went gladly because I was pleased to be able to see the busy port and all the ships again.","The inn was full of loud sailors, and I was almost too frightened to go inside.","As I was waiting at the door I saw a man as he came out of a side room, and I thought he must be Long John Silver.","His left leg was cut off near the top, and under his left shoulder he carried a crutch, on which he moved about easily.","He was very tall and strong, with an intelligent face, and he was serving the people at the tables with a smile.","From the very first time I had read about Long John Silver in Trelawney’s letter, I had been frightened that he might be the one-legged sailor that the captain had told me about.","But one look at this man was enough.","I had seen the captain, Black Dog, and the blind man Pew, and I thought I knew what a pirate was like – very different from this clean and pleasant inn-keeper.","I walked closer to him, held out the note and said, ‘Mr Silver, sir?’","‘Yes, my boy.","And who are you?’ he answered.","I gave him the note.","‘Oh!’ he said, quite loudly and seeming surprised.","‘You’re the new cabin-boy.","I’m very pleased to meet you.’","Just then I noticed one of the men sitting on the other side of the room as he suddenly stood up and walked to the door.","I recognized him at once.","‘Hey!’ I shouted.","‘Stop him!","It’s Black Dog – he’s one of the pirates!’","‘I don’t care who he is,’ cried Silver.","‘But he hasn’t paid for his drinks.","Harry, run and catch him.’","A man near the door jumped up and ran out of the inn after him.","‘Who did you say he was?","A pirate?","In my inn!","I can’t believe it!’ said Silver, who was now very excited.","‘Morgan!’ he called to a man sitting in the bar.","‘You were drinking with him.","You’ve never seen him before, have you?","You didn’t know his name, did you?’","I had become worried when I found Black Dog at The Spy-glass, and I watched the cook carefully.","But he was too ready, and too clever for me.","He laughed and joked with me, and said that I was a clever boy.","By the time Harry had come back empty-handed and had been shouted at loudly by Silver, I felt sure that Silver was an honest man.","A little while later, he took me back to see Trelawney and we walked by the quays together.","He was very interesting, and told me all about the different ships that we passed – their rig, their weight and nationality and where they would sail.","Long John excitedly told the squire and the doctor the whole story.","The two gentlemen said it was a shame that Black Dog had escaped, but we all agreed that nothing could be done.","As Long John left, the two gentlemen thanked him for his trouble.","‘Everyone on board by four this afternoon.’ shouted the squire after him.","‘What a wonderful man!’ said the squire and then turned to me.","‘Now, come with us, Hawkins, and we’ll see the ship.’"]},{"t":"h","s":"Captain Smollett"},{"t":"p","s":["As we climbed aboard the Hispaniola we were met by the new ship’s mate, Mr Arrow, a brown old sailor with earrings in his ears.","He and the squire were very friendly, but I soon noticed that things were not the same between the squire and the captain.","Captain Smollett seemed angry with everything on board and wasted no time in coming to the cabin to tell the squire.","‘Sir, I don’t like this voyage, I don’t like the men, and I don’t like my officer.","That’s short and sweet,’ said the captain.","‘Perhaps, sir, you don’t like the ship?’ asked the squire, who was clearly angry.","‘That I can’t say, since I haven’t seen her tried,’ replied the captain.","‘She seems a good ship, but I can’t say any more.’","At this moment Dr Livesey spoke.","‘Wait a minute,’ he said.","‘That isn’t at all helpful.","I’d like to hear an explanation of what the captain has said.","You don’t, you say, like this voyage.","Now, why?’","‘I took this job under what we call ‘sealed orders’ – that is, I agreed to sail the ship without first knowing where we were going,’ said the captain.","‘But now I find that all the crew know more than I do.","Next,’ continued the captain, ‘I hear, from my own crew, that we are going to find treasure.","Treasure is dangerous, and I don’t like treasure voyages, especially when they are secret.’","‘I understand what you are saying, and I must say, it’s true enough,’ replied Dr Livesey.","‘You say you don’t like the crew.","Are they not good sailors?’","‘I don’t like them, sir,’ replied Captain Smollett.","‘And I wasn’t able to choose them myself.’","‘And you don’t like Mr Arrow?’ continued the doctor.","‘I don’t, sir.","I believe he’s a good sailor, but he’s too friendly with the crew to be a good officer.’","‘Well, Captain,’ said Doctor Livesey, ‘then tell us what you want.’","‘There are two things,’ said the captain.","‘First, the gun powder and weapons should be put under the cabin near the stern of the ship, and not where they are now.","And second, the crew you have brought with you should sleep at the back near the cabin as well.","And there has been too much talk already.’","‘Far too much,’ agreed the doctor.","‘It is said that you have a map of an island,’ said Captain Smollett, ‘that there are crosses on it to show where the treasure is, that the island lies …’ and then he gave the exact latitude and longitude.","‘I never told anyone that!’ cried the squire.","‘The crew know it,’ said the captain.","‘Livesey, that must have been you or Hawkins,’ cried the squire.","‘It doesn’t matter who it was,’ replied the doctor.","‘Well,’ continued the captain, ‘I don’t know who has this map, but it must be kept secret even from me and Mr Arrow.’","‘I see,’ said the doctor.","‘You want us to keep this matter secret, and to make a garrison of the stern part of the ship, with my friend’s own people, and provided with all the arms and powder on board.","You fear a mutiny.’","‘I didn’t say that,’ said Captain Smollett.","‘I believe Mr Arrow is an honest man, and some of the others, too.","But it is my job to make sure that the ship, and every man on it, is safe.","All I am asking you to do is to take every care, or let me leave the ship.","And that’s all.’","The doctor and the squire agreed to Captain Smollett’s suggestions, and then the captain left the cabin.","‘Trelawney,’ the doctor then said, ‘I am surprised, but you have managed to get two honest men on board with you – that man and John Silver.’"]}]},{"n":4,"title":"The voyage","items":[{"t":"h","s":"The voyage begins"},{"t":"p","s":["All night we were very busy getting the ship ready to sail.","The sun was just coming up when everyone moved to their places, ready to leave the docks.","‘Sing us a song,’ shouted one of the crew to Long John.","‘The old one,’ cried another sailor.","And Long John Silver, who was standing nearby, started to sing the song I knew so well: ‘Fifteen men on the dead man’s chest –’ And then the whole crew sang: ‘Yo-ho-ho, and a bottle of rum!’","And at the last word the sailors pushed the capstan-bars hard.","It was an exciting moment, and the song carried me back to The Admiral Benbow in a second, and I seemed to hear the old captain singing too.","But soon the anchor was up and hanging at the bows.","The sails started to fill with wind and before I could lie down for an hour’s sleep, the Hispaniola had begun her voyage to the Island of Treasure.","I am not going to tell you every detail of that voyage – the ship proved to be a good ship, the crew were experienced sailors and the captain certainly knew what he was doing.","But by the time we arrived at Treasure Island, two or three things had happened which I should tell you about.","First, Mr Arrow was worse than the captain had feared.","He had no control over the crew and people did what they liked.","Then, after a day or two at sea, he began to act like a man who was drunk.","Again and again he was sent below deck because he could not work properly.","But no one knew where he could be getting the drink.","No one was very surprised, or sad, therefore, when one dark, stormy night he disappeared and was not seen again.","‘He must have fallen over the side of the ship,’ said the captain.","During the voyage I got to know Long John Silver and see him at work.","Although he only had one leg, he moved about on board with amazing ease.","The crew did what he told them to and seemed to like him.","He was friendly to everyone and was always glad to see me in the galley, which he kept very clean.","‘Hawkins, come and have a chat with John,’ he used to say.","‘Here’s Captain Flint, named after the famous pirate,’ and he pointed to the parrot he kept in a cage in the corner of the galley.","And the parrot used to say, again and again, ‘Pieces of eight!","Pieces of eight!’ until John threw a cloth over the cage.","‘It’s been everywhere, that old parrot.","It says ‘pieces of eight’ because it was there when the ships were pulled up from the seabed with three hundred and fifty thousand of those coins on board,’ explained the cook."]},{"t":"h","s":"What I heard in the apple barrel"},{"t":"p","s":["Before we arrived at Treasure Island, something happened that dramatically changed what I thought of Long John Silver.","On the deck of the ship was a barrel of apples.","One evening, when I had finished work, I went up on deck to get an apple.","I climbed into the barrel and found that there were hardly any apples left.","But sitting down there in the dark, with the gentle movement of the ship, I must have fallen asleep.","Suddenly, I woke up as someone sat down heavily against the barrel.","Then the man began to speak.","It was Silver’s voice.","Frightened, I sat and listened.","‘No.","Flint was the captain, not I,’ said Silver.","‘I looked after the supplies.","I lost my leg at the same time that Pew lost his eyes.","But later on I saw Flint’s ship so heavy with gold I thought that it would sink.’","‘Ah!’ said another voice – the voice of Dick, the youngest man on board, ‘He was the best of them all, was Flint!’","‘Well, I got two thousand from Flint.","That’s not bad for a simple sailor, is it?","I put it all safe in the bank.","It’s all about saving.","But where are Flint’s men now?","Most of ’em are on board this ship, and they’re glad to earn a bit of money,’ said Silver.","‘You see, I save my money, whereas those other gentlemen of fortune spend it on rum and a good time.","Then they have to go to sea again, when they have nothing left but their shirts.","But I’m fifty now, and when I finish this voyage, I’ll be able to live somewhere for the rest of my life.","‘But you can’t go back to Bristol after this,’ said the other voice.","‘Right, and my wife is getting all my money now.","She’s selling The Spy-glass and she’ll meet me somewhere away from Bristol when I’m finished,’ explained Long John.","‘I like my job much better now I’ve talked with you,’ said the young man.","‘You’re a brave boy, and clever too,’ answered Silver.","‘And I’ve never seen a better gentleman of fortune.’","By this time I had begun to understand that when Silver said ‘gentlemen of fortune’ he meant pirates, and I knew that he had just corrupted one of the honest men on the ship.","A few minutes later, Silver called another man over to the barrel.","‘Dick’s with us,’ said Silver.","‘Oh, I knew he would be,’ replied the voice of the coxswain, Israel Hands.","‘But when are we going to do something?","I want their food and drink,’ he said.","‘Now,’ started Long John Silver, ‘Captain Smollett is an excellent sailor, and the doctor and the squire have the map somewhere secret, which means I don’t know where it is, do I?","So I say that we wait until they’ve found the treasure, and they’ve helped us to get it on board.’","‘But we’re all sailors on board this ship!’ cried Israel.","‘We don’t need Smollett and the others.’","‘We can sail the ship,’ said Silver angrily, ‘but who would know which direction to go?","Listen, I know the type of man you are.","You’re never happy until you’re drunk, and then you make mistakes.","But I know how to do this and, believe me, if we do it too quickly, then we’ll hang.’","‘All right, but when we do get them, what will we do to them?’ asked Dick.","‘We can leave them on the island, or we can kill them – that’s what Flint or Billy Bones would have done,’ said Silver.","‘I say we ought to kill them.","We’ll wait, and then we’ll do it,’ said Silver.","‘Now, let’s have some rum!’ ‘Dick,’ said Silver, ‘I’ll let you get it.","Here’s the key.","Fill up a cup and bring it up.’","I realized that this must have been how Mr Arrow had got the drink that killed him.","While Dick was gone, I heard Israel speaking quietly to Silver.","I heard him say, ‘not another man of them will join us.’","So, I thought, there must still be honest men on board.","Moments later the moon started to shine down on me in the barrel, and almost at the same time a voice shouted, ‘Land ho!’"]},{"t":"h","s":"I share the bad news"},{"t":"p","s":["Men came running onto the deck, and I jumped quickly out of the barrel without being seen and joined them at the bow.","To the south-west were the three hills of Treasure Island.","I heard Silver tell Captain Smollett that he had stopped in a bay here years before to get supplies and water.","‘Look at this map,’ said Captain Smollett, ‘and show me the place.’","Long John’s eyes burned in his head as he took the map.","However, the map was not the map we had found in Billy Bones’s chest.","It was a new copy, complete in every detail apart from the red crosses and the written notes.","Silver must have been disappointed, but he managed to hide it well.","A few moments later, when I was close enough to Dr Livesey, I quietly told him that I urgently needed to speak to him, the squire and the captain in the cabin.","I explained everything I had heard.","All three of them thanked me for my luck and for being brave.","‘Captain,’ said the squire, ‘you were right, and I was wrong.’","He now realized the terrible mistakes he had made.","‘I am stupid,’ he went on, ‘and I put myself under your orders.’","‘First,’ began the captain, ‘we must go on, because we can’t turn back.","If I told them to turn back they would attack us immediately.","Secondly, we have time, at least, before we find the treasure.","Thirdly, there are honest men.","Now, sir, there will be a fight sooner or later, and so I think we should attack them when they least expect it.","Can we be sure that the men you brought with you from home are honest, Mr Trelawney?’","‘Yes, as honest as myself,’ replied the squire.","‘So that’s three men,’ said the captain, ‘and we make seven.","Now, which of the other men do you think are honest?’","‘Probably the men that Trelawney found before he met Silver,’ said the doctor.","‘But perhaps not,’ said the squire, ‘Israel Hands was one of mine, but he’s with Silver.’","‘Well,’ said Captain Smollett, ‘we must keep quiet and watch them all.","We shouldn’t do anything until we know our men.’","‘Jim here,’ said the doctor, ‘can help us more than anyone.","The men like him and he’s good at noticing things.’","I began to feel very worried, since I did not feel that I could help very much.","In the end it was because of me that we were saved.","However, at that moment our situation looked very bad.","There were only seven out of the twenty-six on board who we knew were honest.","And of these seven, one was only a boy."]}]},{"n":5,"title":"We arrive at the island","items":[{"t":"h","s":"How my adventure on shore began"},{"t":"p","s":["The island looked very different when I came on deck the next morning.","We had made good time in the night, and the ship was lying approximately half a mile to the south-east of the island.","Grey-coloured woods covered a large part of the surface, and rocky hills pushed up high above these trees.","The Spy-glass was the tallest hill on the island by more than three or four hundred feet, and it had a large, flat top.","I did not like the look of Treasure Island.","With some difficulty, we brought the ship into a safe but narrow passage of water between Treasure Island and the nearby Skeleton Island, and we dropped the anchor.","The trees came down to the shore, and there was a swamp with two little freshwater rivers running out into it.","The air smelt of dead, wet leaves.","As soon as we arrived at the island most of the crew lay around on the deck grumbling together.","Orders were followed slowly and carelessly, and mutiny, it was clear, was hanging over us like a big, black cloud.","We decided to have a meeting in the cabin.","‘Sir,’ said the captain, ‘things are becoming very difficult, and there’s only one man who can help us.’","‘And who is that?’ asked the squire.","‘Silver, sir,’ replied the captain.","‘He’s as worried as us, and he’s trying to hide what’s happening.","As soon as he can, he’ll talk to his men and tell them to work hard and keep quiet.","Let’s give the men an afternoon on the island.","Provided that most of them go ashore with Silver – you’ll see – he’ll bring them back as quietly as sheep.’","And so it was decided.","The squire, the doctor, the captain, myself, three other good men and about a third of the crew were going to stay on board the Hispaniola.","Meanwhile the other thirteen men, including Silver, excitedly started to climb into the small boats.","It was then that I had the first of the mad ideas that helped so much to save our lives.","With so few men on board, I was not needed on the ship.","In a second I had climbed over the side, and quietly dropped down into the bottom of the nearest boat.","I thought no one had seen me.","However, Silver, who was in the other boat, called out to know if it was me.","I said that it was, and I wondered whether perhaps I should have stayed on board the ship.","When our boat reached the beach, I jumped out and ran into the trees.","Not long after that, I heard Long John Silver shouting after me, ‘Jim, Jim!’ but I did not stop.","I ran and ran until I could run no more."]},{"t":"h","s":"The first shot"},{"t":"p","s":["I was happy that I had avoided Long John, and I began to relax.","Then, after I had continued walking through the woods for some time, I suddenly heard voices.","The voices grew louder and nearer, and I hid behind a tree.","I thought that I should try to listen to the conversation, so I quietly moved closer through the trees.","At last, I looked down a little hill towards an open area of swamp, and I saw Long John Silver and one of the crew.","‘Mate,’ Silver was saying, ‘it’s because I like you.","If I hadn’t liked you from the start, do you think I’d be warning you now?","It’s all finished, and you can’t do anything to change things.","I’m trying to save you – join with us, Tom.’","‘Silver,’ said the other man, ‘you’re old, and you’re honest, and you’ve got money, too, and you’re brave.","And you’re telling me you’d join those men?","Not you!","I’d prefer to lose my hand than turn against my duty.’","Suddenly, from far away there was a loud cry of anger, then a horrible, long scream.","It was a death cry, and the sound of it would not leave my head.","‘What was that?’ said Tom, shaking with fear.","‘Oh,’ Silver quietly smiling, ‘that must have been Alan.’","‘Alan!’ cried Tom.","‘God rest his soul!","He was a true seaman.","You’ve killed Alan, have you?","Kill me, too, if you can.’","And with that, this brave man turned and walked away.","With a cry, Silver threw his crutch with all his strength.","It hit Tom hard in the middle of his back.","He fell down, and in a moment, Silver had jumped on top of him and had killed him with a knife.","Then I saw Silver slowly cleaning the blood from his knife on some grass.","He took out a whistle and blew on it several times.","I did not know what this meant, but guessed that more men would be coming.","I began to move away as quickly and as quietly as I could.","They had already killed two people.","Might I be next?","I ran and ran, full of fear.","How could I go back to the boats with these men after what they had done?","Would they kill me as soon as they saw me?","It was a disaster, I thought.","There was nothing left for me but death by one of the mutineers, or by starvation.","But as I ran through the woods, a new fright made me stop suddenly, and I stood still, my heart racing."]},{"t":"h","s":"The man of the island"},{"t":"p","s":["Something had jumped with great speed behind a tree.","It could have been a bear, or a man, or a monkey: I could not tell.","I was very frightened, and I could not move.","Then I saw it again, running on two legs.","It was dark and strange and bent over, but I knew that it was a man.","I had a pistol with me, and that now made me feel a little braver.","I started to walk to where the man was.","He had been hiding behind a tree, but as soon as I came closer he stepped out to meet me.","‘Who are you?’ I asked.","‘Ben Gunn,’ he answered, ‘I’m poor Ben Gunn.","And I haven’t spoken to anyone for three years.’","‘Three years!’ I cried.","I could now see that he was a white man, but that his skin had been burnt by the sun.","He was wearing bits of old seaman’s clothing and these bits were held together with sticks, various buttons and bits of string.","He had an old belt around his waist, which was the only thing that looked normal about him.","‘I was marooned three years ago,’ he said.","I had heard the word, and knew that it meant being left alone by your shipmates on a distant island with only a gun to help you survive.","‘I’ve lived on goats, berries and fish since then,’ he continued.","‘You haven’t got a bit of cheese with you, have you?","I’ve been dreaming of cheese.’","‘Provided that I get on board again,’ I said, ‘you will have lots of cheese.’","‘On board?’ he repeated.","‘What’s your name?’ he asked.","‘Jim,’ I told him.","‘Well, Jim.","I’ve thought about it on this lonely island, and I’m a changed man.","You won’t see me drinking rum again … or, well, just a little for luck, of course.","And I’m going to be good.","And,’ he looked around him carefully, ‘I’m rich.","Rich!","And I’ll tell you something … I’ll give you some of it, since you were the first man to find me!’","But with that, he suddenly looked frightened and held my hand hard.","‘It’s not Flint’s ship you’re from, is it?’ he asked.","This gave me hope.","Perhaps I had found someone who would help me.","‘No, it’s not Flint’s ship.","Flint is dead,’ I replied.","‘But there are some of Flint’s crew aboard, which is bad news for the rest of us.’","‘Not a man … with one … leg?’ he said.","‘Silver?’ I asked.","‘Yes, that was his name.","If you were sent by him, then I’m a dead man,’ he said quietly.","I had decided what to do in a moment.","I told him all about our voyage, and the crisis we were now in.","He listened carefully, and then he said, ‘You’re a good lad.","Don’t you worry, Ben Gunn will help you.","Now, do you think your squire would pay me well to help him?","And take me back home on the ship?’","‘The squire is a gentleman, and anyway, if we don’t have the others, we will need you to help sail the ship home,’ I said.","‘Well,’ he continued, ‘I’ll tell you some of my story.","I were on Flint’s ship when he went to bury the treasure.","He took six strong sailors with him, but he came back alone – he’d killed them all.","Billy Bones was the ship’s mate, and Long John looked after the supplies.","Well, I was on a different ship three years ago when I saw this island again.","“Boys,” I said, “let’s stop and get Flint’s treasure.”","The captain wasn’t happy, but for twelve days we looked for it, and found nothing.","Every day they got angrier and then they said, “here’s a gun, a pickaxe and a spade.","Find it yourself!”","Then they all went aboard and left me here.","But I’ve been busy these three years, see?’","And guess what?","He winked at me.","‘But how are we going to get back on board?’ I asked.","‘Ah,’ he said, ‘I’ve made a small boat.","I keep her under the white rock.’","Just then, there was the sudden loud crash of a cannon.","‘They’ve started to fight!’ I cried."]}]},{"n":6,"title":"The stockade","items":[{"t":"p","s":["While Jim was ashore (the doctor now tells the story) It was about half-past one when the two boats went ashore from the Hispaniola and the captain, the squire, and I were talking in the cabin.","Down came Hunter, who was one of the honest men, and he told us that Jim Hawkins had got into one of the boats and gone ashore with the other men.","We trusted him, but we were worried about his safety.","After a while Hunter and I decided to take another rowing-boat and go ashore in order to explore.","The first two boats had gone far to the right, but Hunter and I came straight in, in the direction of a stockade which we had seen on the treasure map.","There was a man waiting in each of the boats on the shore.","They saw us but did nothing.","When we landed, I jumped out holding two loaded pistols and ran into the trees.","I had not gone more than a hundred yards when I came to an open area and saw the stockade.","There was a little hill that had a fresh-water spring coming out of it.","A strong wooden house, which was big enough to hold about twenty people, had been built by this spring.","Each wall had several holes in it so that muskets could be fired from inside.","All around, a wide space had been cleared, and then the stockade was completed by a tall fence.","With its fresh water and strong walls, the stockade would be the best place for us to stay.","Suddenly, from across the island, there came the terrible cry of a dying man.","I made my decision in a moment, ran towards the shore and jumped into the boat.","We were soon on board the Hispaniola again, where everyone was frightened and worried.","I told the captain my idea and we made a plan.","We gave old Redruth three or four loaded muskets and left him on the ship to watch the six seamen that we did not trust.","Then we started filling the boat with supplies: gun powder, muskets, bags of biscuits, small barrels of meat and brandy, and of course, my medicine chest.","As we rowed to the shore, one of the seamen much further up the beach saw us and ran into the woods.","We unloaded the supplies and left Joyce, who was another honest man, to look after the supplies, Hunter and I returned for a second load.","The reason why we risked a second trip was that, though the majority of the crew were on the island, not one of them had a gun.","When we had unloaded after the second trip, Hunter and Joyce stayed ashore and I rowed as fast as I could back to the Hispaniola.","Then the squire, Captain Smollett, Redruth, myself and one other sailor – Abraham Gray – climbed into the boat.","This fifth trip was dangerous.","There were too many men, and we were also carrying another load of supplies.","The sea had become rougher and several times some water came over the side of the boat.","Suddenly, the captain said, ‘Look behind us!","The gun!","The five men left on board were preparing to fire the cannon – we had forgotten all about this big, powerful gun.","‘Israel was Flint’s gunner,’ said Gray, with fear in his voice.","Trelawney, who was the best of us with a gun, loaded his musket.","We stopped rowing, then he took aim, and fired.","Just at that moment Israel Hands, who had been loading the gun, bent down.","The shot flew past him and hit one of the other men on deck.","Then we heard shouting from the ship and also from the shore, where we could now see the other pirates coming out of the woods.","It was not long until a shot from the cannon fell right by our boat, and she began to sink.","Luckily, we were not far from the shore.","As we walked through the waves and up onto the beach our poor boat and about half of our powder and supplies lay underwater behind us.","To make things worse, we could now hear shouting coming from the woods nearby."]},{"t":"h","s":"The first day in the stockade"},{"t":"p","s":["We ran as quickly as we could to the stockade, and at every step we could hear the pirates’ voices more loudly.","Just as we reached the stockade seven men appeared out of the woods.","The squire and I fired, and so did Hunter and Joyce from inside the log-house.","One of the mutineers fell to the ground and the rest turned and ran into the trees.","We went to look at the man who had fallen, and at that moment a shot came out of the trees and hit poor Tom Redruth.","He cried out with pain, and we carried him, bleeding, inside the wooden house.","The squire fell down beside him and kissed his hand, crying like a child.","Redruth was a good man and had always followed orders silently and well.","Not long after that, he closed his eyes and died.","The captain, whose pockets were full of things he had taken from the ship, took out a flag and put it carefully over Tom’s body.","Then he put another on a tall tree branch high above.","Following that, he came to me and spoke quietly.","‘Dr Livesey,’ he said, ‘how many weeks is it until Blandly will send a ship to look for us? I told him it would be months, and not weeks.","‘Well, sir, then it’s very bad that we lost the second load of supplies.","The food supplies are very limited,’ he replied.","Just then, with a loud roar, a cannon ball landed inside the stockade.","‘Perhaps they can see the flag from the ship,’ said the captain.","We were safe enough inside, but the balls continued to fall throughout the evening.","‘The woods between us and the beach are probably safe,’ said the captain after several hours, ‘and it will now be low tide.","Our supplies shouldn’t be underwater now.","I need some volunteers to go and bring them back.","Gray and Hunter went quietly down to the shore, but they were too late.","Four or five of the mutineers were already there, loading our supplies onto one of their small boats.","Silver was in the boat, and all the men now had muskets, which must have been kept secretly on the ship.","There were now only six of us left, with food supplies to last us for only about ten days.","Redruth was dead, and we did not know what had happened to Jim Hawkins.","Then, suddenly, there was a call from outside.","‘Doctor!","Squire!","Captain!’ cried a voice.","And I ran to the door and saw Jim Hawkins climbing safely over the stockade fence.","As soon as Ben Gunn saw the flag on the stockade, he stopped walking.","‘Now,’ he said, ‘when you see your friends, tell the squire or the doctor to come and see me.","You know where to find me – up in the woods where you saw me today.","Tell them there’s a good reason why I’m hiding.","‘Good,’ I said.","‘Can I go now?","The cannon suddenly started firing again and we ran in different directions into the trees.","Slowly, I went down the hill closer to the sea, and soon I could see the Hispaniola, and I could see the Jolly Roger – the black flag of piracy – flying from her mast.","As I was going down towards the stockade, I saw a large white rock some distance further along the beach.","I thought that this might be the rock that Ben Gunn had spoken about, and that one day, if I needed a boat, I would know where to look.","There was a warm welcome for me at the stockade and I happily told them my story.","Later that evening we buried old Tom Redruth in the sand and stood silently around him for a while.","Then we ate some meat and drank some brandy.","The squire, the doctor and the captain discussed what to do.","We had very little food, but it was decided that we would fight the pirates as best we could.","There were fifteen of them now, and two of those had been shot and hurt.","To help us, on the other hand, there was also the rum the pirates were drinking: though the pirates were half a mile away, we could hear them well, singing and shouting late into the night.","I was very tired, and when at last I got to sleep, I slept like a log."]},{"t":"h","s":"Silver’s visit"},{"t":"p","s":["I was woken up by the sound of voices early the next morning.","‘There’s a white flag!","I heard someone say, ‘It’s Silver!","There was a man with Silver who shouted, ‘Captain Silver, sir, wants to talk and make peace.","‘I don’t know him.","Who’s he?’ cried the captain, adding to himself, ‘So it’s “Captain” now, is it?","And now Long John answered, ‘It’s me.","These poor men chose me to be the captain, after you deserted the ship.","We want to talk to you and agree something.","And then Silver came up close to the fence, threw over his crutch, and with a great effort managed to climb over.","When he finally got near the log-house, he sat down heavily on the sand.","‘Well, captain,’ he said, ‘we want that treasure.","You’ve got a map, haven’t you?","And we want it.","If you give us the map, and stop shooting poor seamen, we’ll give you a choice.","You help us get the treasure, then you come with us on the ship, and I promise you I’ll leave you somewhere safe ashore.","Or you can stay here.","We’ll give you half of the supplies, and I promise I’ll tell the first ship we see to come and get you.","‘Now you will hear me,’ said Captain Smollett.","‘If you come here one by one without guns, I’ll put you all in irons and take you home to England for a fair trial.","If you don’t, you are beaten anyway.","You can’t find the treasure, you can’t sail the ship, and you can’t even fight us.","Now, off you go.","Long John Silver was red with anger.","With much difficulty, he pulled himself along the ground to where his crutch lay.","Then he stood up and spat in the spring.","‘There!’ he cried, ‘that’s what I think of you!","I’m going to destroy this old stockade, and those that die will be the lucky ones!","And swearing loudly, he moved away, pulled himself slowly over the fence and was gone.","The captain soon made sure that we all had muskets and told us where to stand.","There were more of them than there were of us, but at least we had the stockade.","After an hour of waiting, a group of mutineers suddenly appeared from the woods on the north side and ran towards the fence.","At the same time, shots came from the woods to the other side.","The squire and Gray fired again and again from inside the log-house and hit three men as they climbed over the fence – two of them were shot dead, and the third ran away.","But four more had got inside the fence, and then they were on us with pistols and swords.","One of the pirates put his hands on Hunter’s musket, pulled it through the hole in the stockade wall, and used it to hit Hunter hard on the head.","He fell to the floor and did not move.","We picked up swords and ran out of the house to fight.","I saw the doctor cut a man across the face, and Abraham Gray cut down another man who was coming to attack me.","After a few minutes of terrible fighting, it was all over.","We had won.","Six of their men lay dead, or dying, and the rest had run away.","But when we went back to the log-house, we saw that Hunter was lying on the floor.","Joyce had been shot dead, and the squire was holding the captain, who was badly hurt."]}]},{"n":7,"title":"My sea adventure","items":[{"t":"h","s":"How my sea adventure began"},{"t":"p","s":["The mutineers did not return that day.","However, Hunter never woke up again and died some time the following night.","The captain had been shot in the shoulder and the leg.","However, the doctor stated that he would certainly recover provided that he was given enough time to rest.","That left us just four healthy men: the doctor, the squire, Gray and myself.","After eating lunch, the doctor picked up two pistols, a musket, a sword and the treasure map and walked quickly into the woods to the north.","I thought that he was probably going to see Ben Gunn.","I started to wash out the log-house.","It was hot and it was filled with blood and dead bodies.","I hated it and wanted to get away.","After a moment’s thought, and while the squire and Gray were not looking, I filled my pockets with biscuits, took two pistols and immediately left the log-house.","This was the second reckless thing I had done, and this time I had left only two men to protect the stockade.","But, like the first act, it would help to save us.","I had decided to go down to the white rock and find Benn Gunn’s boat.","It was beginning to get dark now, and as I walked among the trees I saw a boat, with Silver and some other men aboard, rowing from the Hispaniola to the beach.","I went on to find the white rock as the light died, and it was almost totally dark by the time I finally found the little boat.","It was very small, even for me, and it was made from a frame of rough pieces of wood covered in goat skins.","There was also a paddle.","Now that I had found the boat, I had another idea.","I could use the boat to go secretly out to the Hispaniola in the dark, and cut her free from her anchor to stop the pirates going to sea.","By now it was very dark.","I could see the pirates’ campfire further along the beach, and just one light out in the water which showed me where the Hispaniola lay.","I carried the little boat down to the water, and with some difficulty, climbed in.","The tide had changed and was going out.","It was hard to get the little boat to move in the right direction, but despite this, I managed at last to get near the ship.","When I found the anchor rope, I took out my knife and started to cut it.","As I was cutting, I could hear two men arguing and fighting in the ship above me.","It was clear that they had drunk a lot of rum, and I knew one of the voices – it was the voice of Israel Hands.","On finally cutting through the rope, the ship suddenly started to turn and move with the tide along the narrow passage of water.","It moved quickly, and my boat moved along with it.","At one point, I saw that I was close to the waves and the beach where they were breaking.","The campfire was closer now, with the pirates all around it, and I heard words from a song I had heard them sing many times on the ship: ‘But one man of her crew alive, What put to sea with seventy-five.’","I lay down in the bottom of that very small little boat, and I believed that I was going to be thrown out into the sea to die.","I must have stayed like that for hours, being thrown about on the waves, expecting to die at any moment, but also exhausted.","Slowly, I fell asleep and dreamed about home and The Admiral Benbow."]},{"t":"h","s":"Alone at sea"},{"t":"p","s":["When I woke the sun was up, and I found myself about a quarter of a mile off the south-west end of Treasure Island.","However, the shore was very rocky and the sea rough, so I could not risk trying to go ashore.","I tried to paddle, but the boat was difficult to steer and water started to come in.","I felt horribly frightened.","How could I hope to reach land?","Sometime later, as I moved around the coast, I suddenly saw the Hispaniola in front of me, less than half a mile away.","Her sails were moving freely in the wind, and it was clear to me that no one was sailing her.","I thought that the two men must be asleep from the rum.","If only I could get on board, I might be able to return her to her captain.","I knew what I needed to do.","I sat up and started paddling again.","Despite water coming into the boat, I went on paddling until at last I was close to the ship.","I could see that one of the booms was hanging out over the side of the ship, and when a large wave came I pushed myself up and reached for it."]},{"t":"h","s":"Israel Hands"},{"t":"p","s":["As I dropped down onto the deck, the ship came into the wind, swung round and nearly threw me back into the sea.","I managed to stand up, and then I saw a man lying dead further along the deck.","Near him was Israel Hands, sitting against the side of the ship.","His eyes were closed and his face was white.","I could see blood on the deck and a large cut on his leg.","I thought that the two men must have killed each other.","At that moment, Israel moved a little and asked me to get him some brandy.","I quickly went down to the cabin.","It looked terrible and was covered in empty bottles, but I managed to find a little brandy, as well as some biscuits, cheese and raisins for myself.","After drinking the brandy, Israel was stronger and asked me where I had come from.","‘I’ve come to take the ship,’ I replied.","‘and please think of me as your captain.’","He looked at me but said nothing.","Then I pulled down the pirates’ black flag and threw it into the sea.","I did not trust Israel Hands, but I knew that I could trust him on one point – we both wanted to beach the ship somewhere safe, where she could easily be returned to the sea.","Hands offered to tell me how to do it.","So, with Hands giving me step-by-step instructions, we brought the ship slowly into the North Inlet.","Then he cried, ‘Now, my boy!’ and I turned the ship quickly and she started to move towards the shore.","While waiting for the ship to beach, I turned to face Hands.","When our eyes met we both cried out.","My cry was of fear, because he was now standing and had a knife in his hand.","His was a cry of attack.","He came towards me, but I ran to the side, pulling one of my pistols out from my belt as I moved.","At that moment, the ship ran onto the shore and with a huge and sudden movement, fell over to one side.","We both fell down onto the deck, but I jumped up again and started to climb the nearest mast.","On getting high up the mast, I stopped to load my two pistols.","Hands began to come up the mast after me, and then he stopped climbing and threw his knife at me.","Despite the fact that it hit me in the shoulder, I fired both my pistols.","Hands cried out and fell into the water below.","‘Pieces of eight’ After a few moments of fear, I saw that the knife had not hurt me much and I climbed slowly down.","Hands was dead in the water.","I got rid of the other body by lifting it over the side of the ship to join Hands.","Before leaving the ship I pulled in as many of the sails as I could.","Then I dropped down into the water and walked to the beach.","I was very excited and could not wait to get back to the stockade to tell the others that I had got the ship back.","It was late at night by the time I found my way to the stockade.","As I came towards the gate I was pleased to hear the sound of my friends snoring.","Then, when I walked in, a strange voice suddenly cried out, ‘Pieces of eight!","Pieces of eight!","Pieces of eight!’","It was Silver’s parrot, Captain Flint!","There was no time to think.","The men woke up immediately and Silver cried, ‘Who goes there?’","I tried to run away, but it was impossible, and they soon caught me.","Silver ordered someone to go and get a torch, and I waited for the light to come."]}]},{"n":8,"title":"Captain Silver","items":[{"t":"h","s":"In the enemy’s camp"},{"t":"p","s":["‘You’ve come to visit us, Jim,’ said Long John.","‘That’s nice.’","I said nothing but looked Silver in the face.","‘Now, I’ve always liked you, I have,’ said Silver.","‘Your friends won’t take you back after this.","And unless you’re going to start a third group of men on your own, you’ll have to join us.’","So, my friends were alive.","‘If I have the freedom to choose,’ I replied, ‘I think you should tell me what’s going on, and where my friends are.’","‘Yesterday, Dr Livesey came with the white flag to speak to me,’ explained Silver.","‘He told me that the ship had gone.","We didn’t have any food, and so he suggested that we should make a bargain with him, and that’s what we did.","So here we are, with the supplies, brandy, log-house and firewood.","I don’t know where they are.’","‘Well,’ I said, ‘You’ve got no ship, the treasure’s lost, men have died and everything’s gone wrong.","And if you want to know who did it … it was I!","I was in the apple barrel the night we first saw Treasure Island, and I heard everything you said.","I cut the anchor from the ship, and killed the men on board her, and hid her somewhere where you’ll never find her.","Kill me if you want, or save me.","But if you save me, I’ll forget all this and support you when you are in court for piracy.’","For a moment there was silence as they all just looked at me.","‘He knew Black Dog,’ said one man.","Silver added, ‘And it was this same boy who got the map from Billy Bones.’","At this moment another man jumped up with a knife and said, ‘Then I’m going to kill him.’","‘Stop,’ said Silver.","‘You’re not the captain.","I like that boy – he’s better than all of you, and I say he stays alive.","You’ve chosen me to be captain.","If you don’t want me, you know what to do.’","After a short silence the men went outside to hold a council.","The men walked out one by one, leaving Silver and me alone, and they were gone for some time.","‘Jim,’ said Silver quietly, ‘you could die now.","We’re in a lot of trouble but I’ll do my best.","If I can, I’ll save your life.","But, see Jim, then you have to save me from being hanged.’","I thought for a moment and then promised that I would do what I could for him.","‘And there’s something else, Jim.","The doctor has given me the treasure map.","Why do you think he did that?’","My mouth fell open, which showed Silver that he did not need to ask more questions."]},{"t":"h","s":"The black spot again"},{"t":"p","s":["The door opened, and the five men came back inside.","One of them walked towards Silver nervously, and gave him a piece of paper marked with a black spot.","I remembered the captain’s fear of ‘the black spot’ long before, back at The Admiral Benbow.","Silver turned over the small, dark piece of paper and then said, ‘Well, what does it say?","“Deposed.”","Well, I’m still your captain until you tell me why you’re unhappy, and I reply.","After that, we’ll see.’","‘Well, first,’ replied one of the men, called George Merry, ‘you’ve made a mess of this voyage.","Second, you let the enemy out of here for nothing.","Why did they want out?","I don’t know, but I know that’s what they wanted.","Third, you wouldn’t let us shoot as they were leaving.","And finally, there’s this boy.’","‘I made a mess of this voyage, did I?’ asked Silver quietly.","‘You all know that I didn’t want to attack them until the treasure had been found and we were on our way back to England.","If you’d listened to me, we’d all still be on the Hispaniola.","Every one of us would be alive and there’d be food and drink and treasure on board!","But you men wouldn’t do what I told you.","Because of what you’ve done, we could all hang!","And isn’t this boy a hostage?","He might be our last chance.","Kill that boy?","I wouldn’t.","Second – the doctor comes here every day to look after that big cut on your head, John, and give you medicine, George.","And there’s another ship coming, and it’s not so long until then.","We’ll see who’ll be glad to have a hostage when that time comes.","Third – you asked me to bargain.","And if I hadn’t made a bargain, we’d all have starved.","And this is why I did it,’ he shouted, and he threw a paper down in front of him.","It was the treasure map, complete with the three red crosses.","The mutineers jumped on the map like five cats on a mouse.","They were so excited that you would have thought they were actually getting their hands on the gold itself.","Soon, however, Merry said, ‘This is all very good – but how are we going to get away without a ship?’","‘You and the other men lost us the ship,’ said Silver angrily, ‘and I got us the treasure.","Who’s the better man?","I’ve had enough.","Choose yourselves another captain.’","‘Silver!’ they cried, ‘Silver forever!’"]},{"t":"h","s":"The doctor’s visit"},{"t":"p","s":["The next morning, I was woken by someone shouting, ‘Here’s the doctor.’","As the doctor came near, Silver said, ‘We’ve got quite a surprise for you, sir.’","As the doctor came into the log-house he nodded his head towards me and then started to look after the two sick men.","When he had finished, he asked to speak to me before he left.","‘Hawkins,’ said Silver, ‘do you give me your word that you won’t run away?’","I promised that I would not, and he agreed to let me go outside to talk with Dr Livesey.","He told the doctor to go and wait for me down by the fence.","The other men were very angry and argued against it, but we walked down to meet the doctor.","Silver said to him, ‘I saved the boy’s life, and was nearly deposed for it, too – he’ll tell you so.","So surely you’ll have a good word to say about me?","I’ll be honest – I don’t want to be hanged.’","Then he left us and walked some distance away.","‘Jim,’ said the doctor, ‘You waited until Captain Smollett was ill and could do nothing, and then you ran away.","That was very cowardly.’","‘Doctor,’ I said.","‘I’m very sorry, and I think I’m going to die anyway.","I would have been dead by now if Silver hadn’t saved me.’","‘Then quick,’ he replied, ‘let’s run away.","One jump and you are out!’ ‘No,’ I answered, ‘I gave my word and I must stay.","But I’ll tell you one thing in case I do die.","I’ve got the ship, partly by luck and partly by risking my life.","She lies in the North Inlet.’","‘The ship!’ said the doctor.","I then quickly explained everything that had happened.","‘At every step,’ he answered, ‘it’s been you who’s saved our lives.","We won’t now let you lose yours.","And finding Ben Gunn was the best thing you’ve ever done.’","Then he called to Silver.","‘Silver,’ he said, ‘I’ll give you some advice.","Don’t be in a hurry to get that treasure.","And when you find it, expect trouble.’","Silver asked him what he meant by that, but the doctor said, ‘I can’t say more.","It’s not my secret.","If we get out of here alive, I’ll do my best to save you.","And another thing – keep the boy close to you, and when you need help, shout.’"]},{"t":"h","s":"The search for the treasure"},{"t":"p","s":["I did not trust Silver.","It was with a heavy heart that I, tied to a length of rope that Silver was holding, followed the men when they went up the hill to look for the bulk of the treasure near Spy-glass hill.","The men were all carrying several weapons each, and some were also carrying shovels, pickaxes and food supplies.","The men followed the detailed instructions on the back of the treasure map.","We crossed swamp and woodland and then climbed up towards the flat top of the Spy-glass.","One of the men in front suddenly screamed out in fear.","Near a tree he had found a skeleton, lying unnaturally straight, with its arms pointing up above its head.","Silver thought for a moment and then asked one of the men to take a compass bearing.","The body pointed from Skeleton Island to Spy-glass hill.","‘I thought so,’ cried the sea-cook, ‘Flint killed this sailor and left his body here as a pointer to the treasure!","What a terrible man, that Flint.’","The men were much quieter after that, and they walked closer together.","All of a sudden, from the trees in front of us, came a thin, high voice, singing the words we knew well: ‘Fifteen men on the dead man’s chest – Yo-ho-ho, and a bottle of rum!’","I have never seen men more frightened than those pirates.","‘It’s Flint’s ghost!’ cried one of them.","But Silver spoke up, ‘Shipmates,’ he cried, ‘I’m going to get that treasure and no man will stop me whether he’s dead or alive.’","After a few words from Silver, the men agreed to go on.","And we looked for the tall tree marked on the map, where the treasure lay buried.","They now walked faster and Silver was full of excitement.","I knew that all Silver wanted was the treasure, and to get away from the island, and that he would kill anyone who stood in his way.","As we came near the great tree the men began to run, and then they stopped suddenly.","In front of us was a great hole, not recently made, and very little else.","The treasure that lay under the first of the red crosses on the map had been found and taken!"]},{"t":"h","s":"The end of the fight"},{"t":"p","s":["The pirates, swearing and shouting, jumped into the hole and started to dig with their hands.","One finally found a single piece of gold.","In the meantime, Silver had recovered quickly from the shock.","He quietly passed me a pistol and whispered in a friendly way, ‘Jim, take that.","And be ready for trouble.’","He had changed sides again.","Then, taking me with him, he moved slowly to the other side of the hole.","The pirates, finding nothing more, climbed out of the hole opposite us.","George Merry shouted at Silver, ‘That’s the treasure, is it?’","He turned and spoke to the other four pirates, ‘Now, mates.","I say we kill them …’ At that moment there came the sound of muskets firing and Merry fell into the hole, another dropped down dead and the remaining three men ran away.","In a moment Silver had shot George Merry again and killed him.","The doctor, Gray and Benn Gunn then came out of the trees to join us.","As we walked down to the boats, the doctor told us what had happened.","Benn Gunn, during his long time on the island, had found the skeleton, and then the treasure.","He had dug it up, and carried it, load after load on his back, to a cave he had found on the other side of the island.","When the doctor had heard this, and had seen that the ship had gone, he realized that the map was useless.","He went to Silver and gave him the map, and the supplies, because he knew that the best place to be was in the secret cave, with the treasure and Benn Gunn’s food supplies.","When Dr Livesey saw that I was with the mutineers, he had run as fast as he could to be ready at the hole with Benn Gunn.","When we got to the boats, the doctor used a pickaxe to break up one boat, and then we all climbed into the other and started to row the eight or nine miles to North Inlet.","As we got close, we came round a hill and saw the black mouth of Ben Gunn’s secret cave.","The squire was standing there, looking after the treasure.","He did not look pleased to see Long John Silver.","We found Captain Smollett lying by a fire inside the cave, and behind him I could see a very large pile of gold coins.","So this was Flint’s treasure.","How much pain, sadness, and blood it had cost, and how many ships had been sunk, cannons shot and lies told no one could say.","That night I ate a wonderful meal with all my friends around me.","We ate Benn Gunn’s salted goat, and had some wine from the Hispaniola.","And there was Silver, sitting and laughing with us – the same friendly, helpful, smiling sea-cook we had left Bristol with."]},{"t":"h","s":"The return home"},{"t":"p","s":["The next morning we started work moving the treasure to the Hispaniola.","It was hard work, and one of us had to stand with a gun on the hill to watch for the last three mutineers.","Day after day this work went on.","We heard the remaining mutineers once only – singing and shouting in the distance.","We decided that we must leave them on the island.","We left enough powder and shot, most of the goat meat, some medicines and other useful things.","Then we prepared the ship, pulled up the anchor and started to move out of North Inlet.","The three men must have been watching us more carefully than we thought.","As we came out of the inlet, they were on the beach.","They were on their knees and were calling out to us, asking to be saved.","The doctor shouted to them, and told them where they could find the supplies we had left.","But they continued to shout, and then one of them fired a shot.","Slowly, they disappeared from sight, and by midday the highest rock of Treasure Island had grown small and sunk into the blue sea.","The sun was just sinking down into the water when we dropped our anchor in a beautiful Mexican bay.","Many small boats came out to us, full of people selling many different types of colourful fruit and vegetables.","The sight of so many smiling faces, the taste of such amazing fruit, and the lights that had begun to shine in the town were a wonderful change from our dark and dangerous time on the island.","The doctor and the squire decided to go ashore for the evening, and they took me with them.","When we returned, Silver had gone, and had taken one of the bags of coins with him.","I think we were all pleased that we had got rid of him so cheaply.","To cut a long story short, we found a few more sailors, had a good voyage home, and the Hispaniola reached Bristol in the late summer.","Only five men who had sailed from Bristol returned with the ship.","‘Drink and the devil had done for the rest,’ though we were not in as bad a situation as the other ship they had sung about: ‘With one man of her crew alive, What put to sea with seventy-five.’","We all had a good share of the treasure, and we used it well or badly, depending on the person.","Captain Smollett has now retired from the sea.","Gray saved his money and studied to become a ship’s mate.","He also got married and had children.","Ben Gunn got a thousand pounds, which he spent, or lost, in nineteen days.","Then he went to live in a village, where he still sings in church every Sunday.","We heard no more about Silver.","That terrible seaman with one leg has at last gone out of my life.","I hope he is somewhere living happily in this world, because I am sure he will not be happy in the next.","The silver and the weapons still lie buried, for all I know, where Flint hid them.","But I will never go back to that island, and the worst dreams I ever have are when I see that terrible rocky coast, or when I suddenly sit up in bed, with the hard voice of Captain Flint still loud in my ears, screaming, ‘Pieces of eight!","Pieces of eight!’"]}]}];
// وەرگێڕانی سۆرانی بە ڕیزبەندی رستەکان (لە رستەی ٠ەوە). رستەکانی تر دەتوانی لێرە زیادیان بکەیت.
const KU=["لەبیرمە وەک ئەوەی دوێنێ بووبێت.","بە هێواشی هاتە بەردەم دەرگای مێواندارخانەی ئەدمیراڵ بێنبۆ، و سندووقە دەریاییەکەی لەسەر عارەبانەیەکی دەستی بەدوایدا دەهات.","پیاوێکی بەهێز و قورس بوو، قژی درێژ و کوتێکی کۆنی شینی لەبەر بوو.","دەستەکانی زبر و لە پیسی ڕەش هەڵگەڕابوون و برینداغێکی درێژی شمشێری بەسەر یەکێک لە گۆناکانییەوە بوو.","دەرگای مێواندارخانەکەی کوتا و کاتێک باوکم دەرگاکەی کردەوە، بە توندی داوای پەرداخێک رۆمی کرد.","«ئەم کەنداوە بۆ مێواندارخانەیەک شوێنێکی خۆش و ئارامە،» گوتی و بە هێواشی سەیری دەوروبەری کرد، بەرەو لێواری چیاکان و مێواندارخانەکەمان.","«هەی هاوڕێ!» بانگی کرد بەو پیاوەی عارەبانەکەی پێبوو، «یارمەتیم بدە سندووقەکەم بخەمە ژوورەوە.»","بەردەوام بوو: «ڕۆم و خواردنی ساکار ئەوەیە کە دەمەوێت.","لەگەڵ ئەو لێواری چیایەی ئەوێ کە دەتوانم لێیەوە سەیری کەشتییەکان بکەم.","دەتوانن پێم بڵێن «کاپتن».","ئا، دەزانم چیت دەوێت،» گوتی بە سەیرکردنێکی توند، و سێ یان چوار دراوی ئاڵتوونی لەبەردەم خۆی فڕێدا.","هەموو ڕۆژ لە دەوروبەری کەنداوەکە یان لەسەر لێواری چیاکان بوو بە تەلەسکۆپەکەیەوە.","هەموو ئێوارەیەک لە مێواندارخانەکە لەلای ئاگرەکە دادەنیشت و ڕۆمی دەخواردەوە.","زۆربەی کات کاتێک قسەی لەگەڵ دەکرا وەڵامی نەدەدایەوە، بەڵکو لەناکاو و بە توڕەییەوە سەیری دەکردین، ئێمەش فێر بووین لێی دووربکەوینەوە.","لەو دەریاوانانە زۆر دەترسا کە دەهاتنە مێواندارخانەکە.","ڕۆژێک بە بێدەنگی بەڵێنی پێدام هەموو مانگێک پارچەیەکی زیوی چوار پێنسی بدات ئەگەر «چاوم لەسەر دەریاوانێکی یەک قاچ بێت».","کاپتن زۆرجار ڕۆمی زۆری دەخواردەوە و گۆرانییە دەریاییە کۆن و کێوییەکانی دەچڕی.","پاشان دەستی بە توندی لەسەر مێزەکە دەکێشا بۆ بێدەنگی، پێش ئەوەی چیرۆکە ترسناکەکانی دەریا بگێڕێتەوە.","چیرۆکەکان باسی سێدارەدان و زریانی دەریا و تاوانی ترسناک بوون.","لەو مانگانەی دەریاوانە پیرەکە لای ئێمە مایەوە، باوکم زۆر نەخۆش کەوت.","ڕۆژێک دوکتۆر لایڤسی هات بۆ بینینی، و پێش ئەوەی بڕوات، دوکتۆرە ژیر و ڕوونەکە لەو ژوورەدا دانیشت کە دەریاوانە پیس و قورسەکەمانی تێدا بوو، ئەویش لەناکاو دەستی کرد بە گۆرانییە ئاساییەکەی: «پانزە پیاو لەسەر سندووقی مردوو – یۆ-هۆ-هۆ، و بوتڵێک ڕۆم!","خواردنەوە و شەیتان کاری ئەوانی تریان تەواو کرد – یۆ-هۆ-هۆ، و بوتڵێک ڕۆم!» پاشان دەستی بەسەر مێزەکەدا کێشا، کە هەموومان دەمانزانی بانگەوازە بۆ بێدەنگی.","هەموو کەس، جگە لە دوکتۆر لایڤسی، بێدەنگ بوون.","چەند ساتێک دواتر کاپتن هاواری کرد: «بێدەنگ بن!»","«ئەگەر قسەت لەگەڵ منە، گەورەم،» دوکتۆر لایڤسی گوتی.","«شتێکم هەیە بیڵێم – ئەگەر بەردەوام بیت لە ڕۆم خواردنەوە، ئەوا جیهان بەم زووانە لە سکوندرێلێکی زۆر پیس ڕزگاری دەبێت!»","کاپتن هەستایە سەرپێ و چەقۆیەکی لە گیرفانی دەرهێنا.","دوکتۆر نەجوڵا، بەڵام بە هێواشی قسەی کرد.","«من پیاوی یاسام – دادوەرم – هەروەها دوکتۆریشم.","ئەگەر ئەو چەقۆیە دانەنێیت، دەچیتە دادگای داهاتوو و سێدارە دەدرێیت.»","چەند ساتێکی ناخۆش تێپەڕین، تا لە کۆتاییدا کاپتن چەقۆکەی خستە گیرفانی و بە قورسی دانیشتەوە.","سەرەتای بەیانییەکی ژانوەری بوو، کاتێک کاپتن لە کەنار دەریا بوو بە تەلەسکۆپەکەیەوە، دەرگای مێواندارخانەکە کرایەوە و پیاوێک هاتە ژوورەوە کە هەرگیز پێشتر نەمبینیبوو.","شمشێرێکی لە پشتێنەکەی هەڵواسیبوو، ڕەنگی پێستی ناخۆش بوو و دوو پەنجەی دەستی چەپی نەمابوو.","لەسەر مێزێک دانیشت، پاشان بانگی کردم بۆ نزیکتر.","«ئەم مێزە بۆ هاوڕێکەمە، بیل؟» پرسی، بە نیگایەکی سەیرەوە.","گوتم مێزەکە بۆ پیاوێکە کە ئێمە پێی دەڵێین کاپتن.","«باشە،» گوتی، «هاوڕێکەم لەوانەیە پێی بگوترێت کاپتن.","برینێکی لەسەر یەکێک لە گۆناکانی هەیە و کاتێک سەرخۆشە زۆر خۆشە، هاوڕێکەم بیل.","ئەی ئێستا لێرەیە؟» پێم گوت چووە پیاسە.","«باشە،» وەڵامی دایەوە، «من و تۆ دەچینە پشت دەرگاکە و بیلێک تۆزێک سەرسام دەکەین.»","ناچاری کردم بشارمەوە و کاتێک بینیم شمشێرەکەی دەرهێنا زۆر نیگەران بووم.","لە کۆتاییدا کاپتن هاتە ژوورەوە و بەرەو مێزی نانی بەیانی ڕۆیشت.","«بیل،» گوتی غەریبەکە.","کاپتن ڕووی وەرگێڕا بۆ لای ئێمە.","ڕووی سپی هەڵگەڕا.","«وەرە بیل، تۆ من دەناسیت – هاوڕێی کۆنی کەشتیت – بێگومان،» گوتی پیاوەکە.","چاوەکانی کاپتن بە فراوانی کرانەوە و گوتی: «بلاک دۆگ!»","«ڕاستە، بلاک دۆگ، هاتووە بۆ بینینی هاوڕێ کۆنەکەی بیلی.","ئا، چەندین ڕۆژی سەختمان پێکەوە بینیوە لەو کاتەوەی ئەم دوو پەنجەیەم لەدەستدا،» گوتی و دەستی بەرزکردەوە.","ڕۆمم بۆ هێنان و پاشان لە ژوورەکە چوومە دەرەوە.","لە سەرەتادا تەنها دەنگی نزمم دەبیست، بەڵام پاشان بەرزتر بوونەوە.","پاشان لەناکاو جنێوێکی بەرز هات و گوێم لە شتێک بوو کە لەسەر زەوی کەوت.","دەنگی ئاسن بە ئاسن هات، پاشان هاوارێکی ژان.","ساتێک دواتر بینیم بلاک دۆگ هەڵدێت و کاپتن لە نزیکییەوە بەدوایدا بوو.","هەردووکیان شمشێریان پێبوو و خوێن لە شانی بلاک دۆگەوە دەڕژا.","بەڵام بلاک دۆگ لە کاپتن خێراتر بوو و زوو چووە دەرەوە و لە سەر گردەکەوە ونبوو.","کاپتن گەڕایەوە ناو مێواندارخانەکە و گوتی: «جیم، ڕۆم!» بەڵام کاتێک قسەی دەکرد، دەستی کرد بە کەوتن بەرەو دیوارەکە.","«ڕۆم،» دووبارەی کردەوە.","«دەبێت لێرە دووربکەومەوە.»","ڕام کرد بۆ هێنانی ڕۆمەکە.","کاتێک لە ژوورەکەی تر بووم، گوێم لە دەنگی کەوتنێک بوو.","ڕام کرد بۆ ژوورەوە و بینیم لەسەر زەوی کەوتووە.","کاپتن بە دەنگێکی بەرز و قورس هەناسەی دەدا.","چاوەکانی داخرابوون و ڕەنگی ڕووی ترسناک بوو.","دایکم ئێستا هاتبووە خوارەوە، بەڵام نەمانزانی چی بکەین.","لەو ساتەدا دوکتۆر لایڤسی هاتە ژوورەوە، لە ڕێگا بوو بۆ بینینی باوکم.","«بە ڕۆمی زۆر خۆی نەخۆش خستووە، بەڵام هەموو هەوڵێکم دەدەم بۆ ڕزگارکردنی ژیانی،» گوتی دوکتۆر کاتێک سەیری کرد.","دوکتۆر کراسەکەی کاپتنی داکەند بۆ دەستپێکردنی کارەکەی و چەند خاڵکوتانێکم لەسەر قۆڵی کاپتن بینی.","ئەمانەیان تێدا نووسرابوو: «بەخت»، «با بەباش» و «بیلی بۆنز».","ماوەیەکی خایاند تا کاپتن چاوەکانی کردەوە.","سەرەتا بە دەوری ژوورەکەدا سەیری کرد، پاشان هەوڵی دا هەستێت و هاواری کرد: «بلاک دۆگ لەکوێیە؟»","«لێرە بلاک دۆگ نییە،» وەڵامی دایەوە دوکتۆر.","«تۆ ڕۆمت خواردووەتەوە و سەکتەت کردووە.","ئێستا ئەوەی دەمەوێت پێت بڵێم ئەمەیە.","یەک پەرداخ ڕۆم تۆ ناکوژێت.","بەڵام ئەگەر یەکێک بخۆیتەوە، ئەوی تر دەخۆیتەوە، و ئەگەر نەوەستیت، دەمریت.","وەرە ئێستا.","یارمەتیت دەدەم بۆ جێگاکەت.»","توانیمان بیبەینە سەرەوە و لەسەر جێگاکەی دایبنێین.","«دەبێت هەفتەیەک لە جێگا بخەوێت،» گوتی دوکتۆر هەر کە دەرگاکەمان داخست.","«ئەوە باشترین شتە بۆ ئەو، و بۆ تۆش.","بەڵام سەکتەیەکی تر کارەکەی تەواو دەکات.»","نزیکەی نیوەڕۆ چووم بۆ بینینی کاپتن.","هەم لاواز و هەم هەڵچووی دیار بوو.","«جیم،» گوتی، «هەموو مانگێک پارچەیەکی زیوی چوار پێنسیم پێداویت.","ئێستا تۆزێک ڕۆمم بۆ دەهێنیت، وانییە؟»","«دوکتۆر…» دەستم پێکرد.","دەستی کرد بە جنێودان و پاشان گوتی: «ئەو دوکتۆرە چی دەزانێت لە ژیانی دەریا؟","من بە ڕۆم ژیاوم، پێت دەڵێم.","دوکتۆرەکەی خۆتان خۆی گوتی یەک پەرداخ زیانم پێ ناگەیەنێت.","گینیەیەکی ئاڵتوونت دەدەمێ بۆی، جیم.»","«من ئەوە دەمەوێت کە قەرزداری باوکمیت.","هەر ئەوەندە،» گوتم (چونکە زۆر درەنگ دەیدایەوە).","«یەک پەرداخت بۆ دەهێنم، و زیاتر نا.»","کاتێک بۆم هێنا، بە خێرایی وەریگرت و هەڵیدایە.","«ئا،» گوتی، «ئەوە باشترە.","چەند ماوەیەک دەبێت لێرە درێژ بکەومەوە؟»","«هەفتەیەک، لانیکەم.»","گوتم.","«ناتوانم ئەوە بکەم!» هاواری کرد.","بەڵام زۆر لاواز بوو بۆ ئەوەی هەستێت و ماوەیەک بە بێدەنگی پاڵکەوت.","«جیم،» گوتی دوای ماوەیەک، «سندووقە دەریاییە کۆنەکەمە کە ئەوان دەیانەوێت.","ئەگەر نەمتوانی دووربکەومەوە، تۆ بڕۆ بۆ – باشە، ئا – بڕۆ بۆ لای دوکتۆر.","پێی بڵێ دادوەرەکان بهێنێت بۆ مێواندارخانەی ئەدمیراڵ بێنبۆ بۆ گرتنی هەموو دەستەی فلینتی پیر، هەموو ئەوانەی ماون.","من یاریدەدەری یەکەمی فلینت بووم و تەنها منم شوێنەکە دەزانم.","کاتێک لە مردندا بوو، ئەو پێی دام.","بەڵام بە دوکتۆر مەڵێ مەگەر خاڵە ڕەشەکەیان خستە سەرم، یان ئەگەر بلاک دۆگ، یان ئەو دەریاوانە یەک قاچەکەت بینی.»","«بەڵام خاڵە ڕەشەکە چییە، کاپتن؟» پرسیم.","«جۆرێک ئاگادارکردنەوەیە، هاوڕێ.","ئەگەر خاڵە ڕەشەکەم پێ بگات، مانای وایە دێن بۆ گرتنی من و ئەوەی هەمە.","چاوەکانت کراوە بێت، جیم، و نیوەی هەموو شتێکت دەدەمێ، بەڵێنت پێ دەدەم.»","نازانم ئەگەر هەموو شتێک بە باشی ڕۆیشتبایە چیم دەکرد.","بەڵام باوکە بەستەزمانەکەم لەو ئێوارەیەدا زۆر لەناکاو مرد.","هەموو دراوسێکان هاتن بۆ سەردان و کاری زۆر هەبوو بیکەین، بۆیە زۆر سەرقاڵ و دڵتەنگ بووم بۆ ئەوەی بیر لە کاپتن بکەمەوە.","ڕۆژی دواتر کاپتن هاتە خوارەوە، کەمێک نانی خوارد و ڕۆمێکی بۆ خۆی هێنا.","شەوی پێش ناشتنی باوکم وەک جاران سەرخۆش بوو.","لەسەر مێزەکە دانیشتبوو و شمشێرەکەی ئامادە لەبەردەمیدا بوو و گۆرانییە دەریاییە ناشیرینە کۆنەکانی دەچڕی.","بەڵام هێشتا زۆر لاواز بوو و وادیار بوو خراپتر دەبێت، نەک باشتر.","چەند ڕۆژێک دواتر، لە دوا نیوەڕۆیەکی سارد و تەمومژاویدا، لەبەر دەرگاکە ڕاوەستابووم و پڕ بووم لە بیری خەمناک دەربارەی باوکم.","کە لەوێ ڕاوەستابووم، بینیم کەسێک بە هێواشی بەسەر ڕێگاکەدا دێت.","پیاوەکە کوێر بوو – دارە دەستێکی لەپێشی خۆیدا دەکوتا و دەڕۆیشت.","پارچە قوماشێکی بەسەر چاو و لوتیدا بوو و کپ بووبوو.","هەرگیز لە ژیانمدا پیاوێکی بەو ترسناکییەم نەبینیبوو.","کەمێک لە مێواندارخانەکە دوور ڕاوەستا و بە دەنگێکی بەرز گوتی: «هیچ پیاوێکی چاک بە کوێرێکی هەژار دەڵێت لەکوێیە؟»","«تۆ لە مێواندارخانەی ئەدمیراڵ بێنبۆیت،» وەڵامم دایەوە.","«دەستت بدەرێ، هاوڕێی گەنج، و ببەمە ژوورەوە،» گوتی.","دەستم درێژ کرد و پیاوە ترسناکەکە بە توندی گرتی.","بەرەو خۆی ڕایکێشام و گوتی: «ئێستا کوڕەکەم.","ببەمە لای کاپتن.»","«گەورەم،» گوتم، «ناتوانم.","کاپتن ئەو نییە کە جاران بوو.","شمشێرەکەی ئامادە لەبەردەمیدا دانیشتووە…» «ببەمە ژوورەوە یان بازووت دەشکێنم،» گوتی و بازووی بە ڕەقی ڕاکێشام.","ڕەقترین و سارد‌ترین دەنگ بوو کە هەرگیز بیستبێتم.","ئەوەندە ترسام کە بردمە ئەو ژوورەی کاپتنی تێدا دانیشتبوو.","کاپتنە بەستەزمانەکە سەری بەرزکردەوە و بە ئاسانی دیار بوو زۆر دەترسێت.","«ئێستا، بیل، لەوێ دانیشە کە هەیت،» گوتی پیاوەکە.","«دەستی چەپت درێژ بکە.","کوڕەکەم، دەستی چەپی ببە و بیهێنە نزیک دەستی ڕاستم.»","هەردووکمان ئەوەمان کرد کە پێمان گوترا، و بینیم شتێکی خستە دەستی کاپتنەوە، کە زوو دەستی لەسەری داخرا.","پیاوە کوێرەکە لەناکاو لە دەرگاکە چووە دەرەوە.","بێ جووڵە ڕاوەستام و گوێم لە دەنگی دارەدەستەکەی بوو کە لە شەقامەکەدا تەق-تەق دەکرد.","کاپتن سەیری ناو دەستی کرد.","«دە‌ی شەو!» هاواری کرد.","«شەش کاتژمێرم ماوە،» گوتی و هەوڵی دا هەستێت.","بەڵام لەناکاو دەستی خستە ملی، و پاشان بە دەنگێکی سەیرەوە بە ڕووخسار کەوتە سەر زەوی.","هاوارم کرد بۆ دایکم، بەڵام درەنگ بوو.","کاپتن مردبوو.","هەموو شتێکم بە دایکم گوت.","زۆر ترسابووین و نەمانزانی چی بکەین.","ئەگەر وەک کاپتن پێی گوتبووم بچم بۆ لای دوکتۆر لایڤسی، دەبوو دایکم تەنها بەجێبهێڵم، و سەلامەتی ئەو لای من لە پێشینە بوو.","لە لایەکی ترەوە، وادیار بوو مانەوەمان لە مێواندارخانەکە زۆر مەترسیدارە.","لە کۆتاییدا بڕیارمان دا چی بکەین.","یەکەم دەبوو بچین بۆ نزیکترین گوند بۆ یارمەتی، پاشان بگەڕێینەوە بۆ کردنەوەی سندووقەکە و وەرگرتنی ئەو پارەیەی کاپتن قەرزداری ئێمە بوو پێش ئەوەی کەسێکی تر بۆی بێت.","بەڵام کاتێک گەیشتینە گوندەکە، کەس نەیویست لەگەڵمان بگەڕێتەوە بۆ مێواندارخانەی ئەدمیراڵ بێنبۆ.","هەندێک لە پیاوەکان ناوی کاپتن فلینتی ترسناکیان بیستبوو، و هەندێکی تر ئەو ڕۆژە پیاوی غەریبیان لەسەر ڕێگا بینیبوو، هەروەها کەشتییەک لە کەنداوێکی نزیک.","هەموویان زۆر ترسابوون بۆ ئەوەی لە ماڵەکانیان بێنە دەرەوە.","بڕیارمان دا بە تەنها بگەڕێینەوە بۆ مێواندارخانەکە و پلانەکەمان جێبەجێ بکەین.","پیاوێک چەکێکی دامێ ئەگەر هێرشمان کرایە سەر، و کوڕێک گوتی سوارە دەبێت بۆ ماڵی دوکتۆر بۆ هێنانی یارمەتی.","کاتێک گەڕاینەوە مێواندارخانەکە، هیچ شتێک نەگۆڕابوو.","دەرگاکەمان داخست، مۆمێکمان داگیرساند و، دەستی یەکترمان گرتبوو، چووینە ژوورەکەی کاپتنی لێ کەوتبوو.","چۆکم دادا.","لەسەر زەوی، نزیک دەستی پیاوە مردووەکە، پارچەیەکی بچووکی خڕی کاغەزی ڕەش هەبوو – خاڵە ڕەشەکە.","هەڵمگرتەوە.","لەسەر یەک لای نووسرابوو: «تا ڕێکی دە ئەمشەو کاتت هەیە».","بەخۆشبەختی ئێمە هێشتا تەنها کاتژمێر شەش بوو.","بە نیگەرانییەوە گیرفانەکانیم پشکنی بۆ کلیلی سندووقەکە، بەڵام هیچم نەدۆزییەوە.","پاشان، لە کۆتاییدا، بینیم لەسەر پارچە گوریسێک بە ملییەوە بوو.","گوریسەکەم بڕی و بە خێرایی چووینە سەرەوە بۆ دۆزینەوەی سندووقەکە.","کۆن بوو و زۆر بەکارهاتووبوو وەک هەر سندووقێکی دەریاوانێکی تر و پیتی «B»ی لەسەر سووتێنرابوو.","«کلیلەکەم بدەرێ،» گوتی دایکم، و هەرچەندە کردنەوەی قفڵەکە سەخت بوو، لە ساتێکدا خوولاندی و سەرپۆشەکەی کردەوە.","لە سەرەوە کراسێکی بە ووردی بەستراو هەبوو.","لە ژێریدا شتی زۆر هەبوو بۆ ژماردن – چەند تفەنگچەیەک، پارچەیەکی گەورەی زیو، کاتژمێرێکی کۆنی ئیسپانی و زۆر شتی بچووکی تر.","لە بنی سندووقەکەدا پاکێتێک بە قوماش داپۆشراو هەبوو، و کیسەیەکی قورس کە دراوی ئاڵتوونی تێدا بوو.","«با ئەوە وەربگرین کە قەرزداری ئێمە بوو،» گوتی دایکم، «و پێنسێکی زیاتر نا.»","دەستی کرد بە ژماردنی دراوەکان.","کارێکی درێژ و سەخت بوو چونکە دراوەکان هەموویان لە وڵاتی جیاواز و قەبارەی جیاواز بوون.","کاتێک نزیکەی نیوەی پارەکەمان ژماردبوو، لەناکاو گوێم لە تەق-تەقی دارەدەستی پیاوە کوێرەکە بوو لەسەر ڕێگاکە.","هەناسەمان بەرنەدەدا و دانیشتبووین.","پاشان دارەکە لە دەرگای مێواندارخانەکە درا، و گوێمان لە دەستگیرەکە بوو دەخوولێنرا – پاشان بێدەنگی.","لە کۆتاییدا، تەقەکە دووبارە دەستی پێکردەوە، بەڵام ئەمجارە کپتر و کپتر بوو کە پیاوەکە دوور دەکەوتەوە.","زۆر نەخایاند، گوێمان لە فیکەیەک بوو لە سەر گردەکەوە لێدرا.","ئەوە بەس بوو بۆ ئێمە.","«بەقەد پێویست نەمژماردووە بۆ دانەوەی هەژماری ئەو، بەڵام ئەوەی هەمە وەریدەگرم،» گوتی و هەستایە سەرپێ.","«و من ئەمە وەردەگرم لەبری ئەوەی تری پارەکە،» گوتم و ئەو پاکێتە بە قوماش داپۆشراوەم هەڵگرت.","بە خێراترین شێوە لە پلیکانە تاریکەکان هاتینە خوارەوە و چووینە سەر ڕێگاکە.","لە ڕێگای گەڕانەوە بووین بۆ گوندەکە کاتێک گوێمان لە دەنگی کەسێک بوو ڕای دەکرد، سەرەتا لە دوورەوە و پاشان نزیکتر.","«دەبێت پارەکە ببەیت و بەردەوام بیت لە ڕاکردن.","هەست دەکەم دەکەومە ناخۆشی،» گوتی دایکم، پاشان کەوتە سەر شانم.","بەخۆشبەختی لە نزیک پردێکی بچووک بووین، و بە زەحمەت توانیم ڕایبکێشم بۆ ژێری.","ساتێک دواتر حەوت یان هەشت پیاو بەرەو مێواندارخانەکە هاتن.","لە پێشەوە سێ پیاو بوون دەستی یەکتریان گرتبوو.","پاشان، لە ڕووناکی لاوازی مانگدا، بینیم لە نێوان ئەو دووەی تردا پیاوە کوێرەکە بوو.","«بڕۆنە ژوورەوە!» هاواری کرد.","چەند پیاوێک چوونە بەر دەرگای مێواندارخانەکە و دەرگاکەیان کراوە دۆزییەوە و چوونە ژوورەوە.","دووانیان لەگەڵ پیاوە کوێرە ترسناکەکە لە دەرەوە مانەوە.","ساتێک بێدەنگی بوو، پاشان هاوارێکی سەرسوڕمان، و دەنگێک لە ماڵەکەوە هاواری کرد: «بیل مردووە!»","پیاوە کوێرەکە جنێوی دا.","«گیرفانەکانی بپشکنن!","پاشان سندووقەکە بدۆزنەوە!» هاواری کرد.","کەمێک دواتر، یەکێک لە پەنجەرەکانی سەرەوە کرایەوە و کەسێک هاواری کرد بۆ پیاوە کوێرەکە: «پیو، کەسێک چووەتە ناو سندووقەکە.»","«لەوێ نییە؟» پیو بە توڕەییەوە پرسی.","«پارەکە لێرەیە، بەڵام هیچ نووسراوێکی فلینت نییە،» وەڵامی دایەوە پیاوەکە.","«ئەو خەڵکانەی مێواندارخانەکەن – ئەو کوڕەیە.","بۆچی چاوەکانم دەرنەهێنا؟» هاواری کرد پیاوە کوێرەکە، پیو.","«پێشتر لێرە بوون – دەرگاکە داخرابوو کاتێک هاتم.","بڕۆن بیاندۆزنەوە.»","هەر ئەو کاتە فیکەکە هات کە پێشتر بیستبوومان، و لە لای گوندەکەوە بوو.","«دیرک دووبارە فیکەی لێدایەوە!» گوتی یەکێک لە پیاوەکان.","«ئەوە مانای وایە کەسێکی بینیوە دێت.","با بڕۆین!»","«بەردەوام بن لە گەڕان!» پیو بە توڕەییەوە هاواری کرد.","«کوڕەکە و دایکی ناتوانن دوور بن.","نزیکە بیدۆزینەوە، و ئێوە دەتانەوێت هەڵبێن؟","ئەگەر بیدۆزینەوە وەک پاشاکان دەوڵەمەند دەبن!»","«بە دەردی بچێت، پیو.","بۆچی ناڕۆین؟","کیسەی پارەکەمان پێیە!» گوتی یەکێک.","پیو دەستی کرد بە هەوڵدان بۆ لێدانی پیاوەکان بە دارەدەستەکەی.","کاتێک شەڕەکە بەردەوام بوو، دەنگی ڕاکردنی ئەسپ لە سەرەوەی گردەکەوە هات.","دەریاوانەکان زوو شەڕیان وەستاند و هەڵاتن، و پیویان بەجێهێشت کە بە نیگەرانییەوە بەسەر ڕێگاکەدا تەق-تەقی دەکرد بە تەنها.","هەر ئەو کاتە، چوار یان پێنج ئەسپ لە ڕووناکی مانگدا دەرکەوتن و لە گردەکەوە بەرەو مێواندارخانەکە ڕایان دەکرد.","پیو هاواری کرد و، نەیدەزانی بەرەو کام لا بڕوات، ڕاستەوخۆ بەژێر یەکەم ئەسپدا ڕای کرد.","بە هاوارێکی ترسناکەوە کەوت.","ئەسپەکان وەستان و کوڕەکەم ناسییەوە کە لە گوندەوە چووبوو بۆ هێنانی دوکتۆر لایڤسی.","لەگەڵیدا چەند ئەفسەری یاسا هەبوون کە لە ڕێگا لەگەڵ ماڵی دوکتۆر بینیبوونی.","پیوی مردبوو.","گەڕاینەوە بۆ ئەوەی دایکم بدۆزینەوە و بیبەین بۆ گوند.","لەوێ دوای کەمێک کاتی باش چاک بووەوە.","ئەفسەرانی یاسا بەرەو کەنداوە نزیکەکە چوون، بەڵام درەنگ بوو؛ کەشتییە نامۆکە پێشتر ڕۆیشتبوو، و زۆر بە گومانەوە دزە دەریاییەکانی تریشی لەگەڵ خۆی بردبوو.","کاتێک سەرکردەی پیاوەکان، بەڕێز دانس، لە کەنداوەکە گەڕایەوە، هەموو ئەو شتانەم بۆ گێڕایەوە کە ڕوویان دابوو.","«دەڵێیت شتێکی زیاتر لە پارەیان دەویست؟","کەواتە، هاوکینز، لە دنیا بۆ چی بەدوای چی دەگەڕان؟» لێی پرسی.","«باوەڕم وایە ئەو شتەی کە دەیانەوێت لە گیرفانمە،» وەڵامم دایەوە، «و دەمەوێت بیگەیەنمە دەست دوکتۆر لایڤسی، تا لە شوێنێکی سەلامەت بێت.»","«بە دڵنیاییەوە کوڕم،» گوتی، «بەڵێ، خۆم دەچم بۆ لای ئەو و هەموو شتەکەی بۆ دەگێڕمەوە.","بۆچی لەگەڵم نایەیت؟»","دوکتۆر لایڤسیم لە هۆڵەکە دۆزییەوە، لەوێ لەگەڵ خاوەنەکە نانی ئێوارەی دەخوارد.","خزمەتکارێک بەناو ماڵە گەورەکەدا ڕێی پێدانین بۆ کتێبخانەکە، لەوێ هەردوو پیاوەکە لەتەنیشت ئاگرەکە جەستەیان دەکێشا.","خاوەنەکە پیاوێکی بەرز و بەهێز بوو، برۆیەکانی زۆر ڕەش بوون و کاتێک قسەی دەکرد زۆر دەجوڵان.","«وەرە ژوورەوە، بەڕێز دانس،» بە دەنگێکی بەرز گوتی.","«ئێوارەت باش،» دوکتۆر گوتی.","«ئەمڕۆ چی هێناوتانە ئێرە؟»","بەڕێز دانس هەستا و چیرۆکەکەی گێڕایەوە، و دوو پیاوە جۆنتڵمانەکە بە سەرسوڕمان و حەزەوە گوێیان لێی گرت.","«کەواتە جیم،» دوکتۆر کاتێک دانس تەواوی کرد گوتی، «ئەو شتەی دەیانویست لەلای تۆیە؟»","«ئەمەیە بەڕێز،» گوتم و دامە دەستی.","بۆ ماوەیەکی کەم لە دەستی گرت و پاشان بە وریاییەوە خستیە گیرفانەکەی.","«خاوەنەکە،» گوتی، «بەڕێز دانس دەگەڕێتەوە ماڵەوە، بەڵام پێموایە هاوکینز ئەم شەوە لە ماڵی من بمێنێتەوە و نانی پێ بدەین.»","کەواتە من لە هۆڵەکە نانێکی زۆر خۆشم خوارد لە کاتێکدا قسەمان دەکرد.","«من باسی ئەم پیاوە فلینتم بیستووە،» بەڕێز ترێلاونی، خاوەنەکە، گوتی.","«ئەو مەترسیدارترین دزە دەریایی بوو کە هەر لە دەریادا ڕۆیشتبێت.","کەشتییەکەم بینیوە، بە چاوی ترسناک کە لەسەر بادبانەکانی کێشرابوون.»","«بەڵام پارەی هەبوو؟» دوکتۆر پرسی.","«پارە!» خاوەنەکە هاواری کرد.","«چۆن چیرۆکی گەنجینەکەی نەبیستوویت؟","ئەگەر پارە نەبوو، ئەو پیاوە خراپانە بەدوای چی دەگەڕان؟»","«تەنها پێم بڵێ،» دوکتۆر وەڵامی دایەوە، «ئەگەر لە گیرفانم زانیاریم هەبێت لەسەر ئەوەی فلینت گەنجینەکەی لە کوێدا شاردووەتەوە، ئەمە واتای چییە کە دەبێت بیکەین؟»","«واتای چییە؟» خاوەنەکە هاواری کرد، «ئەگەر ئەو زانیارییەمان هەبێت کە باسیت دەکەیت، واتە من دەچم بۆ بریستۆل و کەشتییەک دەکڕم، و ئەو گەنجینەیە دەدۆزینەوە، تەنانەت ئەگەر پێویست بێت ساڵێک بەدوایدا بگەڕێین.»","«باشە،» دوکتۆر گوتی و پاکەتەکەی لەسەر مێزەکە لەبەردەمی خۆی دانا.","«ئێستا، ئەگەر جیم ڕازی بێت، پاکەتەکە دەکەمەوە،» و دەستی کرد بە کردنەوەی قوماشەکەی کە داپۆشیبوو.","لەناوی ئەوەدا دوو شت هەبوون؛ کتێبێک و پەڕەیەکی پێچراو.","کتێبەکە پڕ بوو لە ناو، ژمارە و بەروار.","«ئەمە کتێبی حسابی بێڵ بۆنزە!» خاوەنەکە هاواری کرد.","«ئەو ناوانە ناوی ئەو کەشتییانەن کە ئەو نوقاندوونی، و ژمارەکان ئەو پارەیە پیشان دەدەن کە لێیانی بردووە.»","دوکتۆر بە وریاییەوە پەڕە پێچراوەکەی کردەوە و نەخشەیەکی دوورگەمان بینی کە هەموو وردەکارییەکانی تێدا بوو؛ پانی و درێژی جۆگرافی، ناوی گردەکان و کەنداوەکان، گردێکی گەورە لە ناوەڕاست بە ناوی «دوربین»، و هەموو ئەو وردەکارییەی کە کاپتنێک پێویستی پێیەتی بۆ ئەوەی کەشتییەک بە سەلامەتی بهێنێتە ناوەوە.","سێ نیشانەی سووری هەبوو؛ یەکێکیان لە باشووری ڕۆژئاوا بوو و لەتەنیشتی نووسرابوو: «زۆربەی گەنجینەکە لێرەیە.»","نیشانە سوورەکەی دووەم شوێنی ئەو زیوەی پیشان دەدا کە شاردراوەتەوە، و سێیەمەکە شوێنی چەکەکان بوو.","لە پشتەوەی نەخشەکە تێبینی و ڕێنماییی ورد هەبوون.","من نەخشەکەم تێنەدەگەیشت، بەڵام خاوەنەکە و دوکتۆر لایڤسی زۆر خۆشحاڵ بوون.","«تا سبەی ئێوارە لە بریستۆل دەبم،» خاوەنەکە گوتی.","«پاشان لە ماوەی سێ هەفتەدا بە باشترین کەشتی، بەڕێز، و کارامەترین دەستەی کەشتیوانان لە ئینگلتەرا دەڕۆین.","هاوکینز، تۆ دەبیت کوڕی کابین، و تۆ لایڤسی، دوکتۆری کەشتی.","من دەبم ئەمیرەڵ!","پیاوەکانم، ڕێدروث و جۆیس و هانتەر، ئەوانیش لەگەڵ خۆمان دەبەین.","با باش بێت، گەشتەکە خێرا بێت و هیچ کێشەیەک لە دۆزینەوەی گەنجینەکە نەبێت، و پارەیەکی زیاتر لەوەی بتوانین خەیاڵی لێ بکەین بەدەست بهێنین.»","«ترێلاونی،» دوکتۆر گوتی.","«لەگەڵت دەچم، و پێموایە جیمیش دەچێت.","بەڵام تەنها لە یەک پیاو دەترسم.»","«ئەو کێیە؟» خاوەنەکە بە ڕووخسارێکی نیگەرانە پرسی.","«تۆ،» دوکتۆر وەڵامی دایەوە، «چونکە ناتوانیت نهێنی بپارێزیت.","ئێمە تەنها ئەو پیاوانە نین کە لەبارەی ئەم بەڵگەنامەیە دەزانین.","ئەو پیاوانەی ئەمشەو هێرشیان کردە سەر مێواندارخانەکە دوور نین، دڵنیام.","و بەپێی قسەی جیم، ئەوان ئەو پارەیەیان دەوێت.","دەبێت زۆر وریا بین تا دەکەوینە ڕێگا، و نابێت وشەیەک لەبارەی ئەم نەخشەیە بە هیچ کەس بڵێین.»","«لایڤسی،» خاوەنەکە وەڵامی دایەوە، «حەقت لەگەڵە.","من وەک گۆڕستان بێدەنگ دەبم.»","زیاتر لە سێ هەفتەی خایاند تا ئامادە بووین بۆ چوونە دەریا.","کەشتییەک لەلایەن خاوەنەکەوە ئامادە دەکرا، و دوکتۆر لایڤسی بانگ کرابوو بۆ لەندەن.","لەو ماوەیەدا من لە هۆڵەکە لەگەڵ تۆم ڕێدروثی پیر ژیام، و کاتژمێرەکانم بە سەیرکردنی نەخشەکە بەسەر دەبرد، هەموو وردەکارییە بچووکەکانم لە خەیاڵدا دادەنا و خەونم دەبینی کە کاتێک بەڕاستی بگەینە دوورگەکە چی ڕوودەدات.","کەواتە هەفتەکان تێپەڕین تا ڕۆژێکی جوان نامەیەک گەیشت.","بریستۆل،","هاوکینزی خۆشەویست، کەشتییەکەمان کڕیوە و ئامادەیە بۆ چوونە دەریا.","چە کەشتییەکە!","ئاسانە بۆ بەڕێوەبردن، دوو سەد تۆن کێشی هەیە و ناوی «هیسپانیۆلا»یە.","هاوڕێ کۆنەکەم، بلاندلی، یارمەتی دام بۆ بەدەستهێنانی.","ئەو زۆر ماندوو بوو بۆ من، و دەبێت بڵێم هەمووانی تریش لە بریستۆل هەمان کارەیان کرد، هەر کاتێک بیستیان بۆ کوێ دەچین؛ بۆ دۆزینەوەی گەنجینەکە، مەبەستم ئەوەیە.","دۆزینەوەی دەستەی کەشتیوانان لە سەرەتا کێشە بوو، و تەنها چەند پیاوێکم دۆزییەوە.","بەڵام پاشان بە بەختەوە دەریاوانێکی بە تەمەنم بینی.","ئەو مێواندارخانەیەکی هەیە، بۆیە هەموو دەریاوانەکانی بریستۆل دەناسێت.","ماوەیەک نەخۆش بوو، بەڵام ئێستا دەیەوێت وەک چێشتلێنەری کەشتی کار بکات تا دووبارە بگەڕێتەوە دەریا.","پێی دەڵێن «لۆنگ جۆن سیڵڤەر»، و یەک قاچی لەدەست داوە.","پیاوێکی بێچارەیە.","دەستبەجێ پێم گوت کە چێشتلێنەری کەشتییەکەمان دەبێت.","باشە، پێموابوو تەنها چێشتلێنەرێکم دۆزیوەتەوە، بەڵام لەگەڵ ئەوەشدا دەستەیەکی تەواوی کەشتیوانانم دۆزییەوە.","زوو دەستەیەکی لە بەهێزترین دەریاوانە پیرەکان بۆمان دۆزییەوە.","پاشان دوو کەسی لاوازتر لەو شەش یان حەوت پیاوەی پێشتر دامەزراندبووم دەرکرد.","من زۆر باشم، بەڵام تا لە دەریا نەبین دڵخۆش نابم، بۆیە تۆ و ڕێدروث سبەی دەبێت بێن بۆ بریستۆل.","پ.ن.","لەبیرم چوو پێت بڵێم بلاندلی، کە ئەگەر تا کۆتایی مانگی ئاب نەگەڕاینەوە کەشتییەک دەنێرێت بۆ گەڕان بەدواماندا، کاپتنێکی بۆمان دۆزیوەتەوە.","کەمێک زۆر جددییە، بەڵام لە هەموو ڕووێکەوە پیاوێکی نایابە؛ گەنجینەیەکی ڕاستەقینە.","«ترێلاونی لەگەڵ خەڵک قسەی کردووە،» بە ڕێدروثم گوت.","«دوکتۆر لایڤسی لەوە دڵخۆش نابێت.»","بەڵام من زۆر خۆشحاڵ بووم کە بیستم کەشتییەکە ئامادەیە.","ڕۆژی دواتر ماڵئاواییم لە دایکی خۆشەویستم و کەنداوی بچووکەکە کردم کە لەوێ لە دوای لەدایکبوونم ژیابووم، پاشان من و ڕێدروث ئێوارەکە بەرەو بریستۆل ڕۆیشتین.","بەیانی زوو لە ڕۆژی دواتر گەیشتینە شارەکە و بەرەو بەندەرەکە ڕۆیشتین بۆ بینینی ترێلاونی.","کەشتی بە هەموو شێوە و قەبارە و نەتەوە جۆراوجۆرەکان لە هەموو دەوروبەری بەندەرەکان بوون.","دەریاوانان لە کاتی کارکردنیان گۆرانییان دەچڕی، هەندێکیان لە خوارەوە و هەندێکی تریشیان لەسەرەوە لە ناو دارەکانی کەشتی بوون.","پاشان لەناکاو، لەبەردەم مێواندارخانەیەکی گەورە، سکوایەر ترێلاونیم بینی کە وەک ئەفسەرێکی زیرەکی دەریایی جل و بەرگی لەبەر بوو.","«ئێرەیت،» هاواری کرد، «دوکتۆر شەوی ڕابردوو لە لەندەنەوە هات.","براڤۆ!","دەستەی کەشتیوانان تەواوە.","سبەی دەڕۆین!»","دوای نانی بەیانی، خاوەنەکە داوای لێکردم نامەیەک بۆ لۆنگ جۆن سیڵڤەر بەرەم.","پێی گوتم بچم بۆ «دوربین»؛ مێواندارخانەیەک لە کۆتایی تری بەندەرەکان.","بە دڵخۆشییەوە چووم، چونکە خۆشحاڵ بووم بتوانم دووبارە بەندەری پڕجوڵە و هەموو کەشتییەکان ببینم.","مێواندارخانەکە پڕ بوو لە دەریاوانی دەنگبەرز، و نزیک بووم زۆر بترسم لەوەی بچمە ژوورەوە.","کاتێک لە دەرگاکە چاوەڕێم دەکرد، پیاوێکم بینی لە ژوورێکی لاوەکییەوە هاتە دەرەوە، و پێموابوو دەبێت لۆنگ جۆن سیڵڤەر بێت.","قاچی چەپەکەی لە نزیک سەرەوە بڕابوو، و لەژێر شانی چەپەوە دارێکی پشتگیریی هەڵگرتبوو کە بە ئاسانی پێی دەجوڵایەوە.","زۆر بەرز و بەهێز بوو، ڕووخسارێکی زیرەکی هەبوو، و بە پێکەنینەوە خزمەتی خەڵکی سەر مێزەکان دەکرد.","لە یەکەم جارەوە کە نامەکەی ترێلاونیم لەبارەی لۆنگ جۆن سیڵڤەر خوێندبووەوە، دەترسام ئەو هەمان دەریاوانە یەک قاچە بێت کە کاپتن باسی کردبوو.","بەڵام تەنها یەک سەیرکردنی ئەم پیاوە بەس بوو.","کاپتن، بلاک داگ و پیاوە نابیناکە پیویم بینیبوون، و پێموابوو دەزانم دزێکی دەریایی چۆنە؛ بە تەواوی جیاواز لەم مێواندارخانەوانە پاک و خۆشەویستە.","نزیکتر بوومەوە، نامەکەم بەرزکردەوە و گوتم: «بەڕێز سیڵڤەر؟»","«بەڵێ کوڕم.","تۆ کێیت؟» وەڵامی دایەوە.","نامەکەم دامێ.","«ئا!» بە دەنگێکی بەرز گوتی و وادیار بوو سەرسام بوو.","«تۆ کوڕی نوێی کابینیت.","زۆر دڵخۆشم بە ناسینت.»","لەو ساتەدا سەرنجم دا بە یەکێک لە پیاوەکان کە لە لایەکی تری ژوورەکە دانیشتبوو؛ لەناکاو هەستا و بەرەو دەرگاکە ڕۆیشت.","دەستبەجێ ناسیمەوە.","«هەی!» هاوارم کرد.","«ڕایگرن!","ئەو بلاک داگە؛ یەکێکە لە دزە دەریاییەکان!»","«گرنگ نییە کێیە،» سیڵڤەر هاواری کرد.","«بەڵام پارەی خواردنەوەکانی نەداوە.","هەری، ڕابکە و بیگرە.»","پیاوێک لە نزیک دەرگاکە هەستا و بەدوایدا لە مێواندارخانەکە دەرچوو.","«گوتت ئەو کێیە؟","دزێکی دەریایی؟","لە مێواندارخانەکەی من!","باوەڕم ناکرێت!» سیڵڤەر گوتی، کە ئێستا زۆر هیجان‌دار بوو.","«مۆرگن!» بانگی پیاوێکی کرد کە لە بارەکە دانیشتبوو.","«تۆ لەگەڵی دەخواردەوە.","پێشتر هەرگیز ئەوت نەبینیوە، وایە؟","ناوی ئەوت نەدەزانی، وایە؟»","کاتێک بلاک داگم لە «دوربین» بینی، نیگەران بووم، و بە وریاییەوە چاوم لە چێشتلێنەرەکە بوو.","بەڵام ئەو زۆر ئامادە و زۆر زیرەک بوو بۆ من.","پێی دەکەنیم و گاڵتەمان دەکرد، و گوتی من کوڕێکی زیرەکم.","تا هەری بە دەستی بەتاڵ گەڕایەوە و سیڵڤەر بە دەنگێکی بەرز هاواری لێکرد، دڵنیابووم سیڵڤەر پیاوێکی ڕاستگۆیە.","کەمێک دواتر، منی بردەوە بۆ لای ترێلاونی و پێکەوە بەسەر بەندەرەکاندا ڕۆیشتین.","زۆر سەرنجڕاکێش بوو، و هەموو شتێکی لەبارەی کەشتی جیاوازەکانی بەردەمانەوە بۆ گێڕامەوە؛ ڕێکخستنی بادبانەکان، کێش و نەتەوەکەیان و ئەوەی بۆ کوێ دەڕۆن.","لۆنگ جۆن بە هیجانەوە هەموو چیرۆکەکەی بۆ خاوەنەکە و دوکتۆر گێڕایەوە.","هەردوو جۆنتڵمانەکە گوتیان خەمە کە بلاک داگ هەڵات، بەڵام هەموومان ڕازی بووین کە هیچ شتێک ناکرێت بکرێت.","کاتێک لۆنگ جۆن ڕۆیشت، هەردوو پیاوەکە سوپاسیان کرد بۆ ئەو ماندووبوونەی.","«هەمووان تا کاتژمێر چوار لە کەشتی بن.» خاوەنەکە دوای ئەوە هاواری کرد.","«چە پیاوێکی نایابە!» خاوەنەکە گوتی و پاشان ڕووی لە من کرد.","«ئێستا لەگەڵمان وەرە، هاوکینز، با کەشتییەکە ببینین.»","کاتێک سەرکەوتینە سەر هیسپانیۆلا، هاوڕێی نوێی کەشتی، بەڕێز ئارۆ، پیاوێکی دەریایی پیر و قاوەیی‌رەنگ کە گوێوارەی لە گوێ بوو، پێشوازیمان لێکرد.","ئەو و خاوەنەکە زۆر دۆستانە بوون، بەڵام زوو تێبینی کردم کە پەیوەندیی نێوان خاوەنەکە و کاپتن هەمان شت نەبوو.","کاپتن سمۆلێت وادیار بوو لە هەموو شتێکی ناو کەشتی تووڕەیە و هیچ کاتێکی لەدەست نەدا بۆ هاتنە کابینەکە و پێگوتنی ئەمە بە خاوەنەکە.","«بەڕێز، من حەزم لەم گەشتە ناکات، حەزم لە پیاوەکان ناکات، و حەزم لە ئەفسەرەکەم ناکات.","کورت و ڕوونە،» کاپتن گوتی.","«لەوانەیە، بەڕێز، حەزت لە کەشتییەکەش نەبێت؟» خاوەنەکەی کە بە ڕوونی تووڕە بوو پرسی.","«ئەوە ناتوانم بڵێم، چونکە هێشتا نەمدیوە چۆن کار دەکات،» کاپتن وەڵامی دایەوە.","«وادیارە کەشتییەکی باشە، بەڵام زیاتر لەوە ناتوانم بڵێم.»","لەو ساتەدا دوکتۆر لایڤسی قسەی کرد.","«یەک خولەک چاوەڕێ بکە،» گوتی.","«ئەمە بە هیچ شێوەیەک یارمەتیدەر نییە.","دەمەوێت ڕوونکردنەوەی ئەوە ببیستم کە کاپتن گوتوویەتی.","تۆ دەڵێیت حەزت لەم گەشتە نییە.","ئێستا بۆچی؟»","«من ئەم کارەم بەوە وەرگرت کە پێی دەڵێین “فەرمانی داخراو”؛ واتە ڕازیم بوو کەشتییەکە بڕۆخێنم بەبێ ئەوەی پێشتر بزانم بۆ کوێ دەچین،» کاپتن گوتی.","«بەڵام ئێستا دەبینم هەموو دەریاوانەکان لە من زیاتر دەزانن.","دواتر،» کاپتن بەردەوام بوو، «لە دەریاوانەکانی خۆمەوە دەبیستم کە دەچین بەدوای گەنجینە بگەڕێین.","گەنجینە مەترسیدارە، و من حەزم لە گەشتەکانی گەنجینە نییە، بە تایبەتی کاتێک نهێنین.»","«تێدەگەم چی دەڵێیت، و دەبێت بڵێم بەڕاستی ڕاستە،» دوکتۆر لایڤسی وەڵامی دایەوە.","«تۆ دەڵێیت حەزت لە دەریاوانەکان نییە.","ئایا دەریاوانی باش نین؟»","«من حەزم لێیان نییە، بەڕێز،» کاپتن سمۆلێت وەڵامی دایەوە.","«و خۆم نەمتوانیوە هەڵیان بژێرم.»","«و حەزت لە بەڕێز ئارۆش نییە؟» دوکتۆر بەردەوام بوو.","«نا، بەڕێز.","باوەڕم وایە دەریاوانێکی باشە، بەڵام زۆر لەگەڵ دەریاوانەکان دۆستانەیە بۆ ئەوەی ئەفسەرێکی باش بێت.»","«باشە، کاپتن،» دوکتۆر لایڤسی گوتی، «پاشان پێمان بڵێ چی دەوێت.»","«دوو شتم هەیە،» کاپتن گوتی.","«یەکەم، باروت و چەکەکان دەبێت لەژێر کابینەکە و نزیک پاشەکەوتی کەشتی دابنرێن، نەک لەو شوێنەی ئێستا دانراون.","و دووەم، ئەو دەریاوانانەی تۆ لەگەڵ خۆت هێناون دەبێت لە دواوە و نزیک کابینەکە بخەون.","هەروەها پێشتر زۆر قسە کراوە.»","«زۆر زۆر،» دوکتۆر ڕازی بوو.","«دەگوترێت نەخشەی دوورگەیەکت هەیە،» کاپتن سمۆلێت گوتی، «لەسەری خاڵی خاچ هەیە بۆ نیشاندانی شوێنی گەنجینە، و دوورگەکە لە …» پاشان وردەکارییەکانی پانی و درێژی جۆگرافییەکەی گوت.","«من هەرگیز ئەوەم بە کەس نەگوتووە!» سکوایەر هاواری کرد.","«دەریاوانەکان دەیزانن،» کاپتن گوتی.","«لایڤسی، ئەمە دەبێت تۆ یان هاوکینز بووبێت،» سکوایەر هاواری کرد.","«گرنگ نییە کێ بووە،» دوکتۆر وەڵامی دایەوە.","«باشە،» کاپتن بەردەوام بوو، «نازانم کێ ئەم نەخشەیەی لایە، بەڵام دەبێت تەنانەت لە من و بەڕێز ئارۆشیش نهێنی بێت.»","«تێگەیشتم،» دوکتۆر گوتی.","«دەته‌وێت ئەم بابەتە نهێنی بپارێزین، و بەشی دواوەی کەشتی بکەین بە سەنگەرێک، بە پیاوەکانی هاوڕێکەم و بە هەموو چەک و باروتی ناو کەشتییەوە.","تۆ لە یاخیبوون دەترسیت.»","«من ئەوەم نەگوت،» کاپتن سمۆلێت گوتی.","«باوەڕم وایە بەڕێز ئارۆ پیاوێکی ڕاستگۆیە، و هەندێکی تریش وایە.","بەڵام کارەکەی من ئەوەیە دڵنیابم کە کەشتییەکە و هەموو پیاوەکانی ناوی سەلامەتن.","تەنها ئەوەی لێتان دەخوازم ئەوەیە زۆر وریا بن، یان ڕێم بدەن کەشتییەکە بەجێبهێڵم.","هەر ئەوە.»","دوکتۆر و سکوایەر لەگەڵ پێشنیارەکانی کاپتن سمۆلێت ڕازی بوون، پاشان کاپتن لە کابینەکە چووە دەرەوە.","«ترێلاونی،» دوکتۆر پاشان گوتی، «سەرسامم، بەڵام تۆ توانیوتە دوو پیاوی ڕاستگۆ لەگەڵ خۆت بهێنیتە سەر کەشتی؛ ئەو پیاوە و جان سیڵڤەر.»","هەموو شەوەکە زۆر سەرقاڵ بووین بە ئامادەکردنی کەشتی بۆ ڕۆیشتن.","خۆر خەریک بوو هەڵدەهات کە هەمووان چوونە شوێنەکانیان، ئامادەی جێهێشتنی بەندەر.","«گۆرانییەکمان بۆ بخوێنەوە،» یەکێک لە دەریاوانەکان بانگی لۆنگ جۆنی کرد.","«ئەو کۆنەیە،» دەریاوانێکی تر هاواری کرد.","لۆنگ جۆن سیڵڤەر، کە لە نزیکەوە ڕاوەستابوو، دەستی کرد بە گۆرانییەکەی کە زۆر باش دەمانزانی: «پانزە پیاو لەسەر سندووقی مردووەکە –» پاشان هەموو دەریاوانەکان پێکەوە گوتیان: «یۆ-هۆ-هۆ، و بوتڵێک ڕۆم!»","لە وشەی کۆتاییدا دەریاوانەکان دەستیان بە توندی لەسەر دەستەکانی کەپستانەکە کرد.","ساتێکی پڕ لە هیجان بوو، و گۆرانییەکە لە یەک چرکەدا بیرمی خستەوە کە چۆن لە ئەدمیراڵ بێنبۆ بووم، و وام هەست کرد کاپتنی پیرەکەش گۆرانی دەڵێت.","بەڵام زوو لەنگەرەکە هەڵکرا و لە پێشەوەی کەشتی هەڵواسرا.","بادبانەکان دەستیان کرد بە پڕبوون لە با، و پێش ئەوەی بتوانم یەک کاتژمێر بخەوم، هیسپانیۆلا گەشتی بەرەو دوورگەی گەنجینەی دەستپێکرد.","ناچمە ناو هەموو وردەکارییەکانی ئەو گەشتە؛ کەشتییەکە باش بوو، دەریاوانەکان دەریاوانی شارەزا بوون و کاپتن بە دڵنیاییەوە دەیزانی چی دەکات.","بەڵام کاتێک گەیشتینە دوورگەی گەنجینە، دوو یان سێ شت ڕوویدا کە پێویستە بۆتان بگێڕمەوە.","یەکەم، بەڕێز ئارۆ لەوەی کاپتن ترسابوو خراپتر بوو.","کۆنترۆڵی دەریاوانەکانی نەبوو و خەڵک هەرچیان دەویست دەیانکرد.","پاشان، دوو ڕۆژێک یان زیاتر لە دەریادا، دەستی کرد بە ڕەفتارکردن وەک پیاوێک کە سەرخۆشە.","دووبارە و دووبارە دەیانبردە خوارەوەی کەشتی چونکە نەتوانیبوو کارەکەی بە دروستی بکات.","بەڵام هیچ کەس نەیدەزانی لە کوێوە ئەو خواردنەوەیەی دەهێنا.","بۆیە کەس زۆر سەرسام نەبوو و خەمیشی نەخوارد، کاتێک شەوێکی تاریک و زریانێکدا ون بوو و دووبارە نەبینرا.","«دەبێت لە لای کەشتییەکە کەوتبێتە خوارەوە،» کاپتن گوتی.","لە ماوەی گەشتەکەدا لۆنگ جۆن سیڵڤەرم ناسیت و بینیم چۆن کار دەکات.","هەرچەندە تەنها یەک قاچی هەبوو، بە ئاسانێکی سەرسوڕهێنەر لەسەر کەشتی دەجوڵایەوە.","دەریاوانەکان ئەوەیان دەکرد کە پێی دەگوتن و وادیار بوو حەزیان لێیە.","لەگەڵ هەمووان دۆستانە بوو و هەمیشە دڵخۆش بوو کاتێک منی لە چێشتخانەکە دەبینی، کە زۆر پاکی ڕادەگرت.","«هاوکینز، وەرە قسەیەک لەگەڵ جان بکە،» زۆرجار دەیگوت.","«ئەمە کاپتن فلینتە، بە ناوی دزە دەریاییە بەناوبانگەکە ناونراوە،» و ئاماژەی بە تووتییەکەی دەکرد کە لە قەفەسێک لە گوشەی چێشتخانەکەدا هەڵیگرتبوو.","تووتییەکەش دووبارە و دووبارە دەیگوت: «پارچەی هەشت! پارچەی هەشت!» تا جان پارچە قوماشێکی بەسەر قەفەسەکەدا دادەنا.","«ئەم تووتییە کۆنە هەموو شوێنێکی بینیوە.","دەڵێت “پارچەی هەشت” چونکە لەوێ بووە کاتێک کەشتییەکان لە بن دەریاوە دەهێنرایەوە و سی و پێنج هەزار پارەی ئەو جۆرەیان لەسەر بوو،» چێشتلێنەرەکە ڕوونی کردەوە.","پێش ئەوەی بگەینە دوورگەی گەنجینە، شتێک ڕوویدا کە بە شێوەیەکی زۆر گەورە بۆچوونم لەبارەی لۆنگ جۆن سیڵڤەر گۆڕی.","لەسەر تەختەی کەشتیەکە بەرمیلێک سێوی تێدا بوو.","ئێوارەیەک، کاتێک کارم تەواو کرد، چوومە سەر تەختەکە بۆ ئەوەی سێوێک بهێنم.","چوومە ناو بەرمیلەکە و بینیم بە زەحمەت چەند سێوێک ماوە.","بەڵام لەوێ لە تاریکیدا دانیشتم، لەگەڵ جوڵەی نەرم و هێمنی کەشتییەکە، دەبێت خەوم لێکەوتبێت.","لەناکاو بەئاگا هاتمەوە کاتێک کەسێک بە قورسایی لەسەر بەرمیلەکە پاڵی دا.","پاشان پیاوەکە دەستی کرد بە قسەکردن.","دەنگی سیڵڤەر بوو.","ترساوم و دانیشتم و گوێم گرت.","«نا.","فلینت کاپتن بوو، نەک من،» سیڵڤەر گوتی.","«من چاودێری کەرەستە و پێداویستییەکانم دەکرد.","لە هەمان کاتدا کە پێو لەدەستدا، پێو چاوەکانی لەدەستدا.","بەڵام دواتر کەشتیی فلینتم بینی، ئەوەندە بە زێڕ قورس بوو کە پێموابوو دەخنکێت.»","«ئا!» دەنگێکی تر گوت؛ دەنگی دیک، گەنجترین پیاو لەسەر کەشتی، «فلینت باشترین هەموویان بوو!»","«باشە، من دوو هەزار لە فلینتم وەرگرت.","بۆ دەریاوانێکی سادە خراپ نییە، وایە؟","هەمووم لە بانکدا بە سەلامەتی هەڵگرت.","هەموو شتێک پەیوەندی بە پاشەکەوتکردنەوە هەیە.","بەڵام پیاوەکانی فلینت ئێستا لەکوێن؟","زۆربەیان لەسەر ئەم کەشتییەن و خۆشحاڵن بە پارەیەک کار بکەن،» سیڵڤەر گوتی.","«دەبینیت، من پارەکەم پاشەکەوت دەکەم، لە کاتێکدا ئەو پیاوە دەوڵەمەندانەی تر هەمووی بۆ ڕۆم و خۆشی بەکاردێنن.","پاشان کاتێک هیچ شتێکیان نامێنێت جگە لە کراسەکانیان، دەبێت دووبارە بچنە دەریا.","ئەوانیش دەبوو دووبارە بچنە دەریا، کاتێک هیچ شتێکیان نەماوە جگە لە کراسەکانیان.","بەڵام ئێستا پەنجام ساڵە، و کاتێک ئەم گەشتە تەواو بکەم، دەتوانم تا کۆتایی ژیانم لە شوێنێک بژیم.»","«بەڵام دوای ئەمە ناتوانیت بگەڕێیتەوە بۆ بریستۆڵ،» دەنگەکەی تر گوت.","«ڕاستە، و ژنەکەم ئێستا هەموو پارەکەم بەدەستەوەیە.","دوربین دەفرۆشێت و کاتێک تەواو بووم لە شوێنێک دوور لە بریستۆڵ پێم دەگات،» لۆنگ جۆن ڕوونی کردەوە.","«ئێستا کە لەگەڵ تۆ قسەم کردووە، زۆر حەزم لە کارەکەمە،» گەنجەکە گوتی.","«کوڕێکی بوێریت و زیرەکیشیت،» سیڵڤەر وەڵامی دایەوە.","«و هەرگیز جەنتڵمەنێکی دەوڵەمەند لە تۆ باشترم نەبینیوە.»","لەو کاتەدا تێگەیشتم کە کاتێک سیڵڤەر دەیگوت «جەنتڵمەنەکانی بخت»، مەبەستی دزە دەریاییەکان بوو، و زانیم کە تازە یەکێک لە پیاوە ڕاستگۆکانی کەشتییەکەی خستووەتە ڕێگای خۆی.","چەند خولەکێک دواتر سیڵڤەر پیاوێکی تری بانگ کرد بۆ لای بەرمیلەکە.","«دیک لەگەڵ ئێمەیە،» سیڵڤەر گوتی.","«ئا، دەموێست دەبوو بێت،» دەنگی سەرکەشتیوان، ئیسرائیل هاندز، وەڵامی دایەوە.","«بەڵام کەی دەست بە هیچ شتێک دەکەین؟","من خواردن و خواردنەوەکانی ئەوانم دەوێت،» گوتی.","«ئێستا،» لۆنگ جۆن سیڵڤەر دەستی پێکرد، «کاپتن سمۆلێت دەریاوانێکی نایابە، و دوکتۆر و سکوایەر نەخشەکەیان لە شوێنێکی نهێنییە، کە واتە من نازانم لە کوێیە، وایە؟","بۆیە من دەڵێم چاوەڕێ بکەین تا گەنجینەکەیان بدۆزینەوە و یارمەتی بدەین بیهێننە سەر کەشتی.»","«بەڵام هەموومان دەریاوانین لەسەر ئەم کەشتییە!» ئیسرائیل هاواری کرد.","«پێویستمان بە سمۆلێت و ئەوانی تر نییە.»","«دەتوانین کەشتییەکە بڕۆخێنین،» سیڵڤەر بە توڕەیی گوتی، «بەڵام کێ دەزانێت بۆ کام ئاراستە دەبێت بچین؟","گوێ بگرە، من جۆری پیاوەکەی تۆ دەناسم.","هەرگیز دڵخۆش نابیت تا سەرخۆش نەبیت، و پاشان هەڵە دەکەیت.","بەڵام من دەزانم چۆن ئەمە بکەم و باوەڕم پێ بکە، ئەگەر زۆر بەخێرایی بیکەین، ئەوا سێدارەمان دەدرێت.»","«باشە، بەڵام کاتێک دەستیان بەسەردا گرتین، چییان بەسەر دەهێنین؟» دیک پرسی.","«دەتوانین لە دوورگەکە جێیان بهێڵین، یان دەتوانین بیانکوژین؛ فلینت یان بیلی بۆنز ئەوەیان دەکرد،» سیڵڤەر گوتی.","«من دەڵێم دەبێت بیانکوژین.","چاوەڕێ دەکەین، پاشان دەیکەین،» سیڵڤەر گوتی.","«ئێستا با کەمێک ڕۆم بخۆینەوە!» «دیک،» سیڵڤەر گوتی، «دەهێڵم تۆ بیهێنیت.","ئەمە کلیلییەکەیە.","پیاڵەیەک پڕ بکە و بیهێنە سەرەوە.»","تێگەیشتم کە ئەمە دەبێت ئەو ڕێگایە بووبێت کە بەڕێز ئارۆ خواردنەوەکەی پێدەگەیشت کە کوشتی.","کاتێک دیک ڕۆیشت، بیستم ئیسرائیل بە دەنگی نزم لەگەڵ سیڵڤەر قسە دەکات.","بیستم گوتی: «چیتر هیچ پیاوێکی ئەوان بە ئێمە ناچێت.»","بۆیە بیرم کردەوە کە دەبێت هێشتا دەریاوانی ڕاستگۆ لەسەر کەشتی مابن.","چەند ساتێک دواتر مانگ دەستی کرد بە ڕووناککردنەوەی سەر بەرمیلەکە لەسەرم، و نزیکەی هەمان کات دەنگێک هاواری کرد: «خاک لە پێشەوە!»","پیاوەکان هەڵاتن بۆ سەر تەختەکە، و من بە خێرایی لە بەرمیلەکە هاتمە دەرەوە بەبێ ئەوەی کەس بمبینێت و لە پێشەوە لەگەڵیان بووم.","لە باشووری ڕۆژئاوا سێ چیاکەی دوورگەی گەنجینە دیار بوون.","بیستم سیڵڤەر بە کاپتن سمۆلێتی دەگوت کە ساڵانێک پێشتر لەمێرە لە کەنداوێک ڕاوەستابوو بۆ هێنانی پێداویستی و ئاو.","«سەیری ئەم نەخشەیە بکە،» کاپتن سمۆلێت گوتی، «و شوێنەکە پیشانم بدە.»","چاوەکانی لۆنگ جۆن کە نەخشەکەی وەرگرت، وەک ئاگر دەدرەوشانەوە.","بەڵام نەخشەکە ئەو نەخشەیە نەبوو کە لە سندووقی بیلی بۆنز دۆزیمانەوە.","کۆپییەکی نوێ بوو، بە هەموو وردەکارییەکانی جگە لە خاچە سوورەکان و تێبینییە نووسراوەکان.","دەبوو سیڵڤەر دڵشکاو بووبێت، بەڵام توانی باش بشارێتەوە.","چەند ساتێک دواتر، کاتێک ئەوەندە نزیک بووم لە دوکتۆر لایڤسی، بە بێدەنگی پێم گوت پێویستم بە خێرایی قسە لەگەڵ ئەو و سکوایەر و کاپتن هەیە لە کابینەکە.","هەموو ئەو شتانەی بیستم بۆیان ڕوونکردەوە.","هەرسێکیان سوپاسیان کردم بۆ بەخت و بوێرییەکەم.","«کاپتن،» سکوایەر گوتی، «تۆ ڕاست بوویت و من هەڵەم کرد.»","ئێستا تێگەیشتبوو لەو هەڵە ترسناکانەی کردبوونی.","«من گەمژەم،» بەردەوام بوو، «و خۆمم خستووەتە ژێر فەرمانی تۆ.»","«یەکەم،» کاپتن دەستی پێکرد، «دەبێت بەردەوام بین، چونکە ناتوانین بگەڕێینەوە.","ئەگەر پێیان بڵێم بگەڕێینەوە، دەستبەجێ هێرشمان دەکەنە سەر.","دووەم، هێشتا کاتمان هەیە، لانیکەم تا ئەو کاتەی گەنجینەکە دەدۆزینەوە.","سێیەم، هێشتا پیاوی ڕاستگۆ هەیە.","ئێستا بەڕێز، دیر یان زوو شەڕێک ڕوودەدات، بۆیە پێموایە دەبێت کاتێک هێرشیان بکەین کە کەمترین چاوەڕوانییان هەبێت.","بەڕێز ترێلاونی، ئایا دڵنیاین ئەو پیاوانەی لە ماڵەوە لەگەڵ خۆت هێناون ڕاستگۆن؟»","«بەڵێ، هەندەی خۆمم ڕاستگۆن،» سکوایەر وەڵامی دایەوە.","«کەواتە سێ پیاون،» کاپتن گوتی، «و دەبن بە حەوت.","ئێستا، پێت وایە کام لە پیاوەکانی تر ڕاستگۆن؟»","«لەوانەیە ئەو پیاوانە بن کە ترێلاونی پێش ئەوەی سیڵڤەر ببینێت دۆزیبوونەوە،» دوکتۆر گوتی.","«بەڵام لەوانەیە نا،» سکوایەر گوتی، «ئیسرائیل هاندز یەکێک لە پیاوەکانی من بوو، بەڵام ئێستا لەگەڵ سیڵڤەرە.»","«باشە،» کاپتن سمۆلێت گوتی، «دەبێت بێدەنگ بمێنینەوە و چاودێری هەموویان بکەین.","نابێت هیچ کارێک بکەین تا نزانین پیاوەکانمان کێن.»","جیم لێرەیە،» دوکتۆر گوتی، «دەتوانێت زیاتر لە هەر کەسێک یارمەتیمان بدات.","پیاوەکان حەزیان لێیە و باشە لە تێبینی کردن.»","دەستم کرد بە زۆر نیگەران بوون، چونکە هەستم دەکرد ناتوانم زۆر یارمەتی بدەم.","لە کۆتاییدا ئەوە بەهۆی منەوە بوو کە ڕزگار بووین.","بەڵام لەو ساتەدا بارودۆخەکەمان زۆر خراپ دەردەکەوت.","لە نێوان بیست و شەش کەسەکەی ناو کەشتی، تەنها حەوت کەسمان دەزانی ڕاستگۆن.","لەو حەوت کەسەش، یەکێکیان تەنها کوڕێک بوو.","دوورگەکە بە تەواوی جیاواز دەردەکەوت کاتێک بەیانیی ڕۆژی دواتر هاتمە سەر تەختەی کەشتی.","لە شەودا گەشتێکی باشمان کردبوو، و کەشتییەکە نزیکەی نیو میل لە باشووری ڕۆژهەڵاتی دوورگەکەوە ڕاوەستابوو.","دارستانی ڕەنگ خۆڵەمێشی بەشێکی زۆری ڕووی زەوی داپۆشیبوو، و گردە بەردینەکان بەرز لەسەر ئەو دارستانەوە هەڵدەکشان.","چیای سپای-گلاس لە دوورگەکە بەرزترین چیا بوو، زیاتر لە سێ یان چوار سەد پێ بەرزتر لەوانی تر، و سەرێکی فراوان و تەختی هەبوو.","دیمەنی دوورگەی گەنجینە حەزم لێ نەبوو.","بە زەحمەت کەشتییەکەمان بردە ناو ڕێڕەوێکی ئاو کە سەلامەت بەڵام تەنگ بوو، لەنێوان دوورگەی گەنجینە و دوورگەی نزیکی سکەلەت، و لەنگەرەکەمان دابەزاند.","دارەکان تا کەناراوەکە دەهاتن، و زەنگێکی ئاوی هەبوو کە دوو ڕووباری بچوکی ئاوی شیرین تێیدا دەڕژان.","هەوا بۆنی گەڵای مردوو و تەڕی دەدا.","هەر کە گەیشتینە دوورگەکە، زۆربەی دەریاوانەکان لەسەر تەختەکە پاڵکەوتبوون و پێکەوە گڵەییان دەکرد.","فەرمانەکان بە هێواشی و بێ‌وریایی جێبەجێ دەکران، و ڕوون بوو یاخیبوون وەک هەورێکی گەورە و ڕەش بەسەرمانەوە هەڵواسراوە.","بڕیارمان دا کۆبوونەوەیەک لە کابینەکە بکەین.","«گەورەم،» کاپتن گوتی، «شتەکان هەموو ڕۆژێک ئاڵۆزتر دەبن، و تەنها یەک پیاو هەیە کە دەتوانێت یارمەتیمان بدات.»","«ئەو کێیە؟» سکوایەر پرسی.","«سیڵڤەر، گەورەم،» کاپتن وەڵامی دایەوە.","«ئەو هەندەی ئێمە نیگەرانە و هەوڵ دەدات ئەوەی ڕوودەدات بشارێتەوە.","هەر کاتێک بتوانێت، لەگەڵ پیاوەکانی قسە دەکات و پێیان دەڵێت زۆر کار بکەن و بێدەنگ بن.","با بە پیاوەکان دوا نیوەڕۆیەک لە دوورگەکە بدەین.","ئەگەر زۆربەیان لەگەڵ سیڵڤەر بچنە کەناراوە ــ دەبینیت ــ ئەو وەک مەڕ دەیانگەڕێنێتەوە بە بێدەنگی.»","بۆیە بڕیار لەسەر ئەوە درا.","سکوایەر، دوکتۆر، کاپتن، من، سێ پیاوی باشی تر و نزیکەی یەک لەسەر سێی دەریاوانەکان دەمانویست لەسەر هیسپانیۆلا بمێنینەوە.","لە هەمان کاتدا سێزدە پیاوەکەی تر، لەگەڵ سیڵڤەر، بە شەپۆلی خۆشحاڵی دەستیان کرد بە چوونە ناو بەلەمە بچووکەکان.","ئەو کاتە یەکەم بیرۆکە شێتانەکەم هاتە مێشکم کە زۆر یارمەتیی ڕزگارکردنی ژیانمان دا.","چونکە پیاوی زۆر کەم لەسەر کەشتی مابوون، پێویستیان بە من لەسەر کەشتی نەبوو.","لە یەک چرکەدا بەسەر لای کەشتییەکەدا هەڵکشام و بە بێدەنگی خۆم خستە خوارەوەی نزیکترین بەلەم.","وام زانی هیچ کەسێک منی نەبینیوە.","بەڵام سیڵڤەر، کە لە بەلەمەکەی تردا بوو، بانگی کرد بزانێت ئایا منم.","گوتم بەڵێ، و لە خۆم پرسی شاید دەبوو لەسەر کەشتی بمامایەوە.","کاتێک بەلەمەکەمان گەیشتە کەناراوە، هەڵپەڕیمە دەرەوە و ڕام کرد بۆ ناو دارستانەکە.","کەمێک دواتر گوێم لە لۆنگ جۆن سیڵڤەر بوو کە بەدوامدا هاواری دەکرد: «جیم، جیم!» بەڵام من نەوەستام.","ڕام و ڕام تا چیتر نەمتوانی ڕابکەم.","دڵخۆش بووم کە لۆنگ جۆنم دوورخستبووەوە، و دەستم کرد بە ئارامبوون.","پاشان، دوای ئەوەی ماوەیەک لە ناو دارستانەکەدا بەردەوام بووم بە ڕۆیشتن، لەناکاو گوێم لە دەنگی پیاوان بوو.","دەنگەکان بەرزتر و نزیکتر بوونەوە، و خۆم لە پشت دارێک شاردەوە.","وام بیرکردەوە دەبێت هەوڵ بدەم گوێ لە گفتوگۆکە بگرم، بۆیە بە بێدەنگی لە ناو دارەکان نزیکتر بوومەوە.","لە کۆتاییدا لەسەر گردێکی کەم بەرز سەیرم کردە خوارەوە بەرەو شوێنێکی کراوەی زەنگ، و بینیم لۆنگ جۆن سیڵڤەر و یەکێک لە دەریاوانەکان.","«هاوڕێ،» سیڵڤەر دەیگوت، «هۆکاری ئەوەیە حەزم لێتە.","ئەگەر لە سەرەتاوە حەزم لێت نەبووایە، پێت وایە ئێستا ئاگاداریت دەکردەوە؟","هەموو شتێک کۆتایی هاتووە، و ناتوانیت هیچ بکەیت بۆ گۆڕینی بارودۆخەکە.","هەوڵ دەدەم ڕزگارت بکەم ــ لەگەڵ ئێمە یەکبگرە، تۆم.»","«سیڵڤەر،» پیاوەکەی تر گوتی، «تۆ پیرە، و ڕاستگۆیت، و پارەشت هەیە، هەروەها بوێریت.","و پێم دەڵێیت دەتەوێت لەگەڵ ئەو پیاوانە یەکبگریت؟","تۆ نا!","پێم خۆشترە دەستم لەدەست بدەم لەوەی دژی ئەرکەکەم بوەستم.»","لەناکاو لە دوورەوە هاوارێکی توڕەیی بەرز هات، پاشان هاوارێکی درێژ و ترسناک.","هاواری مردن بوو، و دەنگەکەی هەرگیز لە مێشکم نەدەچوو.","«ئەوە چی بوو؟» تۆم گوت، لە ترسدا دەڵەرزی.","«ئا،» سیڵڤەر بە پێکەنینێکی هێمن گوت، «دەبێت ئەلان بووبێت.»","«ئەلان!» تۆم هاواری کرد.","«خوا ڕووحی بێخوات!","ئەو دەریاوانێکی ڕاستەقینە بوو.","تۆ ئەلانت کوشتووە، وایە؟","ئەگەر دەتوانیت، منیش بکوژە.»","پاش ئەوە، ئەو پیاوە بوێرە ڕووی وەرگێڕا و بەڕێوە چوو.","سیڵڤەر بە هاوارێکەوە دارە دەستەکەی بە هەموو هێزی خۆی فڕێدا.","دارەکە بە توندی لە ناوەڕاستی پشتی تۆمی کەوت.","کەوتە سەر زەوی، و لە یەک ساتدا سیڵڤەر بەسەریدا هەڵپەڕی و بە چەقۆ کوشتی.","پاشان بینیم سیڵڤەر بە هێواشی خوێنەکە لەسەر چەقۆکەی بە هەندێک گیا پاک دەکاتەوە.","سوتێکەی دەرهێنا و چەند جارێک فووی تێدا کرد.","نەمزانی ئەمە چی مانایە، بەڵامم خەمڵاند کە پیاوی زیاتر دێن.","دەستم کرد بە دوورکەوتنەوە بەو خێرایی و بێدەنگییەی کە دەتوانیم.","ئەوان پێشتر دوو کەسیان کوشتبوو.","ئایا منیش دەتوانم کەسی داهاتوو بم؟","ڕام و ڕام، پڕ لە ترس.","دوای ئەوەی ئەوان ئەو کارەیان کردبوو، چۆن دەتوانم بگەڕێمەوە بۆ بەلەمەکان لەگەڵ ئەو پیاوانە؟","ئایا هەر کە من ببینن دەموکوژن؟","بیرم کردەوە ئەمە کارەساتە.","هیچ شتێکم بۆ نەماوەتەوە جگە لە مردن بە دەستی یەکێک لە یاخیبووەکان، یان مردن بە برسیەتی.","بەڵام کاتێک بە ناو دارستانەکەدا ڕام، ترسێکی نوێ وای لێکردم لەناکاو بوەستم، و بێ‌جووڵە ڕاوەستم، دڵم بە خێرایی لێدەدا.","شتێک بە خێرایییەکی زۆر لە پشت دارێکەوە بازیدا.","لەوانە بوو ورچێک بێت، یان پیاوێک، یان بوزینەیەک؛ نەمزانی.","زۆر ترسام و نەمتوانی بجوڵێم.","پاشان دووبارە بینیم، بەسەر دوو قاچەکەیدا ڕادەکات.","تاریک و سەیر بوو و کەمێک خۆی چەماندبووەوە، بەڵام زانیم پیاوە.","تفەنگچەیەکم لەگەڵ بوو، و ئەوە ئێستا کەمێک بوێرترم کرد.","دەستم کرد بە ڕۆیشتن بەرەو ئەو شوێنەی پیاوەکەی تێدا بوو.","لە پشت دارێک شاردبوویەوە، بەڵام هەر کە نزیکتر بوومەوە هاتە دەرەوە بۆ پێشوازیم.","«تۆ کێیت؟» پرسیارم کرد.","«بێن گەن،» وەڵامی دایەوە، «من بێن گەنە هەژارەکەم.","سێ ساڵە لەگەڵ هیچ کەسێک قسەم نەکردووە.»","«سێ ساڵ!» هاوارم کرد.","ئێستا دەتوانیم ببینم پیاوێکی سپی‌پێستە، بەڵام پێستی بە خۆر سووتابوو.","پارچەپارچە جل‌وبەرگی کۆنی دەریاوانی لەبەر بوو، و ئەو پارچانە بە دار، دوگمەی جۆراوجۆر و پارچەی بەستەر پێکەوە گیرابوون.","کەمەرێکی کۆنی لە کەمەری بوو، و تەنها ئەو شتە بوو کە لەسەری شتێکی ئاسایی دەچوو.","«سێ ساڵ پێش ئێستا لەم دوورگەیە جێهێڵراوم،» گوتی.","ئەم وشەیەم بیستبوو و دەمتوانی بزانم مانای ئەوەیە هاوڕێکانی کەشتی لە دوورگەیەکی دوور تەنها جێتبهێڵن و تەنها تفەنگێکت هەبێت بۆ ئەوەی بە زیندوویی بمێنیتەوە.","«لەو کاتەوە بە بزن و تووت و ماسی ژیاوم،» بەردەوام بوو.","«پارچەیەک پەنیرت لەگەڵ خۆتە؟","خەونم بە پەنیرەوە بینیوە.»","«ئەگەر دووبارە بگەڕێمەوە سەر کەشتی،» گوتم، «پەنیرێکی زۆرت دەبێت.»","«سەر کەشتی؟» دووبارەی کردەوە.","«ناوت چییە؟» پرسی.","«جیم،» پێم گوت.","«باشە، جیم.","لەسەر ئەم دوورگەیە تەنیایە بیرم لێکردووەتەوە، و بوومەتە پیاوێکی گۆڕاو.","چیتر نابینیت ڕۆم بخۆمەوە… یان باشە، تەنها کەمێک بۆ بەخت، بەڵێ.»","«و دەبێت پیاوێکی باش بم.","و،» بە وریایی سەیری دەوروبەری کرد، «دەوڵەمەندم.","دەوڵەمەند!","و شتێکت پێ دەڵێم… بەشێکی لێ دەدەمێ، چونکە تۆ یەکەم پیاویت کە منت دۆزیوەتەوە!»","بەڵام لەگەڵ ئەوەدا، لەناکاو ترسا و دەستم بە توندی گرت.","«ئەوە کەشتیی فلینتە کە تۆ لێوە هاتوویت، وایە؟» پرسی.","ئەمە هیوای پێدام.","لەوانەیە کەسێکم دۆزیبێتەوە کە یارمەتیم بدات.","«نا، ئەوە کەشتیی فلینت نییە.","فلینت مردووە،» وەڵامم دایەوە.","«بەڵام هەندێک لە دەریاوانەکانی فلینت لەسەر کەشتییەکەن، کە بۆ هەموومان هەواڵێکی خراپە.»","«نەک پیاوێک… کە یەک قاچی هەبێت؟» گوتی.","«سیڵڤەر؟» پرسیارم کرد.","«بەڵێ، ناوی ئەوە بوو.","ئەگەر ئەو تۆی ناردبێت، ئەوا من پیاوێکی مردووم،» بە دەنگێکی نزم گوتی.","لە یەک ساتدا بڕیارم دا چی بکەم.","هەموو چیرۆکی گەشتەکەمان و ئەو کێشەیەی ئێستا تێیدا بووین بۆی گێڕامەوە.","بە وریایی گوێی لێگرت، پاشان گوتی: «کوڕێکی باشیت.","مەترسە، بێن گەن یارمەتیت دەدات.","ئێستا، پێت وایە سکوایەرەکەت پارەی باشم پێ بدات بۆ ئەوەی یارمەتی بدەم؟","و بە کەشتییەکە بیگەڕێنێتەوە بۆ ماڵەوە؟»","«سکوایەر جەنتڵمەنە، و هەرچی بێت، ئەگەر ئەوانی ترمان نەبێت، پێویستمان بە تۆ دەبێت بۆ یارمەتیدانی لێخوڕینی کەشتییەکە بۆ ماڵەوە،» گوتم.","«باشە،» بەردەوام بوو، «هەندێک لە چیرۆکی خۆمم بۆت دەگێڕمەوە.","لە کەشتیی فلینت بووم کاتێک چوو بۆ ئەوەی گەنجینەکە بشارێتەوە.","شەش دەریاوانی بەهێزی لەگەڵ خۆی برد، بەڵام بە تەنیا گەڕایەوە ــ هەموویانی کوشتبوو.","بیلی بۆنز یاریدەدەری کەشتی بوو، و لۆنگ جۆن چاودێری پێداویستییەکانی دەکرد.","باشە، سێ ساڵ پێش ئێستا لە کەشتییەکی جیاواز بووم کاتێک دووبارە ئەم دوورگەیەم بینی.","«کوڕان،» گوتم، «با لێرە بوەستین و گەنجینەی فلینت بدۆزینەوە.»","کاپتن دڵخۆش نەبوو، بەڵام بۆ دوازدە ڕۆژ بەدوایدا گەڕاین و هیچمان نەدۆزییەوە.","هەموو ڕۆژێک توڕەتر دەبوون، پاشان گوتیان: «ئەمە تفەنگێکە، ئەمەش کەلەبچە و بێڵێکە.","خۆت بدۆزەوە!»","پاشان هەموویان سەر کەشتی چوون و منیان لێرە جێهێشت.","بەڵام لەم سێ ساڵەدا زۆر سەرقاڵ بووم، دەبینیت؟»","و بزانە چی؟","چاوی لێکدا و پێی ڕۆیشتم.","«بەڵام چۆن دەگەڕێینەوە سەر کەشتی؟» پرسیارم کرد.","«ئا،» گوتی، «بەلەمێکی بچووکم دروست کردووە.","لەژێر بەردە سپییەکە هەڵیمگرتووە.»","لەو ساتەدا دەنگی لێدانێکی لەناکاو و بەرزی تۆپێکی چەک هات.","«دەستیان بە شەڕ کردووە!» هاوارم کرد.","کاتێک جیم لە کەناراوە بوو (ئێستا دوکتۆر چیرۆکەکە دەگێڕێتەوە)، نزیکەی نیوەی دووی دوا نیوەڕۆ بوو کە دوو بەلەمەکە لە هیسپانیۆلاوە چوونە کەناراوە و کاپتن، سکوایەر و من لە کابینەکە قسەمان دەکرد.","هانتەر، کە یەکێک بوو لە پیاوە ڕاستگۆکان، هاتە خوارەوە و پێی گوتین جیم هاوکینز چووەتە ناو یەکێک لە بەلەمەکان و لەگەڵ پیاوەکانی تر چووەتە کەناراوە.","متمانەمان پێی هەبوو، بەڵام نیگەران بووین لە سەلامەتییەکەی.","دوای ماوەیەک هانتەر و من بڕیارمان دا بەلەمێکی تری بەرکێشان وەربگرین و بچینە کەناراوە بۆ گەڕان و پشکنین.","دوو بەلەمەکەی یەکەم زۆر بەرەو ڕاست چووبوون، بەڵام هانتەر و من ڕاستەوخۆ هاتین، بەرەو ئەو قەڵایەی دارینەی کە لەسەر نەخشەی گەنجینە بینیمان.","لە هەر یەکێک لە بەلەمەکانی کەناراوە پیاوێک چاوەڕوان بوو.","ئەوان ئێمەیان بینی، بەڵام هیچ شتێکیان نەکرد.","کاتێک گەیشتینە کەناراوە، من بە دوو تفەنگچەی پڕ لە چەک هەڵپەڕیمە دەرەوە و ڕام بۆ ناو دارەکان.","کەمتر لە سەد یاردێکم ڕۆیشتبوو کە گەیشتمە شوێنێکی کراوە و قەڵای دارینم بینی.","گردێکی بچووک هەبوو کە سەرچاوەیەکی ئاوی شیرینی لێوە دەهات.","لە نزیک ئەو سەرچاوەیە خانوویەکی بەهێزی دارین دروست کرابوو کە بۆ نزیکەی بیست کەس بەس بوو.","لە هەر دیوارێکدا چەند کونێک هەبوو بۆ ئەوەی لە ناوەوە بتوانرێت بە تفەنگ تەقە بکرێت.","لە هەموو دەوروبەریدا بۆشاییەکی فراوان پاک کرابوو و دواتر قەڵاکە بە پەرژینیەکی بەرز تەواو کرابوو.","بەهۆی ئاوی شیرین و دیوارە بەهێزەکانی، قەڵاکە باشترین شوێن دەبوو بۆ مانەوەمان.","لەناکاو، لە بەشی دیکەی دوورگەکەوە هاواری ترسناکی پیاوێکی لەسەر مردن هات.","لە یەک ساتدا بڕیارم دا، بەڕووی کەناراوەکەدا ڕاکردم و خۆم هەڵدایە ناو بەلەمەکە.","زوو گەڕاینەوە سەر هیسپانیۆلا، لەوێ هەمووان ترساو و نیگەران بوون.","بیری خۆم بۆ کاپتن باس کرد و پلانیەکمان دانا.","سێ یان چوار تفەنگی پڕمان بە پیرە ڕێدڕوث دا و لە کەشتییەکە بەجێمان هێشت بۆ چاودێریکردنی ئەو شەش دەریاوانەی متمانەمان پێیان نەبوو.","پاشان دەستمان کرد بە پڕکردنی بەلەمەکە بە پێداویستییەکان: باروت، تفەنگ، کیسەی بیسکیت، بەرمیلە بچووکەکانی گۆشت و برەندی، و بەدڵنیاییەوە سندووقی دەرمانەکەم.","کاتێک بەڕووی کەناراوەکەدا دەڕۆیشتین، یەکێک لە دەریاوانەکان کە زۆر لە پێشمان لەسەر کەناراوەکە بوو ئێمەی بینی و ڕایکردە ناو دارستانەکە.","پێداویستییەکانمان دابەزاند و جۆیس، کە ئەویش پیاوێکی ڕاستگۆ بوو،مانەوە بۆ چاودێریکردنیان؛ من و هانتەر گەڕاینەوە بۆ باری دووەم.","هۆکاری ئەوەی بۆ گەشتی دووەم مەترسیمان خستە سەر خۆمان ئەوە بوو کە، هەرچەندە زۆربەی دەریاوانەکان لە دوورگەکە بوون، هیچ کامیان تفەنگێکیان نەبوو.","کاتێک دوای گەشتی دووەم بارەکەمان دابەزاند، هانتەر و جۆیس لە کەناراوەکە مانەوە و من بە خێرایی ڕۆیشتمەوە بۆ هیسپانیۆلا.","پاشان سکوایەر، کاپتن سمۆڵێت، ڕێدڕوث، من و دەریاوانێکی دیکە ــ ئەبراهام گرەی ــ سوارەی بەلەمەکە بووین.","ئەم گەشتی پێنجەمە مەترسیدار بوو.","پیاوەکان زۆر بوون، هەروەها بارێکی دیکە لە پێداویستییەکانیشمان لەگەڵ بوو.","دەریاکە خراپتر ببوو و چەند جارێک ئاو هاتە سەر لاپەڕەی بەلەمەکە.","لەناکاو کاپتن گوتی: «پشت سەرتان بڕوانن!","تۆپەکە!»","ئەو پێنج پیاوەی لە کەشتییەکە مابوون ئامادە دەبوون تۆپەکە تەقێنن؛ ئێمە بە تەواوی ئەم تۆپە گەورە و بەهێزەمان لەبیر کردبوو.","گرەی بە دەنگێکی پڕ لە ترس گوتی: «ئیسرائیل دەریاوانی تۆپی فلینت بوو.»","ترەلۆنی، کە لە هەموومان باشتر لە تەقاندنی تفەنگ بوو، تفەنگەکەی پڕ کرد.","ڕۆیشتنمان وەستاند، دواتر ئەو نیشانەی گرت و تەقاندی.","لە هەمان ساتدا ئیسرائیل هاندز، کە خەریکی پڕکردنی تۆپەکە بوو، خۆی خوار کرد.","گوللەکە لە تەنیشتی تێپەڕی و لە یەکێکی دیکە لە پیاوەکانی سەر تەختەی کەشتی کەوت.","پاشان گوێمان لە هاوار بوو، هەم لە کەشتییەکە و هەم لە کەناراوەکە، کە ئێستا دەمانبینی دزەکانی دیکە لە دارستانەکە دێنە دەرەوە.","زۆر نەخایاند تا گوللەیەکی تۆپەکە ڕاست لە تەنیشت بەلەمەکەمان کەوت و بەلەمەکە دەستی کرد بە نقوومبوون.","بەخۆشییەوە، لە کەناراوەکە زۆر دوور نەبووین.","کاتێک بە ناو شەپۆلەکاندا ڕۆیشتین و هاتینە سەر کەناراوەکە، بەلەمە خراپەکەمان و نزیکەی نیوەی باروت و پێداویستییەکانمان لە پشتەوە لەژێر ئاو مابوون.","بۆ خراپترکردنی بارودۆخ، ئێستا گوێمان لە هاوارێک دەبوو کە لە دارستانە نزیکەکەوە دێت.","بە خێرایی هەموو توانامان ڕاکردین بەرەو قەڵاکە، و لە هەر هەنگاوێکدا دەنگی دزەکانمان بە بەرزی زیاتر دەبیست.","هەر کە گەیشتینە قەڵاکە، حەوت پیاو لە دارستانەکەوە دەرکەوتن.","سکوایەر و من تەقەمان کرد، هانتەر و جۆیس لە ناو خانووی دارینەکەش تەقەیان کرد.","یەکێک لە یاخیبووان کەوتە سەر زەوی و ئەوانی دیکە وەرگەڕان و ڕایانکردە ناو دارستانەکە.","چوین بۆ سەیرکردنی ئەو پیاوەی کە کەوتبوو، لە هەمان ساتدا گوللەیەک لە دارستانەکەوە هات و تۆم ڕێدڕوثی بەدبەختی لێدا.","لە ئازاردا هاواری کرد و بە خوێناوی هەڵمانگرت و بردمانە ناو خانووی دارینەکە.","سکوایەر لە تەنیشتی کەوتە سەر زەوی و دەستی ماچ کرد، وەک منداڵێک دەگریا.","ڕێدڕوث پیاوێکی باش بوو و هەمیشە بە بێدەنگی و باشی شوێنی فەرمانەکانی دەکەوت.","زۆری نەخایاند کە چاوی داخست و مرد.","کاپتن، کە گیرفانەکانی پڕ بوون لە شتەکانی کە لە کەشتییەکە هێنابوونی، ئاڵایەکی دەرهێنا و بە وریاییەوە دایخستە سەر جەستەی تۆم.","پاشان ئاڵایەکی دیکەی لەسەر لقێکی بەرزی دارێک دانا.","دوای ئەوە هاتە لام و بە دەنگێکی ئارام قسەی کرد.","«دکتۆر لایڤزی»، گوتی، «چەند هەفتە ماوە تا بلاندلی کەشتییەک بنێرێت بۆ گەڕان بەدوای ئێمە؟» پێم گوت کە مانگە، نەک هەفتە.","«باشە گەورەم، ئەوا زۆر خراپە کە باری دووەمی پێداویستییەکانمان لەدەست دا.","پێداویستییەکانی خواردن زۆر کەمە»، وەڵامی دایەوە.","لە هەمان ساتدا، بە دەنگێکی زۆر بەرز، گوللەی تۆپێک کەوتە ناو قەڵاکە.","«لەوانەیە لە کەشتییەکەوە ئاڵاکە ببینن»، کاپتن گوتی.","لە ناو قەڵاکەدا تا ڕادەیەک سەلامەت بووین، بەڵام گوللەکان تا درەنگانی ئێوارە بەردەوام دەکەوتن.","کاپتن دوای چەند کاتژمێرێک گوتی: «لەوانەیە دارستانی نێوان ئێمە و کەناراوەکە سەلامەت بێت، و ئێستا کاتی جزرە.","پێداویستییەکانمان نابێت ئێستا لەژێر ئاو بن.","هەندێک خۆبەخش پێویستمە بچن و بیانهێننەوە.»","گرەی و هانتەر بە بێدەنگی چوونە خوارەوە بەرەو کەناراوەکە، بەڵام درەنگ بوو.","چوار یان پێنج لە یاخیبووان پێشتر لەوێ بوون و پێداویستییەکانمانیان دەخستە ناو یەکێک لە بەلەمە بچووکەکانیان.","سیلڤەر لە بەلەمەکە بوو و هەموو پیاوەکان ئێستا تفەنگیان هەبوو، کە دەبوو بە نهێنی لە کەشتییەکە هەڵگیرابێت.","ئێستا تەنها شەش کەس لە ئێمە مابووین و پێداویستیی خواردنمان تەنها بۆ نزیکەی دە ڕۆژ بەس بوو.","ڕێدڕوث مردبوو و نەماندەزانی بە جیم هاوکینز چی هاتووە.","لەناکاو، دەنگێک لە دەرەوە هات.","«دکتۆر!","سکوایەر!","کاپتن!» دەنگێک هاواری کرد.","منیش ڕۆیشتم بۆ دەرگاکە و جیم هاوکینزم بینی بە سەلامەتی بەسەر پەرژینی قەڵاکەدا دێتە خوارەوە.","من بەوانی دیکەوە دەچمەوە (جیم هاوکینز بەردەوامی چیرۆکەکە دەگێڕێتەوە) هەر کە بن گەن ئاڵاکەی سەر قەڵاکەی بینی، وەستان.","«ئێستا»، گوتی، «کاتێک هاوڕێکانت دەبینیت، بە سکوایەر یان دکتۆر بڵێ بێت بۆ بینینم.","دەزانیت لە کوێ دەمەدۆزیتەوە ــ لە سەرەوەی دارستانەکە، لەو شوێنەی ئەمڕۆ منت بینی.","پێیان بڵێ هۆکارێکی باش هەیە بۆ ئەوەی خۆم دەشارمەوە.»","«باشە»، گوتم.","«دەتوانم ئێستا بچم؟»","تۆپەکە لەناکاو دەستی کردەوە بە تەقین و ئێمە بە ئاراستەی جیاوازدا ڕامانکردە ناو دارستانەکە.","بە هێواشی بەری دامەزیم بەرەو دەریا، و زوو هیسپانیۆلام بینی، هەروەها جۆلی ڕۆجەر ــ ئاڵای ڕەشی دزەکان ــ کە لەسەر دزەکەی کەشتییەکە هەڵواسرا بوو.","کاتێک بەرەو قەڵاکە دادەبەزیم، بەردێکی گەورەی سپیم بینی کەمێک دوورتر لەسەر کەناراوەکە.","وام زانی ئەوە دەبێت ئەو بەردە بێت کە بن گەن باسی کردبوو، و ڕۆژێک ئەگەر پێویستم بە بەلەم بوو، دەزانم لە کوێ بگەڕێم.","لە قەڵاکە بە گەرمی پێشوازییان لێکردم و بە دڵخۆشی چیرۆکەکەم بۆیان گێڕایەوە.","دواتر لەو ئێوارەیە تۆم ڕێدڕوثی پیرمان لەناو خۆڵدا ناشتی و بۆ ماوەیەک بە بێدەنگی لە دەوری وەستان.","پاشان هەندێک گۆشتمان خوارد و برەندیمان خواردەوە.","سکوایەر و دکتۆر و کاپتن گفتوگۆیان کرد لەسەر ئەوەی چی بکەین.","خواردنمان زۆر کەم بوو، بەڵام بڕیار درا بە باشترین شێوەی کە بتوانین لەگەڵ دزەکان شەڕ بکەین.","ئێستا ژمارەیان پازدە کەس بوو و دوو کەسیان لێدرابوون و بریندار بوون.","لە لایەکی دیکەوە ئەو ڕۆمەش یارمەتیدەری ئێمە بوو کە دزەکان دەیانخواردەوە؛ هەرچەندە دزەکان نیو میل لە ئێمە دوور بوون، بە درێژایی شەو دەنگی گۆرانی و هاواریان بە باشی دەبیستین.","من زۆر ماندوو بووم و کاتێک لە کۆتاییدا خەوم لێکەوت، وەک دارێک بە قووڵی خەوتم.","بەیانیی ڕۆژی دواتر بە دەنگی قسەکان لە خەو هەستام.","«ئاڵایەکی سپییە!»","گوێم لە کەسێک بوو کە گوتی: «سیلڤەرە!»","پیاوێک لەگەڵ سیلڤەر بوو کە هاواری کرد: «کاپتن سیلڤەر، گەورەم، دەیەوێت قسە بکات و ئاشتی بکات.»","«من نایناسم.","ئەو کێیە؟» کاپتن هاواری کرد و بە خۆی گوت: «کەواتە ئێستا بووە “کاپتن”، وایە؟»","ئێستا لۆنگ جۆن وەڵامی دایەوە: «منم.","ئەم پیاوە بەدبەختانە منیان هەڵبژاردووە ببمە کاپتن، دوای ئەوەی تۆ کەشتییەکەت بەجێهێشت.","دەمانەوێت قسەت لەگەڵ بکەین و لەسەر شتێک ڕێک بکەوین.»","پاشان سیلڤەر هاتە نزیک پەرژینەکە، دارەکەی فڕێدا و بە هەوڵێکی زۆر توانی بەسەریدا بڕواتەوە.","کاتێک لە کۆتاییدا گەیشتە نزیک خانووی دارین، بە قورسایی خۆی دانیشتە سەر خۆڵەکە.","«باشە کاپتن»، گوتی، «ئێمە ئەو گەنجینەیەمان دەوێت.","نەخشەکەت هەیە، وایە؟","ئێمەش دەمانەوێت.","ئەگەر نەخشەکەمان بدەیت و دەست لە تەقەکردن لە دەریاوانە بەدبەختەکان هەڵبگریت، هەڵبژاردنێکت بۆ دادەنێین.","یارمەتیمان بدە گەنجینەکە بدۆزینەوە، دواتر لەگەڵمان لە کەشتییەکەدا دێیت و بەڵێنت پێدەدەم لە شوێنێکی سەلامەت لە کەناراوە داتبهێڵمەوە.","یان دەتوانیت لێرە بمێنیت.","نیوەی پێداویستییەکانت پێدەدەین و بەڵێنت پێدەدەم یەکەم کەشتییەک ببینین، پێی بڵێین بێت و تۆ ڕزگار بکات.»","«ئێستا گوێم لێ بگرە»، کاپتن سمۆڵێت گوتی.","«ئەگەر یەک بە یەک و بێ تفەنگ بێنە ئێرە، هەمووتان دەخەمە کۆت و بۆ دادگاییەکی دادپەروەرانە دەبتانەوە بۆ ئینگلتەرا.","ئەگەر نا، بە هەر حاڵێک شکستخواردوون.","ناتوانن گەنجینەکە بدۆزنەوە، ناتوانن کەشتییەکە بخەنە ڕێ، و تەنانەت ناتوانن لەگەڵ ئێمە شەڕ بکەن.","ئێستا بڕۆن.»","لۆنگ جۆن سیلڤەر لە تووڕەییدا سوور ببووەوە.","بە زەحمەت خۆی بەسەر زەوییەکەدا ڕاکێشا تا گەیشتە شوێنی دارەکەی.","پاشان هەستا و تفی کردە ناو سەرچاوەکە.","«ئەوەتا!» هاواری کرد، «ئەمە ئەوەیە من لە تۆ بیردەکەمەوە!","من ئەم قەڵایە کۆنە وێران دەکەم، و ئەوانەی دەمرن خۆشبەختترین کەسن!»","و بە هاواری سوێندخواردن، دوور کەوتەوە، بە هێواشی خۆی بەسەر پەرژینەکەدا ڕاکێشا و ون بوو.","کاپتن زوو دڵنیابوو کە هەموومان تفەنگمان هەیە و شوێنی وەستانمان بۆ دیاری کرد.","ئەوان لە ئێمە زۆرتر بوون، بەڵام لانیکەم قەڵاکەمان هەبوو.","دوای یەک کاتژمێر چاوەڕوانی، گرووپێک لە یاخیبووان لەناکاو لە دارستانی لای باکوور دەرکەوتن و بەڕووی پەرژینەکەدا ڕایانکرد.","لە هەمان کاتدا، لە دارستانی لایەکەی دیکەوە دەنگی تەقە هات.","سکوایەر و گرەی لەناو خانووی دارینەکەوە جار لە دوای جار تەقەیان کرد و سێ پیاویان لێدا کە خەریکی بەسەر پەرژینەکەدا هەڵدەگەڕان؛ دوو کەسیان کوژران و سێیەمەکە ڕایکرد.","بەڵام چوار کەسی دیکە هاتبونە ناو پەرژینەکە و ئێستا بە تفەنگ و شمشێر هێرشیان کردبووە سەرمان.","یەکێک لە دزەکان دەستی خستە سەر تفەنگی هانتەر، لە کونەکەی دیواری قەڵاکە دەرهێنای و بەهێزی لەسەر سەری هانتەری دا.","کەوتە سەر زەوی و نەجوڵایەوە.","شمشێرمان هەڵگرت و لە خانووەکە هاتینە دەرەوە بۆ شەڕکردن.","بینیم دکتۆر پیاوێکی لەسەر ڕووخساری برید، و ئەبراهام گرەی پیاوێکی دیکەی بڕی کە هاتبوو هێرشم بکات.","دوای چەند خولەکێک شەڕی ترسناک، هەموو شتێک کۆتایی هات.","ئێمە بردمانەوە.","شەش کەس لەوانە مردبوون یان خەریکی مردن بوون و ئەوانی دیکە ڕایانکردبوو.","بەڵام کاتێک گەڕاینەوە بۆ خانووی دارین، بینیمان هانتەر لەسەر زەوی کەوتووە.","جۆیس بە تەقە کوژرابوو و سکوایەر کاپتنەکەی بەدەستەوە گرتبوو کە زۆر بریندار بوو.","یاخیبووان ئەو ڕۆژە نەگەڕانەوە.","بەڵام هانتەر هەرگیز چاوی نەکردەوە و لە شەوی دواتردا مرد.","کاپتن لە شان و قاچی لێدرابوو.","بەڵام دکتۆر ڕایگەیاند کە بەدڵنیاییەوە چاک دەبێتەوە، بە مەرجێک کاتی پێویستی بۆ پشوودان بدرێت.","ئەمە تەنها چوار پیاوی تەندروستی بۆ هێشتینەوە: دکتۆر، سکوایەر، گرەی و من.","دوای نانی نیوەڕۆ، دکتۆر دوو تفەنگ، تفەنگێکی درێژ، شمشێرێک و نەخشەی گەنجینەکەی هەڵگرت و بە خێرایی چووە ناو دارستانی لای باکوور.","وام زانی بە گومانەوە دەچێت بۆ بینینی بن گەن.","دەستم کرد بە شۆردنەوەی خانووی دارینەکە.","گەرم بوو و پڕ بوو لە خوێن و لاشەی مردوو.","ڕقم لێی بوو و دەمتوانی هەموو شتێک بەجێبهێڵم.","دوای بیرکردنەوەیەکی کەم، لە کاتێکدا سکوایەر و گرەی سەیریان نەدەکرد، گیرفانەکانم پڕ لە بیسکیت کرد، دوو تفەنگم هەڵگرت و دەستبەجێ خانووی دارینەکەم بەجێهێشت.","ئەمە دووەم کارە بێ‌پەرواکانەی من بوو، و ئەمجارە تەنها دوو پیاوم بەجێهێشت بۆ پاراستنی قەڵاکە.","بەڵام وەک یەکەم کردارەکە، ئەمەش یارمەتیدەر دەبوو بۆ ڕزگارکردنمان.","بڕیارم دابوو بچمە خوارەوە بۆ بەردە سپییەکە و بەلەمەکەی بن گەن بدۆزمەوە.","ئێستا دەستی کردبوو بە تاریکبوون، و کاتێک لە نێوان دارەکاندا دەڕۆیشتم بەلەمێکم بینی کە سیلڤەر و چەند پیاوێکی دیکەی تێدا بوون و لە هیسپانیۆلاوە بەرەو کەناراوەکە دەڕۆیشتن.","بەردەوام بووم بۆ دۆزینەوەی بەردە سپییەکە تا ڕووناکی ڕۆژ کەمبووەوە، و کاتێک لە کۆتاییدا بەلەمە بچووکەکەم دۆزییەوە نزیکەی بە تەواوی تاریک بوو.","بەلەمەکە زۆر بچووک بوو، تەنانەت بۆ منیش، و لە چوارچێوەی دارە نەپەختە خۆڵەمێشییەکان دروست کرابوو کە بە پێستی بز پۆشراو بوون.","پارۆیەکیشی تێدا بوو.","ئێستا کە بەلەمەکەم دۆزیبووەوە، بیرۆکەیەکی دیکەم هاتە مێشکم.","دەتوانیم بە نهێنی لە تاریکییەکەدا بە بەلەمەکە بچمە سەر هیسپانیۆلا و کەشتییەکە لە لەنگەرەکەی دەربهێنم، بۆ ئەوەی ڕێگری لە دزەکان بکەم لەوەی بچنە سەر دەریا.","تا ئێستا هەموو شوێنەکە زۆر تاریک بوو.","ئاگری کەمپەکەی دزەکانم لە کەناراوەکە دوورتر دەبینی و تەنها ڕووناکییەک لە ناو ئاوەکە بوو کە شوێنی هیسپانیۆلام بۆ دیاری دەکرد.","بەلەمە بچووکەکەم بردە کەنار ئاو و بە زەحمەت خۆم کردمە ناوی.","جزرەکە گۆڕابوو و ئاوەکە دەچووە دەرەوە.","بەلەمە بچووکەکە بە ئاستەم بەرەو ئاراستەی دروست دەجوڵا، بەڵام سەرەڕای ئەوە، لە کۆتاییدا توانییم نزیک کەشتییەکە ببمەوە.","کاتێک حەبلی لەنگەرەکەم دۆزییەوە، چەقۆکەم دەرهێنا و دەستم کرد بە بڕینی.","کاتێک خەریک بووم حەبلەکە دەبڕم، گوێم لە دوو پیاو بوو کە لەسەر کەشتییەکە لە سەرەوە مشتومڕ و شەڕیان دەکرد.","ڕوون بوو کە زۆر ڕۆمیان خواردبووەوە، و یەکێک لە دەنگەکانم دەناسی؛ ئەوە دەنگی ئیسرائیل هاندز بوو.","کاتێک لە کۆتاییدا حەبلەکەم بڕی، کەشتییەکە لەناکاو دەستی کرد بە سوڕانەوە و لەگەڵ ئاراستەی شەپۆلەکە بە ڕێڕەوی تەنگی ئاوەکەدا جووڵا.","بە خێرایی دەجوڵا و بەلەمەکەشم لەگەڵیدا دەجوڵا.","لە خاڵێکدا بینیم نزیک شەپۆلەکان و ئەو کەنارەی بووم کە شەپۆلەکان لێی دەشکاندن.","ئاگرەکەی مەڵبەندەکە ئێستا نزیکتر بوو، چەتەکان هەموویان لە دەوروبەری بوون، و گوێم لە وشەکانی گۆرانییەک بوو کە زۆرجارم بیستبوو لەسەر کەشتی دەیانووتەوە: «بەڵام یەک پیاو لەناو تاقمەکەی زیندووە، کە لەگەڵ حەفتاو پێنج کەس چووبووە ناو دەریا.»","لە بنەڕەتی ئەو بەلەمە زۆر بچووکەکەدا پاڵکەوتم و پێموابوو فڕێدەدرێمە ناو دەریا بۆ مردن.","دەبوو چەند کاتژمێرێک بەو شێوەیە بمامایەوە، لەسەر شەپۆلەکان هەڵدەدرام و هەر ساتێک چاوەڕێی مردن بووم، بەڵام زۆر ماندوو بووم.","بە هێواشی خەوم لێکەوت و خەونم بە ماڵەوە و ئەدمیراڵ بێنبۆوە بینی.","کاتێک بەخەبەر هاتمەوە، خۆر هەڵابوو و خۆمم بینی نزیکەی چارەک میلێک لە کۆتایی باشووری ڕۆژئاوای دوورگەی گەنجینە دوور بووم.","بەڵام کەناراوەکە زۆر بەرداوی بوو و دەریاکەش شەپۆلاوی بوو، بۆیە نەمتوانی مەترسی بکەم و هەوڵ بدەم بچمە کەناراوە.","هەوڵم دا سەوڵ لێبدەم، بەڵام بەلەمەکە بە ئاستەم لێخوڕرا و ئاو دەستی کرد بە هاتنە ناوەوە.","هەستم بە ترسێکی زۆر خراپ کرد.","چۆن دەتوانیم هیوا بکەم بگەمە وشکانی؟","کەمێک دواتر، کاتێک بە دەوری کەناراوەکەدا دەجووڵام، لەناکاو هیسپانیۆلام لەبەردەم خۆم بینی، کەمتر لە نیو میل دوور بوو.","چارۆکەکانی بە ئازادی لە بادا دەجووڵان، و بۆم ڕوون بوو کە هیچ کەسێک لێی ناخوڕێت.","پێموابوو ئەو دوو پیاوە دەبێت بەهۆی ڕۆمەکەوە خەوتبن.","ئەگەر تەنها بتوانم سوار کەشتییەکە ببم، لەوانەیە بتوانم بیگەڕێنمەوە بۆ کاپتنەکەی.","دەمزانی پێویستە چی بکەم.","دانیشتم و دووبارە دەستم کرد بە سەوڵ لێدان.","سەرەڕای هاتنە ناوەوەی ئاو بۆ بەلەمەکە، بەردەوام بووم لە سەوڵ لێدان تا لە کۆتاییدا نزیک کەشتییەکە بوومەوە.","بینیم یەکێک لە ستوونەکانی کەشتی لە لای کەشتییەکەوە هەڵواسراوە، و کاتێک شەپۆلێکی گەورە هات، خۆمم بەرز کردەوە و دەستم بۆ گرتنی درێژ کرد.","کاتێک خۆم فڕێدایە سەر تەختەی کەشتییەکە، کەشتییەکە ڕووی لە باد کرد، سوڕایەوە و نزیک بوو دووبارە فڕێم بداتەوە ناو دەریا.","توانیم ڕاوەستم و پاشان پیاوێکم بینی کەمێک دوورتر لەسەر تەختەی کەشتی کەوتووە و مردووە.","لە نزیکی ئەودا ئیسرائیل هاندز دانیشتبوو و پاڵی بە لای کەشتییەکەوە دابوو.","چاوەکانی داخراو بوون و ڕووخساری سپی بوو.","خوێنم لەسەر تەختەکە بینی و برینێکی گەورەش لە قاچەکەی بوو.","پێموابوو ئەو دوو پیاوە دەبێت یەکتریان کوشتبێت.","لەو ساتەدا ئیسرائیل کەمێک جووڵا و داوای کرد هەندێک براندی بۆ بهێنم.","بەخێرایی چوومە خوارەوە بۆ کابینەکە.","کابینەکە زۆر خراپ دەردەکەوت و بە بوتڵی بەتاڵ داپۆشرابوو، بەڵام توانییم کەمێک براندی، هەروەها هەندێک بسکیت و پەنیر و مێوژ بۆ خۆم بدۆزمەوە.","دوای خواردنەوەی براندی، ئیسرائیل بەهێزتر بوو و پرسیاری کرد لە کوێوە هاتووم.","«هاتووم بۆ ئەوەی کەشتییەکە ببەم،» وەڵامم دایەوە.","«و تکایە وەک کاپتنی خۆت لێم بڕوانە.»","سەیری کردم، بەڵام هیچ نەگوت.","پاشان ئاڵای ڕەشی چەتەکانم دابەزاند و فڕێم دایە ناو دەریا.","متمانەم بە ئیسرائیل هاندز نەبوو، بەڵام لە خاڵێکدا متمانەم پێی هەبوو؛ هەردووکمان دەمانویست کەشتییەکە لە شوێنێکی سەلامەت لە کەناراوە بگەیەنین، شوێنێک کە بتوانرێت بە ئاسانی بگەڕێنرێتەوە ناو دەریا.","هاندز پێشنیاری کرد ڕێگای ئەنجامدانی ئەو کارە فێرم بکات.","بۆیە، لەگەڵ ڕێنمایی هەنگاو بە هەنگاوی هاندز، کەشتییەکەمان بە هێواشی بردە ناو ئینلێتی باکوور.","پاشان هاواری کرد: «ئێستا کوڕەکەم!» و منیش بە خێرایی کەشتییەکەم سوڕاند و دەستی کرد بە جووڵان بەرەو کەناراوە.","کاتێک چاوەڕێ بووین کەشتییەکە بگاتە کەناراوە، ئاوڕم دایەوە بۆ هاندز.","کاتێک چاوەکانمان یەکتریان بینی، هەردووکمان هاوارمان کرد.","هاواری من لە ترس بوو، چونکە ئەو ئێستا ڕاوەستابوو و چەقۆیەکی لە دەست بوو.","هاواری ئەو هاواری هێرش بوو.","بەرەو من هات، بەڵام من ڕام کرد بۆ لایەک و لە کاتی جووڵاندا یەکێک لە تفەنگچەکانم لە پشتێنەکەم دەرهێنا.","لەو ساتەدا کەشتییەکە بە کەناراوە کەوت و بە جووڵەیەکی زەبەلاح و لەناکاو بەسەر یەک لایدا کەوت.","هەردووکمان کەوتینە سەر تەختەی کەشتی، بەڵام من دووبارە هەستامەوە و دەستم کرد بە هەڵگەڕان بۆ نزیکترین ستوونی کەشتی.","کاتێک بەرزبوومەوە لەسەر ستوونەکە، وەستام بۆ پڕکردنەوەی هەردوو تفەنگچەکەم.","هاندز دەستی کرد بە هاتنە سەر ستوونەکە بەدوامدا، پاشان وەستا و چەقۆکەی بەرەو من فڕێدا.","سەرەڕای ئەوەی چەقۆکە بە شانم کەوت، هەردوو تفەنگچەکەم تەقاند.","هاندز هاواری کرد و کەوتە ناو ئاوەکەی خوارەوە.","«پارچەکانی هەشت.» دوای چەند ساتێک ترس، بینیم چەقۆکە زۆر ئازاری نەداوم و بە هێواشی هاتمە خوارەوە.","هاندز لەناو ئاوەکە مردبوو.","الشەکەی تریشم بە بەرزکردنەوەی بەسەر لای کەشتییەکەدا فڕێدایە ناوەوە بۆ ئەوەی لەگەڵ هاندز بێت.","پێش ئەوەی کەشتییەکە بەجێبهێڵم، هەرچەندە لە چارۆکەکان توانیم هێنامە خوارەوە.","پاشان خۆم فڕێدایە ناو ئاوەکە و بەرەو کەناراوە ڕۆیشتم.","زۆر هەڵچووبووم و نەمدەتوانی چاوەڕێ بکەم تا بگەڕێمەوە بۆ قەڵای دارین و بەوانی تر بڵێم کە کەشتییەکەم گەڕاندۆتەوە.","درەنگی شەو بوو کاتێک ڕێگاکەم بۆ قەڵای دارین دۆزییەوە.","کاتێک بەرەو دەروازەکە دەهاتم، دڵخۆش بووم لە بیستنی دەنگی خەوتنی هاوڕێکانم.","پاشان، کاتێک چوومە ژوورەوە، دەنگێکی نامۆ لەناکاو هاواری کرد: «پارچەکانی هەشت!»","«پارچەکانی هەشت!»","«پارچەکانی هەشت!»","ئەوە تووتی سیڵڤەر بوو، کاپتن فلینت!","هیچ کاتێک نەبوو بۆ بیرکردنەوە.","پیاوەکان دەستبەجێ خەبەریان هاتەوە و سیڵڤەر هاواری کرد: «کێیە لەوێ؟»","هەوڵم دا ڕابکەم، بەڵام نەمتوانی و زوو گرتیانم.","سیڵڤەر فەرمانی بە کەسێک دا بچێت و فانۆسێک بهێنێت، و من چاوەڕێی هاتنی ڕووناکی بووم.","«هاتوویت بۆ سەردانمان، جیم،» لۆنگ جۆن گوتی.","«ئەوە خۆشە.»","هیچم نەگوت، تەنها سەیری سیڵڤەرم کرد.","«ئێستا، من هەمیشە حەزم لێت بووە،» سیڵڤەر گوتی.","«دوستانەکەت دوای ئەمە نایەن بۆ وەرگرتنەوەی تۆ.»","«و ئەگەر ناتەوێت دەستەی سێیەم لە پیاوان بە تەنیا خۆت دروست بکەیت، دەبێت لەگەڵ ئێمە یەکبگریت.»","کەواتە، هاوڕێکانم زیندوو بوون.","«ئەگەر ئازادی هەڵبژاردنم هەبێت،» وەڵامم دایەوە، «پێموایە دەبێت پێم بڵێیت چی ڕوویداوە و هاوڕێکانم لە کوێن.»","«دوێنێ دکتۆر لیڤیسی بە ئاڵایەکی سپی هات بۆ قسەکردن لەگەڵم،» سیلڤەر ڕوونی کردەوە.","«پێی گوتین کە کەشتییەکە ڕۆیشتووە.»","«هیچ خواردنێکمان نەبوو، بۆیە پێشنیاری کرد ڕێکەوتنێک لەگەڵی بکەین، و ئەوەشمان کرد.»","«کەواتە ئێستا لێرەین، لەگەڵ پێداویستییەکان، براندی، خانووە-دارەکە و دارە سووتەمەنییەکان.»","«نازانم لە کوێن.»","«باشە،» گوتم، «تۆ چیتر کەشتیت نییە، گەنجینەکە لەدەست چووە، چەند پیاوێک کوژراون و هەموو شتێک بە ئاراستەیەکی خراپدا ڕۆیشتووە.»","«و ئەگەر دەتەوێت بزانیت کێ ئەمەی کردووە... من بووم!»","«ئەو شەوەی یەکەم جار دوورگەی گەنجینەکەمان بینی، من لەناو بەرمیلە سێوەکەدا بووم و هەموو ئەوەی تۆ گوتت بیستم.»","«لەنگەرەکەی کەشتییەکەم بڕی و پیاوەکانی سەر کەشتییەکەم کوشت، پاشان کەشتییەکەم لە شوێنێک شاردەوە کە تۆ هەرگیز نایدۆزیتەوە.»","«ئەگەر دەتەوێت بمکوژە، یان ڕزگارم بکە.»","«بەڵام ئەگەر ڕزگارم بکەیت، هەموو ئەمە لەبیر دەکەم و کاتێک لە دادگا بۆ دزیی دەریایی دادگایی دەکرێیت پشتگیریت دەکەم.»","بۆ ساتێک بێدەنگی هەموو شوێنەکەی گرت، چونکە هەموویان تەنها سەیری منیان دەکرد.","«ئەو بلاک دۆگی دەناسی،» یەکێک لە پیاوەکان گوتی.","سیلڤەر زیادیکرد: «هەر ئەم کوڕە بوو کە نەخشەکەی لە بیلی بۆنز وەرگرت.»","لەو ساتەدا پیاوێکی تر بە چەقۆیەکەوە هەستا و گوتی: «ئەوا من دەیکوژم.»","«بوەستە،» سیلڤەر گوتی.","«تۆ کاپتن نیت.»","«من ئەو کوڕەم خۆشدەوێت؛ ئەو لە هەمووتان باشترە، و من دەڵێم بە زیندوویی دەمێنێتەوە.»","«ئێوە من هەڵبژاردووە بۆ ئەوەی ببمە کاپتن.»","«ئەگەر منتان ناوێت، دەزانن چی بکەن.»","دوای بێدەنگییەکی کورت، پیاوەکان چوونە دەرەوە بۆ کۆبوونەوە و مشوڕەکردن.","پیاوەکان یەک بە یەک چوونە دەرەوە و سیلڤەر و منیان بە تەنیا جێهێشت، و بۆ ماوەیەک نەگەڕانەوە.","«جیم،» سیلڤەر بە هێمنی گوتی، «ئێستا خەریکە بمیریت.»","«ئێمە لە کێشەی زۆرداین، بەڵام هەموو هەوڵێک دەدەم.»","«ئەگەر بتوانم، ژیانت دەپارێزم.»","«بەڵام سەیرکە جیم، دواتر تۆش دەبێت من لە هەڵواسران ڕزگار بکەیت.»","بۆ ساتێک بیرم کردەوە و پاشان بەڵێنم دا هەرچی لە توانام بێت بۆی بکەم.","«شتێکی تریش هەیە، جیم.»","«دکتۆر نەخشەی گەنجینەکەی پێداوم.»","«پێت وایە بۆچی ئەوەی کرد؟»","دەمم لە سەرسامیدا داپچڕا، ئەوەش نیشانی سیلڤەری دا کە پێویست ناکات پرسیاری زیاتر بکات.","دەرگاکە کرایەوە و پێنج پیاوەکە گەڕانەوە ژوورەوە.","یەکێک لەوان بە دوودڵییەوە بەرەو سیلڤەر چوو و پارچە کاغەزێکی پێدا کە بە خاڵێکی ڕەش هێما کرابوو.","ترسی کاپتنم لە «خاڵە ڕەشەکە» بیرکەوتەوە؛ زۆر پێشتر، لە ئەدمیراڵ بێنبۆ.","سیلڤەر پارچە کاغەزە بچووکە تاریکەکەی هەڵگێڕایەوە و گوتی: «باشە، چی دەڵێت؟","«دەرکراو.»","«باشە، من هێشتا کاپتنی ئێوەم تا پێم دەڵێن بۆچی ناخۆشن و منیش وەڵامتان دەدەمەوە.","«دوای ئەوە دەبینین.»","«باشە، یەکەم،» یەکێک لە پیاوەکان بە ناوی جۆرج مێری وەڵامی دایەوە، «تۆ پشێویت لەم گەشتەدا دروست کردووە.»","«دووەم، تۆ هێشتت دوژمن بە هیچ شتێک لێرە بڕوات.»","«بۆچی دەیانویست بڕۆنە دەرەوە؟»","«من نازانم، بەڵام دەزانم ئەوە ئەو شتە بوو کە ئەوان دەیانویست.»","«سێیەم، تۆ ڕێگەت نەدا تەقە لەوان بکەین کاتێک دەڕۆیشتن.»","«و لە کۆتاییدا، ئەم کوڕەش هەیە.»","«من لەم گەشتەدا ئاژاوەم دروست کردووە، وایە؟» سیلڤەر بە هێمنی پرسی.","«هەمووتان دەزانن کە من نەمدەویست هێرشیان بکەین تا گەنجینەکە بدۆزرێتەوە و ئێمە بگەڕێینەوە بۆ ئینگلتەرا.»","«ئەگەر گوێتان لە من گرتبایە، هەموومان تا ئێستا لەسەر هیسپانیۆلا دەبووین.»","«هەموومان زیندوو دەبووین و خواردن و خواردنەوە و گەنجینە لەسەر کەشتییەکە دەبوو!»","«بەڵام ئێوە پیاوان ئەوەتان نەکرد کە من پێم گوتن.»","«لەبەر ئەو کارانەی ئێوە کردووتانە، لەوانەیە هەموومان لە سێدارە بدرێین!»","«ئایا ئەم کوڕە بارمتە نییە؟»","«لەوانەیە ئەو کۆتا دەرفەتمان بێت.»","«ئەو کوڕە بکوژم؟»","«من نایکوژم.»","«دووەم، دکتۆر هەموو ڕۆژێک دێتە ئێرە بۆ چاودێریکردنی ئەو برینە گەورەی سەرت، جۆن، و دەرمانت پێ دەدات، جۆرج.»","«کەشتییەکی تر دێت، و زۆری نەماوە تا ئەو کاتە.»","«ئەو کاتە دەبینین کێ دڵخۆش دەبێت بە هەبوونی بارمتە.»","«سێیەم، ئێوە داواتان لێکردم ڕێکەوتن بکەم.»","«و ئەگەر ڕێکەوتنم نەکردبایە، هەموومان لە برسان دەمردین.»","«ئەوە بۆیە من ئەو کارەم کرد،» هاواری کرد و کاغەزێکی فڕێدایە بەردەم خۆی.","ئەوە نەخشەی گەنجینەکە بوو، تەواو بە سێ هێمای سوورەکەوە.","یاخیبووەکان خۆیان هەڵدایە سەر نەخشەکە وەک پێنج پشیلە بۆسەر مشکێک.","زۆر بە پەرۆش بوون، وا دەزانی ئەوان بەڕاستی دەستیان بە زێڕەکە گەیشتووە.","هەر زوو، مێری گوتی: «ئەوە زۆر باشە، بەڵام چۆن لێرە بڕۆینە دەر بەبێ کەشتی؟»","«تۆ و پیاوەکانی تر کەشتییەکەتان لەدەست داین،» سیلڤەر بە تووڕەیی گوتی، «و من گەنجینەکەم بۆخۆمان بەدەست هێنا.»","«کێ پیاوێکی باشترە؟»","«من تەواو بووم.»","«کاپتنێکی تر بۆخۆتان هەڵبژێرن.»","«سیلڤەر!» هاواریان کرد، «سیلڤەر بۆ هەمیشە!»","«بەیانی ڕۆژی دواتر، بە هاواری کەسێک بەخەبەر هاتمەوە کە دەیگوت: «ئەوە دکتۆرە.»","کاتێک دکتۆر نزیک بۆوە، سیلڤەر گوتی: «گەورەم، سوپرایزێکی زۆرمان بۆت هەیە.»","کاتێک دکتۆر هاتە ناو خانووە-دارەکە، سەری بەرەو من جولاند و پاشان دەستی کرد بە چاودێریکردنی دوو پیاوە نەخۆشەکە.","کاتێک تەواوی کرد، داوای کرد پێش ڕۆیشتن قسە لەگەڵ من بکات.","«هاوکینز، بەڵێنت پێدەدەیت کە هەڵنەهێیت؟» سیلڤەر گوتی.","بەڵێنم دا هەڵنەهێم، ئەویش ڕازی بوو ڕێگام پێبدات بچمە دەرەوە و لەگەڵ دکتۆر لیڤیسی قسە بکەم.","پێی گوت دکتۆر بڕوات و لە تەنیشت سەنگەرەکە چاوەڕێم بکات.","پیاوەکانی تر زۆر تووڕە بوون و دژی ئەو بڕیارە قسەیان کرد، بەڵام ئێمە چووینە خوارەوە بۆ بینینی دکتۆر.","سیلڤەر پێی گوت: «ژیانی کوڕەکەم ڕزگار کرد، و بۆ ئەوەش نزیک بووم لە کاپتنی لاببرێم؛ ئەویش پێت دەڵێت.","«کەواتە بێگومان قسەیەکی باشم لەگەڵ دەکەیت، وایە؟","«ڕاستگۆ دەبم، من نامەوێت لە سێدارە بدرێم.»","پاشان ئێمەی بەجێهێشت و کەمێک دوورەوە ڕۆیشت.","«جیم،» دکتۆر گوتی، «تۆ چاوەڕێت کرد تا کاپتن سمۆڵێت نەخۆش بێت و هیچ کاری نەکات، پاشان هەڵهاتیت.","«ئەوە کارێکی زۆر ترسنۆکانە بوو.»","«دکتۆر،» گوتم.","«زۆر پەشیمانم و پێموایە هەر لە کۆتاییدا دەمرم.","«ئەگەر سیلڤەر ڕزگاری نەکردبام، تا ئێستا مردبووم.»","«کەواتە خێرا،» وەڵامی دایەوە، «با هەڵبێین.","«یەک بازدان و دەرباز دەبیت!» «نەخێر،» وەڵامم دایەوە، «بەڵێنم داوە و دەبێت بمێنمەوە.»","«بەڵام شتێکت پێدەڵێم، لەوانەیە بمرم.","«کەشتییەکەم بەشێک بە بەخت و بەشێک بە مەترسیکردن بە ژیانم بەدەستم هێناوە.","«لە ئینلێتی باکورە.»","«کەشتییەکە!» دکتۆر گوتی.","پاشان بە خێرایی هەموو ئەوەی ڕوویدابوو بۆی ڕوون کردمەتەوە.","«لە هەموو هەنگاوێکدا،» وەڵامی دایەوە، «ئەوە تۆ بوویت کە ژیانی ئێمەتی ڕزگار کردووە.","«ئێستا ناهێڵین ژیانی خۆت لەدەست بدەیت.","«و دۆزینەوەی بێن گەن باشترین شت بوو کە هەرگیزت کردووە.»","پاشان بانگی سیلڤەری کرد.","«سیلڤەر،» گوتی، «ئامۆژگارییەکت پێدەدەم.","«بۆ بەدەستهێنانی ئەو گەنجینەیە پەلە مەکە.","«و کاتێک دەیدۆزیتەوە، چاوەڕێی کێشە بکە.»","سیلڤەر پرسیاری کرد مەبەستی چییە، بەڵام دکتۆر گوتی: «ناتوانم زیاتر بڵێم.","«ئەو نهێنی من نییە.","«ئەگەر بە زیندوویی لێرە دەربچین، هەموو هەوڵێک دەدەم بۆ ڕزگارکردنت.","«هەروەها شتێکی تر؛ کوڕەکە لە نزیک خۆت بهێڵەوە، و کاتێک پێویستت بە یارمەتی بوو، هاوار بکە.»","متمانەم بە سیلڤەر نەبوو.","بە دڵێکی توندەوە، من بە حەبلێکی درێژەوە بەسترابوومەوە کە سیلڤەر لە دەستیدا بوو، و بەدوای پیاوەکانەوە بووم کاتێک سەرکەوتن بەرەو گردەکە بۆ گەڕان بەدوای گەنجینەکەدا لە نزیک گردی سپای-گلاس.","هەموو پیاوەکان چەند چەکێکیان پێبوو، هەندێکیانیش خاکەناس، کەڵەک و پێداویستییەکانی خواردنیان هەڵگرتبوو.","پیاوەکان بەدوای ڕێنماییە وردەکانی پشتی نەخشەی گەنجینەکە کەوتن.","زەلکاو و دارستانەکەمان تێپەڕاند و دواتر سەرکەوتین بەرەو لوتکە تەختەکەی سپای-گلاس.","یەکێک لە پیاوەکانی پێشەوە لەناکاو لە ترس هاواری کرد.","لە نزیک دارێک، ئێسکە پەیکەرێکی دۆزیبووەوە کە بە شێوەیەکی ناسروشتی ڕاست پاڵکەوتبوو و باسکەکانی بەرەو سەرەوەی سەری درێژ کرابوون.","سیلڤەر ساتێک بیرکردەوە و دواتر داوای لە یەکێک لە پیاوەکان کرد قیبلە نما بێنێت.","جەستەکە ئاراستەی دوورگەی سکێلەت بۆ گردی سپای-گلاس نیشان دەدا.","«پێم وابوو وای بێت،» چێشتلێنەرە دەریاییەکە هاواری کرد، «فلینت ئەو دەریاوانەی کوشتووە و لەشەکەی لێرە بەجێهێشتووە وەک ئاماژەیەک بۆ گەنجینەکە! چ پیاوێکی ترسناک بووە، ئەو فلینتە.»","«ئەو فلینتە چ پیاوێکی ترسناک بوو.»","پیاوەکان لەوە بەدواوە زۆر بێدەنگتر بوون و نزیکتر بە یەکتر ڕۆیشتن.","لەناکاو، لەناو دارەکانی بەردەممانەوە دەنگێکی بەرزی ناسک هات، ئەو گۆرانییەی دەگوت کە ئێمە بە باشی دەمانزانی: «پانزە پیاو لەسەر سندووقی مردوو ـ یۆ-هۆ-هۆ، و بوتڵێک ڕۆم!»","هەرگیز کەسم نەدیوە هێندەی ئەو چەتە دەریاییانە ترسابێت.","یەکێکیان هاواری کرد: «ئەمە ڕۆحی فلینتە!»","بەڵام سیلڤەر هاتە قسە و هاواری کرد: «هاوڕێکانی کەشتی، من ئەو گەنجینەیە بەدەست دەهێنم و هیچ پیاوێک ڕێگریم لێ ناکات، جا مردوو بێت یان زیندوو.»","دوای چەند وشەیەک لە سیلڤەر، پیاوەکان ڕازی بوون بەردەوام بن.","ئێمەش بەدوای دارە بەرزەکەدا گەڕاین کە لەسەر نەخشەکە هێما کرابوو، ئەو شوێنەی گەنجینەکەی لە ژێرەوە شاردراوە.","ئێستا ئەوان خێراتر دەڕۆیشتن و سیلڤەریش پڕ بوو لە پەرۆشی.","زانیم هەموو ئەوەی سیلڤەر دەیویست گەنجینەکە و چوونە دەرەوە بوو لە دوورگەکە، و ئەگەر هەر کەسێک لەسەر ڕێگای بوەستێت، دەیکوژێت.","کاتێک نزیک دارە گەورەکە بووین، پیاوەکان دەستیان کرد بە ڕاکردن و پاشان لەناکاو وەستان.","لەبەردەمماندا چاڵێکی گەورە هەبوو کە تازە هەڵنەکەنرابوو، و زۆر شتی تری لە دەوروبەری نەبوو.","ئەو گەنجینەیەی لە ژێر یەکەم هێمای سووری نەخشەکە بوو، دۆزرابۆوە و بردرابوو!","چەتە دەریاییەکان جنێویان دەدا و هاواریان دەکرد، خۆیان هەڵدایە ناو کونەکە و دەستیان کرد بە هەڵکۆڵین بە دەستەکانیان.","لە کۆتاییدا یەکێکیان تەنها پارچە زێڕێکی دۆزییەوە.","لەو نێوانەدا سیلڤەر بە خێرایی لە سەرسامبوونەکەی چاک بووەوە.","بە بێدەنگی دەمانچەیەکی پێدام و بە شێوەیەکی هاوڕێیانە چرپاندی: «جیم، ئەوە بگرە.","«و ئامادەی کێشە بە.»","هەر لەو کاتەدا، سیلڤەر بە خێرایی لە سەرسام بوونەکەی چاک بووەوە.","پاشان، لەگەڵ ئەوەی منی لەگەڵ خۆی برد، بە هێواشی بەرەو لایەکی تری کونەکە ڕۆیشت.","چەتەکان کە هیچ شتێکی تریان نەدۆزییەوە، لە لای بەرامبەرمانەوە هاتنە دەرەوەی کونەکە.","جۆرج مێری هاواری بۆ سیلڤەر کرد: «ئەوە گەنجینەکەیە، وایە؟»","ڕووی وەرگێڕا و بە چەتەکانی تری گوت: «باشە هاوڕێکان.","«من دەڵێم بیکوژین…» لەو ساتەدا دەنگی تەقەی تفەنگەکان هات و مێری کەوتە ناو کونەکە، یەکێکی تریشی بە مردوویی کەوت و سێ پیاوەکەی تر ڕایانکرد.","لە یەک ساتدا سیلڤەر دووبارە تەقەی لە جۆرج مێری کرد و کوشتی.","دکتۆر، گرەی و بێن گەن لەو کاتەدا لە دارەکانەوە هاتنە دەرەوە بۆ پەیوەستبوونمان.","کاتێک بەرەو بەلەمەکان دەڕۆیشتین، دکتۆر باسی ئەوەی کرد کە چی ڕوویدابوو.","بێن گەن لە ماوەی درێژی مانەوەی لە دوورگەکە، سکێلەتەکە و دواتر گەنجینەکەی دۆزیبووەوە.","هەڵیکۆڵیبووەوە و بار بە بار لەسەر پشتی بردبووی بۆ ئەشکەوتێک کە لە لایەکی تری دوورگەکە دۆزیبوویەوە.","کاتێک دکتۆر ئەمەی بیست و بینی کە کەشتییەکە ڕۆیشتووە، تێگەیشت کە نەخشەکە بێسوودە.","چوو بۆ لای سیلڤەر و نەخشەکە و کەل و پەلەکانی پێدا، چونکە دەیزانی باشترین شوێن بۆ مانەوە ئەشکەوتە نهێنییەکەیە، لەگەڵ گەنجینەکە و خواردنەکانی بێن گەن.","کاتێک دکتۆر لیڤیسی بینی من لەگەڵ یاخیبووەکانم، بە خێرایی ڕایکرد بۆ ئەوەی لەگەڵ بێن گەن لە کەناری کونەکە ئامادە بێت.","کاتێک گەیشتینە بەلەمەکان، دکتۆر بە پاچەکە یەک بەلەمی شکاند، دواتر هەموومان سوار ئەویتریان بووین و دەستمان کرد بە سەوڵ لێدان بۆ هەشت یان نۆ میل بەرەو ئینلێتی باکور.","کاتێک نزیک بووینەوە، بە دەوری گردێکدا سوڕاینەوە و دەمی ڕەشی ئەشکەوتە نهێنییەکەی بێن گەنمان بینی.","کوێخا لەوێ ڕاوەستابوو و چاودێری گەنجینەکەی دەکرد.","بە بینینی لۆنگ جۆن سیلڤەر دڵخۆش دیار نەبوو.","کاپتن سمۆڵێتمان بینی پاڵکەوتووە لەلای ئاگرێک لەناو ئەشکەوتەکە، و لە پشتیەوە کۆیەکی زۆر گەورەی کۆینی زێڕم بینی.","کەواتە ئەمە گەنجینەکەی فلینت بوو.","کەس ناتوانێت بڵێت چەند ئازار و خەم و خوێنی تێچووە، و چەند کەشتی نقووم کراون، تۆپ تەقێنراون و درۆ لەسەر کرابوو.","ئەو شەوە ژەمێکی زۆر خۆشمان خوارد لەگەڵ هەموو هاوڕێکانم کە لە دەوروبەرم بوون.","گۆشتی بزی خوێکراوی بێن گەنمان خوارد و کەمێک مەی لە هیسپانیۆلاوە خواردەوە.","و سیلڤەر لەگەڵمان دانیشتبوو و پێدەکەنی؛ هەمان ئەو چێشتلێنەرە دەریاییە ڕووخۆش و یارمەتیدەر و پێکەنینەی کە لە بریستۆڵ بەجێمانهێشتبوو.","بەیانی ڕۆژی دواتر دەستمان کرد بە گواستنەوەی گەنجینەکە بۆ هیسپانیۆلا.","کارێکی قورس بوو و یەکێکمان دەبوو بە تفەنگێک لەسەر گردەکە ڕاوەستێت و چاودێری سێ یاخیبووە کۆتاییەکان بکات.","ڕۆژ لە دوای ڕۆژ ئەم کارە بەردەوام بوو.","تەنها جارێک گوێمان لە یاخیبووە ماوەکان بوو؛ لە دوورەوە گۆرانییان دەگوت و هاواریان دەکرد.","بڕیارمان دا دەبێت لەسەر دوورگەکە جێیانبهێڵین.","باروت و گوللەی پێویست، زۆربەی گۆشتی بزنەکە، هەندێک دەرمان و هەندێک شتی بەسوودی ترمان بەجێهێشت.","دواتر کەشتییەکەمان ئامادە کرد، لەنگەرەکەمان هەڵکێشا و دەستمان کرد بە ڕۆیشتنە دەر لە ئینلێتی باکور.","دەبوو ئەو سێ پیاوە بە وردییەکی زیاتر چاودێریمان کردبێت لەوەی ئێمە پێمان وابوو.","کاتێک لە ئینلێتەکە چووینە دەر، سێ یاخیبووەکە لە کەنارەکە بوون.","لەسەر ئەژنۆکانیان بوون و بانگیان دەکرد و داوای ڕزگارکردنیان دەکرد.","دکتۆر هاواری بۆ کردن و پێی گوتن لە کوێ دەتوانن ئەو کەل و پەلەیە بدۆزنەوە کە ئێمە جێمانهێشتووە.","بەڵام بەردەوام بوون لە هاوارکردن، پاشان یەکێکیان تەقەیەکی کرد.","بە هێواشی لە چاو ون بوون، و تا نیوەڕۆ بەرزترین تاشەبەردی دوورگەی گەنجینەکە بچووک بووەوە و لەناو دەریای شینەکەدا نقوم بوو.","خۆر تازە دەچووە ناو ئاوەکە کە ئێمە لەنگەرمان لە کەنداوێکی جوانی مەکسیک بەردایەوە.","چەندین بەلەمی بچووک بەرەو ئێمە هاتن، پڕ بوون لە خەڵکێک کە جۆرە جۆر میوە و سەوزەی ڕەنگاوڕەنگیان دەفرۆشت.","دیمەنی ئەو هەموو ڕووخسارە پێکەنیناوانە، تامی ئەو میوە سەرنجڕاکێشانە و ئەو ڕووناکییانەی کە دەستیان کردبوو بە درەوشانەوە لە شارۆچکەکە، گۆڕانکارییەکی سەرنجڕاکێش بوو بە بەراورد بە کاتە تاریک و ترسناکەکانمان لە دوورگەکە.","دکتۆر و کوێخا بڕیاریان دا بۆ ئێوارە بچنە کەناراوە، و منیشیان لەگەڵ خۆیان برد.","کاتێک گەڕاینەوە، سیلڤەر ڕۆیشتبوو و یەکێک لە کیسەکانی کۆینەکانی لەگەڵ خۆی بردبوو.","پێم وایە هەموومان دڵخۆش بووبین کە ئاوا بە ئاسانی ڕزگارمان بوو لە دەستی.","بۆ ئەوەی چیرۆکەکە کورت بکەینەوە، هەندێک دەریاوانی زیاترمان دۆزییەوە، گەشتێکی خۆشمان کرد بەرەو ماڵەوە و هیسپانیۆلا لە کۆتایی هاوین گەیشتە بریستۆڵ.","تەنها پێنج پیاو لەوانەی لە بریستۆڵەوە بە کەشتییەکە چووبوون، لەگەڵ کەشتییەکە گەڕانەوە.","«خواردنەوە و شەیتان کاری ئەوانی تریان تەواو کرد،» بەڵام ئێمە لەو حاڵە خراپەدا نەبووین وەک ئەو کەشتییەی تر کە گۆرانییەکەیان دەربارەی گوتبوو: «تەنها یەک پیاو لە تاقمەکەی زیندووە، ئەوەی بە حەفتا و پێنج کەسەوە چووبووە ناو دەریا.»","هەموومان بەشێکی باشمان لە گەنجینەکە بەرکەوت، و بە پێی کەسەکە بە باشی یان بە خراپی بەکارمان هێنا.","کاپتن سمۆڵێت ئێستا لە دەریا خانەنشین بووە.","گرەی پارەکەی خۆی پاشەکەوت کرد و خوێندی بۆ ئەوەی ببێتە دەریاوان.","هەروەها هاوسەرگیری کرد و منداڵی هەبوو.","بێن گەن هەزار پاوەندی بەدەستهێنا، کە لە ماوەی نۆزدە ڕۆژدا سەرفی کرد یان لەدەستی دا.","پاشان ڕۆیشت بۆ ئەوەی لە گوندێک بژی، ئەو شوێنە هێشتا هەموو یەکشەممەیەک لە کڵێسە گۆرانی دەڵێت.","هیچ شتێکی تریمان دەربارەی سیلڤەر نەبیست.","ئەو دەریاوانە خراپە یەک قاچە لە کۆتاییدا لە ژیانم چووە دەرەوە.","هیوادارم لە شوێنێکی ئەم جیهانە بە دڵخۆشی بژیێت، چونکە دڵنیام لە جیهانی داهاتوودا دڵخۆش نابێت.","زیو و چەکەکان هێشتا لەوێ شاردراونەتەوە، ئەوەندەی من بزانم، هەر لەو شوێنەی کە فلینت لێی شاردبوونەوە.","بەڵام هەرگیز ناگەڕێمەوە بۆ ئەو دوورگەیە، و خراپترین ئەو خەونانەی کە تا ئێستا دەیانبینم ئەو کاتەیە کە ئەو کەنارە بەرداویە ترسناکە دەبینم، یان کاتێک لەناکاو لە جێگای خەوتنم هەستم دەکەم و دەنگی قورس و بەرزی کاپتن فلینت هێشتا لە گوێمدا دەچڕێنێت: «پیسز ئەڤ ئەێیت!","پیسز ئەڤ ئەێیت!»"];;
const $=s=>document.querySelector(s), book=$('#book'), panel=$('#panel');
const S=[]; let cur=-1, mode='listen', slow=false;

// دروستکردنی پەرتووکەکە
DATA.forEach(ep=>{
  const sec=document.createElement('section'); sec.className='ep'; sec.id='ep'+ep.n;
  sec.innerHTML=`<h2>Episode ${ep.n}: ${ep.title}</h2>`;
  ep.items.forEach(it=>{
    if(it.t==='h'){const h=document.createElement('h3');h.textContent=it.s;sec.appendChild(h);return;}
    const p=document.createElement('p');
    it.s.forEach(t=>{const sp=document.createElement('span');sp.className='s';sp.textContent=t;sp.dataset.i=S.length;S.push({t,el:sp});p.append(sp,' ');});
    sec.appendChild(p);
  });
  book.appendChild(sec);
  const a=document.createElement('a');a.href='#ep'+ep.n;a.textContent='ئەپیسۆدی '+ep.n;a.dataset.n=ep.n;$('#eps').appendChild(a);
});
book.addEventListener('click',e=>{const s=e.target.closest('.s');if(s)open(+s.dataset.i)});

function open(i){
  if(i<0||i>=S.length)return;
  speechSynthesis.cancel();
  if(cur>=0)S[cur].el.classList.remove('on','speaking');
  cur=i;S[i].el.classList.add('on');
  panel.hidden=false;
  $('#pos').textContent=`رستەی ${i+1} لە ${S.length}`;
  $('#sent').textContent=S[i].t;
  S[i].el.scrollIntoView({block:'center',behavior:'smooth'});
  render();
}
function speak(t,el){
  speechSynthesis.cancel();
  const u=new SpeechSynthesisUtterance(t.replace(/[‘’]/g,"'"));
  u.lang='en-GB';u.rate=slow?.65:.95;
  const v=speechSynthesis.getVoices().find(v=>/^en/i.test(v.lang));if(v)u.voice=v;
  u.onstart=()=>el.classList.add('speaking');u.onend=u.onerror=()=>el.classList.remove('speaking');
  speechSynthesis.speak(u);
}
function h(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
function hash(n){let x=(n+1)*2654435761>>>0;x^=x>>>15;return x>>>0}

const STOP=new Set('about after again against always because before being between could didn’t doesn’t during every from have having himself into itself might never other should since still their there these they’re those through under until very were what when where which while with without would your'.split(' '));
let POOL=null;
function pool(){if(POOL)return POOL;const m=new Set();S.forEach(s=>(s.t.match(/[A-Za-z]+/g)||[]).forEach(w=>{w=w.toLowerCase();if(w.length>=4&&!STOP.has(w))m.add(w)}));return POOL=[...m]}
function quiz(i){
  const t=S[i].t, ws=[...t.matchAll(/[A-Za-z]+/g)];
  let c=ws.filter(m=>m[0].length>=5&&!STOP.has(m[0].toLowerCase()));
  if(!c.length)c=ws.filter(m=>m[0].length>=3);
  if(!c.length)return null;
  const m=c[hash(i)%c.length], ans=m[0], low=ans.toLowerCase();
  const P=pool().filter(w=>w!==low&&Math.abs(w.length-low.length)<=1&&w[0]!==low[0]);
  const d=[];for(let k=0;d.length<2&&k<200;k++){const w=P[hash(i*7+k)%P.length];if(w&&!d.includes(w))d.push(w)}
  const cap=/^[A-Z]/.test(ans);
  const fix=w=>cap?w[0].toUpperCase()+w.slice(1):w;
  const opts=[ans,...d.map(fix)].sort((a,b)=>hash(i+a.length*31+a.charCodeAt(0))-hash(i+b.length*31+b.charCodeAt(0)));
  return {text:t.slice(0,m.index)+'_____'+t.slice(m.index+ans.length),ans,opts};
}
function render(){
  const o=$('#out'), t=S[cur].t;
  document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('on',b.dataset.m===mode));
  if(mode==='listen'){
    o.innerHTML='<div class="pl"><button id="play">▶ گوێبگرە</button><button id="sl" class="ghost">'+(slow?'خێرایی ئاسایی':'هێواشتر')+'</button></div><p class="note">ئەگەر دەنگ نەهات، لە وێبگەڕی Chrome یان Edge بیکەرەوە.</p>';
    $('#play').onclick=()=>speak(t,S[cur].el);
    $('#sl').onclick=()=>{slow=!slow;render();speak(t,S[cur].el)};
    speak(t,S[cur].el);
  }else if(mode==='ku'){
    const k=KU[cur];
    o.innerHTML=k?`<p class="ku">${h(k)}</p>`:`<p class="note">وەرگێڕانی ئەم ڕستەیە هێشتا لە فایلی script.js زیاد نەکراوە.</p>`;
  }else{
    const q=quiz(cur);
    if(!q){o.innerHTML='<p class="note">بۆ ئەم رستەیە پرسیار نییە.</p>';return}
    o.innerHTML=`<p class="q">📝 لەوانەیە لە تاقیکردنەوە بەم شێوازە بێتەوە: وشە ونبووەکە هەڵبژێرە</p><div class="blank">${h(q.text)}</div><div class="opts">${q.opts.map(x=>`<button>${h(x)}</button>`).join('')}</div><p class="res"></p>`;
    o.querySelectorAll('.opts button').forEach(b=>b.onclick=()=>{
      o.querySelectorAll('.opts button').forEach(x=>{x.disabled=true;if(x.textContent===q.ans)x.classList.add('ok')});
      const good=b.textContent===q.ans;if(!good)b.classList.add('bad');
      o.querySelector('.res').textContent=good?'✔ ڕاستە! ئافەرین':'✘ هەڵەیە — وەڵامی ڕاست: '+q.ans;
    });
  }
}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{mode=b.dataset.m;render()});
$('#prev').onclick=()=>open(cur-1);$('#next').onclick=()=>open(cur+1);
$('#close').onclick=()=>{panel.hidden=true;speechSynthesis.cancel();if(cur>=0)S[cur].el.classList.remove('on','speaking');cur=-1};
document.addEventListener('keydown',e=>{if(panel.hidden)return;if(e.key==='Escape')$('#close').click();if(e.key==='ArrowRight')open(cur+1);if(e.key==='ArrowLeft')open(cur-1)});

// ڕێکخستنەکان
const root=document.documentElement;let fs=+localStorage.getItem('fs')||1.18;
const setFs=v=>{fs=Math.min(1.6,Math.max(.95,v));root.style.setProperty('--fs',fs+'rem');try{localStorage.setItem('fs',fs)}catch(e){}};setFs(fs);
$('#fPlus').onclick=()=>setFs(fs+.08);$('#fMinus').onclick=()=>setFs(fs-.08);
try{root.dataset.t=localStorage.getItem('t')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light')}catch(e){}
$('#theme').onclick=()=>{root.dataset.t=root.dataset.t==='dark'?'light':'dark';try{localStorage.setItem('t',root.dataset.t)}catch(e){}};
addEventListener('scroll',()=>{const d=root;$('#bar').style.transform=`scaleX(${scrollY/(d.scrollHeight-innerHeight||1)})`;
  let on=1;DATA.forEach(e=>{if($('#ep'+e.n).getBoundingClientRect().top<innerHeight*.4)on=e.n});
  document.querySelectorAll('#eps a').forEach(a=>a.classList.toggle('on',+a.dataset.n===on))},{passive:true});
speechSynthesis.onvoiceschanged=()=>{};
